INSERT INTO "asset"("id","kind","name","slug","source","licence","url","tile_m","colour","category","variants","period_from","period_to","confidence","note","extra_json","origin_file","origin_path") VALUES('composite:frame','composite','frame','plastered_wall','Poly Haven','CC0 1.0 — https://polyhaven.com/license','https://polyhaven.com/a/plastered_wall',3.0,NULL,NULL,NULL,NULL,NULL,NULL,'Timber-frame wall: scanned lime plaster with oak framing drawn over it at load time (frame-* with a painted window, for distant houses; fwall-* bay designs without windows, for modelled houses). See src/scene/street/frameTex.ts.','{"beams": "rough_wood"}','assets.json','$.composites.frame');
INSERT INTO "asset"("id","kind","name","slug","source","licence","url","tile_m","colour","category","variants","period_from","period_to","confidence","note","extra_json","origin_file","origin_path") VALUES('model:island_tree_01','model','Gnarled broadleaf (coastal)','island_tree_01','Poly Haven','CC0 1.0 — https://polyhaven.com/license','https://polyhaven.com/a/island_tree_01',NULL,NULL,'tree',NULL,-4000,1625,'low','Species not stated by Poly Haven: a wind-sculpted coastal broadleaf with a gnarled trunk and small leaves. Not an oak or beech; at mid/far range it reads as a generic hedgerow or wood-edge tree (hawthorn, field maple, crab apple). Use as a stand-in only; keep away from close-up camera positions.',NULL,'models.json','$.assets[0]');
INSERT INTO "asset"("id","kind","name","slug","source","licence","url","tile_m","colour","category","variants","period_from","period_to","confidence","note","extra_json","origin_file","origin_path") VALUES('model:island_tree_02','model','Small twisted broadleaf','island_tree_02','Poly Haven','CC0 1.0 — https://polyhaven.com/license','https://polyhaven.com/a/island_tree_02',NULL,NULL,'tree',NULL,-4000,1625,'low','Species not stated; small twisted trunk with a spreading dense canopy. Reads as an old hawthorn or pollard at distance. Stand-in, not a named British species.',NULL,'models.json','$.assets[1]');
INSERT INTO "asset"("id","kind","name","slug","source","licence","url","tile_m","colour","category","variants","period_from","period_to","confidence","note","extra_json","origin_file","origin_path") VALUES('model:island_tree_03','model','Low windswept broadleaf','island_tree_03','Poly Haven','CC0 1.0 — https://polyhaven.com/license','https://polyhaven.com/a/island_tree_03',NULL,NULL,'tree',NULL,-4000,1625,'low','Species not stated; low windswept multi-trunk tree on exposed roots. Reads as scrub (blackthorn/hawthorn thicket) or a coppice stool at distance. Stand-in only.',NULL,'models.json','$.assets[2]');
INSERT INTO "asset"("id","kind","name","slug","source","licence","url","tile_m","colour","category","variants","period_from","period_to","confidence","note","extra_json","origin_file","origin_path") VALUES('model:tree_small_02','model','Slender young broadleaf','tree_small_02','Poly Haven','CC0 1.0 — https://polyhaven.com/license','https://polyhaven.com/a/tree_small_02',NULL,NULL,'tree',NULL,-4000,1625,'low','FLAGGED: Poly Haven tags it Burkea africana (an African savanna tree), not a British species. Kept as a slender-trunk, airy-canopy form that reads like a young birch or rowan at mid/far range. Do not use for close-ups; prefer the procedural trees where species matters.',NULL,'models.json','$.assets[3]');
INSERT INTO "asset"("id","kind","name","slug","source","licence","url","tile_m","colour","category","variants","period_from","period_to","confidence","note","extra_json","origin_file","origin_path") VALUES('model:pine_sapling_small','model','Pine sapling','pine_sapling_small','Poly Haven','CC0 1.0 — https://polyhaven.com/license','https://polyhaven.com/a/pine_sapling_small',NULL,NULL,'tree',3,-4000,1625,'medium','Pine of unstated species; form fits Scots pine (Pinus sylvestris, native). Use SPARINGLY: Scots pine was largely gone from lowland southern England after the mid-Holocene and was replanted mostly after 1625; plausible on prehistoric heath and sandy commons only.','{"budget": {"lod0": 6000, "lod1": 1500, "lod2": 8}}','models.json','$.assets[4]');
INSERT INTO "asset"("id","kind","name","slug","source","licence","url","tile_m","colour","category","variants","period_from","period_to","confidence","note","extra_json","origin_file","origin_path") VALUES('model:pine_sapling_medium','model','Young pine','pine_sapling_medium','Poly Haven','CC0 1.0 — https://polyhaven.com/license','https://polyhaven.com/a/pine_sapling_medium',NULL,NULL,'tree',3,-4000,1625,'medium','As pine_sapling_small: reads as a young Scots pine. Sparingly, prehistoric heathland only; not a London street or Thames-side tree in the historic periods.',NULL,'models.json','$.assets[5]');
