INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:barnet/road-london-barnet-hadley:located_at','landmark','barnet/road-london-barnet-hadley','Road from London through Barnet to the fork (Great North Road)','barnet','located_at',NULL,NULL,'Road from London through Barnet to the fork (Great North Road)','The main road north from London climbed Barnet Hill, ran through the market town past its chapel, and crossed Hadley Green to a fork where the Hadley Highstone now stands. Both armies came this way.',51.6562,-0.2019,'attested-documentary','medium','bar-barnet-battlefield-project-2015-2018,bar-vch-herts-barnet,bar-osm-overpass',3,'locations/barnet/landmarks.json','$[0]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:barnet/road-st-albans:located_at','landmark','barnet/road-st-albans','St Albans road (now Kitts End Road)','barnet','located_at',NULL,NULL,'St Albans road (now Kitts End Road)','The road from London to St Albans, the Midlands and the north-west: the left-hand branch at the fork, running north-west past Kitts End to Dancers Hill. In 1471 this was the great road, and Warwick''s army had marched down it from St Albans; today it is a country lane.',51.6728,-0.2034,'attested-documentary','medium','bar-barnet-battlefield-project-2015-2018,bar-vch-middx-south-mimms-intro,bar-watson-2022-looking-for-the-site,bar-osm-overpass',4,'locations/barnet/landmarks.json','$[1]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:barnet/road-hatfield:located_at','landmark','barnet/road-hatfield','Hatfield road (later the Great North Road)','barnet','located_at',NULL,NULL,'Hatfield road (later the Great North Road)','The right-hand branch at the fork, heading north-east to Potters Bar, Hatfield and the north along the edge of Enfield Chase.',51.6722,-0.1937,'reconstructed','low','bar-barnet-battlefield-project-2015-2018,bar-vch-middx-south-mimms-intro,bar-osm-overpass',3,'locations/barnet/landmarks.json','$[2]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:barnet/road-wood-street:located_at','landmark','barnet/road-wood-street','Wood Street (road west to Barnet Common)','barnet','located_at',NULL,NULL,'Wood Street (road west to Barnet Common)','The lane branching west at Barnet chapel, widening as a drove towards Barnet Common.',51.6528,-0.2123,'reconstructed','low','bar-barnet-battlefield-project-2015-2018,bar-vch-herts-barnet,bar-osm-overpass',3,'locations/barnet/landmarks.json','$[3]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:barnet/lane-hadley-church:located_at','landmark','barnet/lane-hadley-church','Lane from the green to Hadley church','barnet','located_at',NULL,NULL,'Lane from the green to Hadley church','A lane from the main road across the east side of the green to the church at the edge of Enfield Chase.',51.6614,-0.1955,'conjectural','low','bar-osm-overpass,bar-vch-middx-monken-hadley-intro',2,'locations/barnet/landmarks.json','$[4]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:barnet/monken-mead-brook:located_at','landmark','barnet/monken-mead-brook','Monken Mead Brook','barnet','located_at',NULL,NULL,'Monken Mead Brook','A small stream rising north of Hadley church and running east through a shallow valley inside Enfield Chase. One contemporary newsletter puts Edward''s army in a hollow or marsh; this valley is the usual candidate.',51.6676,-0.1896,'reconstructed','low','bar-barnet-battlefield-project-2015-2018,bar-battlefields-trust-barnet,bar-osm-overpass',3,'locations/barnet/landmarks.json','$[5]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:barnet/margery-mead-stream:located_at','landmark','barnet/margery-mead-stream','Stream at the head of Margery Mead','barnet','located_at',NULL,NULL,'Stream at the head of Margery Mead','A stream falling north-west from the Kitts End side of the ridge into the broad, flat valley called Margery Mead, which may have been marshy before modern drainage.',51.6732,-0.2139,'reconstructed','low','bar-barnet-battlefield-project-2015-2018,bar-osm-overpass',2,'locations/barnet/landmarks.json','$[6]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:barnet/gannick-bank:located_at','landmark','barnet/gannick-bank','Gannick Bank (boundary of Enfield Chase)','barnet','located_at',NULL,NULL,'Gannick Bank (boundary of Enfield Chase)','The bank and hedge that divided Enfield Chase from the commons outside it, running north from Hadley towards Potters Bar beside the Hatfield road. If it was still a substantial hedged bank in 1471 it would have been a serious obstacle on the east side of the field.',51.669,-0.1952,'reconstructed','low','bar-barnet-battlefield-project-2015-2018',1,'locations/barnet/landmarks.json','$[7]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:barnet/hedge-side-hadley:located_at','landmark','barnet/hedge-side-hadley','A possible ''hedge-side'' on the Hadley Green interpretation','barnet','located_at',NULL,NULL,'A possible ''hedge-side'' on the Hadley Green interpretation','The Arrivall says Warwick''s men were drawn up ''under a hedge-side'' rather more than half a mile from Barnet. On the Hadley Green interpretation that hedge ran east–west near the north edge of the green; A. H. Burne thought he could identify it beside Old Fold.',51.6631,-0.201,'conjectural','low','bar-arrivall-part-3,bar-barnet-battlefield-project-2015-2018,bar-wikipedia-battle-of-barnet',3,'locations/barnet/landmarks.json','$[8]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:barnet/hedge-kicks-end-closes:located_at','landmark','barnet/hedge-kicks-end-closes','Edge of the closes north of Kicks End Common','barnet','located_at',NULL,NULL,'Edge of the closes north of Kicks End Common','Hedged closes lay north of the common by 1479. The survey report''s simplest reading of the sources puts Warwick''s line behind this boundary, facing south across the common, with a frontage of about 650 m between the two roads.',51.6737,-0.1968,'conjectural','low','bar-barnet-battlefield-project-2015-2018',1,'locations/barnet/landmarks.json','$[9]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:barnet/hedge-old-fold-east:located_at','landmark','barnet/hedge-old-fold-east','Edge of the Old Fold estate beside the green','barnet','located_at',NULL,NULL,'Edge of the Old Fold estate beside the green','Old Fold was a compact, fully hedged estate when first mapped in 1726, with its moated house at the eastern edge next to Hadley Green.',51.6631,-0.2012,'conjectural','low','bar-barnet-battlefield-project-2015-2018,bar-vch-middx-south-mimms-manors',2,'locations/barnet/landmarks.json','$[10]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:barnet/barnet-church:located_at','landmark','barnet/barnet-church','Chapel of St John the Baptist, Chipping Barnet','barnet','located_at',NULL,NULL,'Chapel of St John the Baptist, Chipping Barnet','The town''s church, standing at the angle where Wood Street leaves the High Street on the crest of the ridge, about 400 ft (122 m) above sea level. A chapel of St John is recorded here in 1361; it was largely rebuilt in the first half of the 15th century and was treated as a parish church by the time of the battle.',51.65317,-0.20092,'reconstructed','medium','bar-vch-herts-barnet,bar-osm-overpass',2,'locations/barnet/landmarks.json','$[11]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:barnet/hadley-church:located_at','landmark','barnet/hadley-church','St Mary''s church, Monken Hadley','barnet','located_at',NULL,NULL,'St Mary''s church, Monken Hadley','The parish church of Hadley, on the plateau at the edge of Enfield Chase east of the green. Hadley is listed as a parish church about 1175 and a hermitage ''in the park of Hadley'' is recorded about 1136. The church that stood here on the day of the battle was replaced about 1494 by the present building, which carries that date on its west tower.',51.6616,-0.1939,'reconstructed','medium','bar-vch-middx-monken-hadley-church,bar-vch-middx-monken-hadley-intro,bar-listing-st-mary-monken-hadley,bar-wikipedia-st-mary-monken-hadley,bar-barnet-battlefield-project-2015-2018',5,'locations/barnet/landmarks.json','$[12]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:barnet/old-fold-manor:located_at','landmark','barnet/old-fold-manor','Old Fold manor house (moated)','barnet','located_at',NULL,NULL,'Old Fold manor house (moated)','A moated manor house at the north-west corner of Hadley Green, held by the Frowyk family of London merchants from soon after 1271 until 1527. A manor house is mentioned in 1310 and three sides of its moat survive beside the golf club house. It was certainly standing in 1471 and, on the Hadley Green interpretation, lay in or just behind Warwick''s line.',51.6644,-0.2017,'reconstructed','low','bar-vch-middx-south-mimms-manors,bar-vch-middx-south-mimms-intro,bar-barnet-battlefield-project-2015-2018,bar-osm-overpass',4,'locations/barnet/landmarks.json','$[13]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:barnet/battle-chapel:located_at','landmark','barnet/battle-chapel','Chapel for the dead of the battle (site not proven)','barnet','located_at',NULL,NULL,'Chapel for the dead of the battle (site not proven)','The Great Chronicle of London (about 1512) says the common dead were buried on the plain and that a little chapel was afterwards built there to remember their souls. A will suggests it was still in use in 1519–20; by Stow''s day it had become a house. Since 1970 it has been identified with ''the Hermitage'', a moated site on the former Kicks End Common, one arm of whose moat survives as a pond.',51.6719,-0.1961,'conjectural','low','bar-barnet-battlefield-project-2015-2018,bar-watson-2022-looking-for-the-site,bar-vch-middx-south-mimms-intro,bar-barnet-society-2021',4,'locations/barnet/landmarks.json','$[14]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:barnet/zone-registered:located_at','landmark','barnet/zone-registered','Registered battlefield area (Hadley Green)','barnet','located_at',NULL,NULL,'Registered battlefield area (Hadley Green)','The area registered as the battlefield by English Heritage in 1995, following a National Army Museum report: Hadley Green, Old Fold and the ground north of Monken Hadley. Its northern edge is a little over half a mile from Barnet, matching the Arrivall''s distance.',51.663,-0.199,'conjectural','low','bar-barnet-battlefield-project-2015-2018,bar-battlefields-trust-barnet,bar-wikipedia-battle-of-barnet',3,'locations/barnet/landmarks.json','$[15]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:barnet/zone-kitts-end:located_at','landmark','barnet/zone-kitts-end','Kitts End: the 2015–18 survey''s alternative site','barnet','located_at',NULL,NULL,'Kitts End: the 2015–18 survey''s alternative site','The former Kicks End Common and its surroundings, between the St Albans and Hatfield roads north of the fork: a level hilltop of open common, about 1.9 km from the Barnet boundary, edged by hedged closes on the north and the bank of Enfield Chase on the east, with the Monken Mead valley falling away to the south-east. The survey report judged that this ground ''most closely'' fits the written accounts, and the putative battle chapel lies on it.',51.6712,-0.197,'conjectural','low','bar-barnet-battlefield-project-2015-2018,bar-watson-2022-looking-for-the-site,bar-battlefields-trust-barnet,bar-barnet-society-2021',4,'locations/barnet/landmarks.json','$[16]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:barnet/troops-lanc-right:located_at','landmark','barnet/troops-lanc-right','Lancastrian right (Oxford)','barnet','located_at',NULL,NULL,'Lancastrian right (Oxford)','Stand-in for the western wing of Warwick''s army, which the sources agree overlapped and routed the king''s left; its men chased the fugitives towards Barnet and, returning in the mist, were taken for enemies by their own side. That the Earl of Oxford led the attack is attested; that this was the ''right wing'' is inference.',51.6636,-0.20552,'conjectural','low','bar-barnet-battlefield-project-2015-2018,bar-arrivall-part-3,bar-wikipedia-battle-of-barnet,bar-battlefields-trust-barnet',4,'locations/barnet/landmarks.json','$[17]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:barnet/troops-lanc-centre:located_at','landmark','barnet/troops-lanc-centre','Lancastrian centre (Montagu)','barnet','located_at',NULL,NULL,'Lancastrian centre (Montagu)','Stand-in for the middle of Warwick''s line. Modern accounts put John Neville, Marquess Montagu, here and Warwick himself with a reserve behind; no contemporary source says where either stood. Both were killed.',51.6636,-0.20219,'conjectural','low','bar-barnet-battlefield-project-2015-2018,bar-arrivall-part-3,bar-wikipedia-battle-of-barnet,bar-battlefields-trust-barnet',4,'locations/barnet/landmarks.json','$[18]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:barnet/troops-lanc-left:located_at','landmark','barnet/troops-lanc-left','Lancastrian left (Exeter)','barnet','located_at',NULL,NULL,'Lancastrian left (Exeter)','Stand-in for the eastern wing of Warwick''s army, which the king''s line overlapped. The Duke of Exeter was badly wounded and left for dead; his place on the left is a modern inference.',51.6636,-0.19886,'conjectural','low','bar-barnet-battlefield-project-2015-2018,bar-arrivall-part-3,bar-wikipedia-battle-of-barnet,bar-battlefields-trust-barnet',4,'locations/barnet/landmarks.json','$[19]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:barnet/troops-york-left:located_at','landmark','barnet/troops-york-left','Yorkist left (Hastings)','barnet','located_at',NULL,NULL,'Yorkist left (Hastings)','Stand-in for the western end of the king''s line, which was overlapped, broken and driven back through Barnet towards London. Lord Hastings led the rearward, which later sources place here.',51.6611,-0.20233,'conjectural','low','bar-barnet-battlefield-project-2015-2018,bar-arrivall-part-3,bar-wikipedia-battle-of-barnet,bar-battlefields-trust-barnet',4,'locations/barnet/landmarks.json','$[20]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:barnet/troops-york-centre:located_at','landmark','barnet/troops-york-centre','Yorkist centre (Edward IV)','barnet','located_at',NULL,NULL,'Yorkist centre (Edward IV)','Stand-in for the king''s own division. The Arrivall, written by a servant of the king, describes Edward fighting in the midst of the press.',51.6611,-0.199,'conjectural','low','bar-barnet-battlefield-project-2015-2018,bar-arrivall-part-3,bar-wikipedia-battle-of-barnet,bar-battlefields-trust-barnet',4,'locations/barnet/landmarks.json','$[21]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:barnet/troops-york-right:located_at','landmark','barnet/troops-york-right','Yorkist right (Gloucester)','barnet','located_at',NULL,NULL,'Yorkist right (Gloucester)','Stand-in for the eastern end of the king''s line, which overlapped the enemy''s. Richard, Duke of Gloucester, aged eighteen, led the vanguard, conventionally placed on the right.',51.66065,-0.19567,'conjectural','low','bar-barnet-battlefield-project-2015-2018,bar-arrivall-part-3,bar-wikipedia-battle-of-barnet,bar-battlefields-trust-barnet',4,'locations/barnet/landmarks.json','$[22]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:brentford/thames-ford:located_at','landmark','brentford/thames-ford','Thames ford (line conjectural)','brentford','located_at',NULL,NULL,'Thames ford (line conjectural)','A crossing of the Thames by wading. The Anglo-Saxon Chronicle has Edmund ''go over at Brentford'' and later ''ford over the Thames at Brentford'' in 1016, so a usable ford existed. The county history thinks the lowest permanent ford on the Thames was probably at Old England, the low ground by the Brent mouth; that is where it is drawn.',51.4803,-0.3022,'reconstructed','low','bre-asc-avalon,bre-vch-mdx7-comms,bre-vch-mdx7-growth,bre-bclhs-brentford-bridge,bre-wheeler-old-england,bre-brentfordhistory-to-793,bre-tdp-foreshore-pioneers',7,'locations/brentford/landmarks.json','$[0]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:brentford/river-brent:located_at','landmark','brentford/river-brent','River Brent','brentford','located_at',NULL,NULL,'River Brent','The tributary that gives Brentford its name, joining the Thames from the north. Alluvium lies along it and at its mouth.',51.4838,-0.3099,'reconstructed','medium','bre-vch-mdx7-intro,bre-vch-mdx3-heston-isleworth,bre-wikipedia-brentford-dock,bre-osm-nominatim',4,'locations/brentford/landmarks.json','$[1]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:brentford/brent-ford:located_at','landmark','brentford/brent-ford','Crossing of the Brent on the west road','brentford','located_at',NULL,NULL,'Crossing of the Brent on the west road','Where the road west from London crossed the Brent. The name Brentford, recorded from 705, is usually taken to mean this ford. A bridge is first recorded in 1224, long after this window, so a ford is shown.',51.4823,-0.3124,'reconstructed','low','bre-vch-mdx7-growth,bre-vch-mdx7-comms,bre-bclhs-brentford-bridge',3,'locations/brentford/landmarks.json','$[2]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:brentford/west-road-east:located_at','landmark','brentford/west-road-east','Road from London (later Brentford High Street)','brentford','located_at',NULL,NULL,'Road from London (later Brentford High Street)','The main road from London to the west, successor to the Roman road to Silchester, running along the gravel just above the Thames to the Brent crossing.',51.4862,-0.298,'reconstructed','low','bre-vch-mdx7-comms,bre-vch-mdx7-growth,bre-vch-mdx3-heston-isleworth,bre-osm-nominatim',4,'locations/brentford/landmarks.json','$[3]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:brentford/west-road-west:located_at','landmark','brentford/west-road-west','Road to the west (towards Staines)','brentford','located_at',NULL,NULL,'Road to the west (towards Staines)','The same road beyond the Brent, through the later Brentford End towards Hounslow and Staines. The county history calls the London to Staines road probably the oldest man-made feature of the district.',51.48,-0.3195,'reconstructed','low','bre-vch-mdx7-comms,bre-vch-mdx7-growth,bre-vch-mdx3-heston-isleworth,bre-osm-nominatim',4,'locations/brentford/landmarks.json','$[4]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:brentford/ford-track:located_at','landmark','brentford/ford-track','Track to the Thames ford (conjectural)','brentford','located_at',NULL,NULL,'Track to the Thames ford (conjectural)','A way from the west road to the head of the Thames ford, keeping west and south of the Brent''s last bend.',51.4802,-0.3095,'conjectural','low','bre-vch-mdx7-comms',1,'locations/brentford/landmarks.json','$[5]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:brentford/fields-old-brentford:located_at','landmark','brentford/fields-old-brentford','Arable north of the road (conjectural)','brentford','located_at',NULL,NULL,'Arable north of the road (conjectural)','Ploughed strips on the brickearth and gravel above the road, standing for the farmland of the bishop of London''s manor.',51.4877,-0.3021,'conjectural','low','bre-vch-mdx7-growth,bre-vch-mdx7-econ,bre-vch-mdx7-intro',3,'locations/brentford/landmarks.json','$[6]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:brentford/fields-isleworth:located_at','landmark','brentford/fields-isleworth','Arable west of the Brent (conjectural)','brentford','located_at',NULL,NULL,'Arable west of the Brent (conjectural)','Ploughed strips south of the west road, standing for the large arable of the manor of Isleworth, which Domesday Book credits with land for 55 ploughs.',51.479,-0.317,'conjectural','low','bre-opendomesday-isleworth,bre-vch-mdx3-heston-isleworth',2,'locations/brentford/landmarks.json','$[7]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:brentford/fishing-boats:located_at','landmark','brentford/fishing-boats','Fishing boats (illustrative)','brentford','located_at',NULL,NULL,'Fishing boats (illustrative)','A few small boats off Old Brentford. A Thames fishery at Brentford existed by 996, when the king granted half of it to Winchester; later records speak of weirs.',51.4846,-0.2966,'conjectural','low','bre-vch-mdx7-econ,bre-vch-mdx7-growth',2,'locations/brentford/landmarks.json','$[8]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:brentford/marker-crossing:located_at','landmark','brentford/marker-crossing','Possible crossing, 1016 (conjectural)','brentford','located_at',NULL,NULL,'Possible crossing, 1016 (conjectural)','A shaded band over the ford as drawn: one place where Edmund''s army may have crossed the Thames in 1016.',51.4803,-0.3022,'conjectural','low','bre-asc-avalon,bre-vch-mdx7-comms',2,'locations/brentford/landmarks.json','$[9]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:brentford/marker-crossing-alt:located_at','landmark','brentford/marker-crossing-alt','Another possible crossing, 1016 (conjectural)','brentford','located_at',NULL,NULL,'Another possible crossing, 1016 (conjectural)','A second shaded band, on the line of the later Kew ferry from Old Brentford, shown to make plain that the crossing place is not known.',51.4834,-0.2982,'conjectural','low','bre-asc-avalon,bre-vch-mdx7-comms',2,'locations/brentford/landmarks.json','$[10]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:brentford/marker-danish-position:located_at','landmark','brentford/marker-danish-position','Possible Danish position, 1016 (conjectural)','brentford','located_at',NULL,NULL,'Possible Danish position, 1016 (conjectural)','A shaded area on the Surrey bank where the Danish army may have stood. The Chronicle''s wording, that Edmund crossed and then fought, is usually read as putting the fight south of the river, and the county history (citing Stenton) says it was fought on the south bank.',51.4778,-0.2975,'conjectural','low','bre-asc-avalon,bre-vch-mdx7-growth,bre-wikipedia-battle',3,'locations/brentford/landmarks.json','$[11]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:brentford/troops-english-main:located_at','landmark','brentford/troops-english-main','Edmund''s army (stand-in figures)','brentford','located_at',NULL,NULL,'Edmund''s army (stand-in figures)','A block of plain figures at the Middlesex end of the ford, standing for the English army that crossed the Thames here under King Edmund in 1016.',51.48088,-0.30515,'conjectural','low','bre-asc-avalon',1,'locations/brentford/landmarks.json','$[12]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:brentford/troops-english-advance:located_at','landmark','brentford/troops-english-advance','Englishmen ahead of the army (stand-in figures)','brentford','located_at',NULL,NULL,'Englishmen ahead of the army (stand-in figures)','A small loose group on the Surrey bank, standing for the men who, the Chronicle says, ''went before the main army with a design to plunder'' and of whom many drowned.',51.4791,-0.2998,'conjectural','low','bre-asc-avalon,bre-wikipedia-battle',2,'locations/brentford/landmarks.json','$[13]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:brentford/troops-danish:located_at','landmark','brentford/troops-danish','Danish army (stand-in figures)','brentford','located_at',NULL,NULL,'Danish army (stand-in figures)','A block of plain figures on the Surrey bank, standing for the Danish army that Edmund fought and put to flight.',51.4778,-0.2975,'conjectural','low','bre-asc-avalon,bre-wikipedia-battle',2,'locations/brentford/landmarks.json','$[14]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/roman-bridge:located_at','landmark','london/roman-bridge','Roman bridge','london','located_at',NULL,NULL,'Roman bridge','A timber bridge across the Thames on the Fish Street Hill line, the reason the town stood here. A probable timber pier base of the late 1st century was excavated near Pudding Lane in 1981.',51.5082,-0.0867,'reconstructed','low','gresham-discovering-port-roman-london,britannia-milne-further-evidence-roman,london-archaeologist-brigham-watson-regis-house,london-museum-timeline-roman-london,history-london-port-roman-london-secondary',5,'locations/london/landmarks.json','$[0]');
