INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/amphitheatre:located_at','landmark','london/amphitheatre','Amphitheatre','london','located_at',NULL,NULL,'Amphitheatre','An oval arena beneath today''s Guildhall Yard: built in timber about 74 CE and rebuilt shortly after 120 with a masonry arena wall and entrances. The seating was always timber.',51.5155,-0.092,'attested-excavated','medium','mola-londons-roman-amphitheatre-guildhall,city-of-london-londons-roman-amphitheatre-information,london-museum-roman-amphitheatre-central-london',3,'locations/london/landmarks.json','$[3]');
