INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/city-wall:located_at','landmark','london/city-wall','City wall','london','located_at',NULL,NULL,'City wall','The landward wall, about 3 km long, 2–2.6 m thick and about 6.4 m high, built of Kentish ragstone c. 190–225 and enclosing some 134 hectares. It set the limits of the city for the next 1,400 years.',51.5158,-0.0812,'attested-standing','high','english-heritage-history-london-wall,london-museum-timeline-roman-london,current-archaeology-fortress-londinium-tracing-londons,bho-stow-wall-about-citie,bho-stow-gates-wall,bho-fitzstephen-descriptio-stow-appendix,bho-stow-ditch-sometimes-compassing,moeml-aldgate,grub-street-aldgate-reproducing-harben-dictionary,grub-street-aldersgate-reproducing-harben-dictionary',10,'locations/london/landmarks.json','$[6]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/riverside-wall:located_at','landmark','london/riverside-wall','Riverside wall','london','located_at',NULL,NULL,'Riverside wall','A wall about 1,700 m long added along the river front c. 255–275 on the line of Thames Street, closing the circuit. Its eastern end was strengthened as late as c. 388–402, parts still stood in the late 9th century, and it had gone by the 12th.',51.51,-0.09,'attested-excavated','medium','english-heritage-history-london-wall,london-museum-timeline-roman-london,gresham-discovering-port-roman-london,mola-saxon-ad-4101066-research,gresham-london-notsodark-ages-lyn,london-museum-lundenwic-other-medieval-london,lamas-saxon-origins-queenhithe-r,bho-stow-wall-about-citie',8,'locations/london/landmarks.json','$[7]');
