INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/queenhithe:located_at','landmark','london/queenhithe','Queenhithe','london','located_at',NULL,NULL,'Queenhithe','A trading shore from the late 880s (''Æthelred''s Hythe'', first charter 889): at first an open beach market, with low timber revetments from the late 10th century and embankments dated 1021 and 1045. The main dock above the bridge through the Middle Ages.',51.5106,-0.095,'attested-documentary','high','lamas-saxon-origins-queenhithe-r,bho-stow-queene-hith-warde',2,'locations/london/landmarks.json','$[20]');
