INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/rose:located_at','landmark','london/rose','The Rose playhouse','london','located_at',NULL,NULL,'The Rose playhouse','Philip Henslowe''s playhouse of 1587, the first on Bankside; its foundations were excavated in 1989.',51.5072,-0.0955,'attested-excavated','high','mola-15871644-shakespeares-bankside-playhouses,reed-rose-theatre-citing-bowsher,folger-shakespeares-theater-folger-shakespeare,bho-survey-london-vol-22',4,'locations/london/landmarks.json','$[64]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/swan:located_at','landmark','london/swan','The Swan playhouse','london','located_at',NULL,NULL,'The Swan playhouse','Built about 1595 in Paris Garden; the subject of the only surviving sketch of an Elizabethan playhouse interior.',51.5073,-0.1046,'attested-pictorial','medium','moeml-swan,bho-survey-london-vol-22',2,'locations/london/landmarks.json','$[65]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/globe:located_at','landmark','london/globe','The Globe','london','located_at',NULL,NULL,'The Globe','Built in 1599 from the timbers of the Theatre; burned on 29 June 1613 and rebuilt with a tiled roof by 1614.',51.5067,-0.0946,'attested-excavated','medium','shakespeares-globe-globe,reed-globe-theatre-citing-bowsher,folger-shakespeares-theater-folger-shakespeare,cup-blatherwick-gurr-shakespeares-factory,bho-survey-london-vol-22',5,'locations/london/landmarks.json','$[66]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/bear-garden:located_at','landmark','london/bear-garden','Bear Garden, later the Hope','london','located_at',NULL,NULL,'Bear Garden, later the Hope','A baiting ring on Bankside, replaced in 1613–14 by the Hope, a dual-purpose playhouse and baiting house.',51.5076,-0.096,'attested-documentary','medium','bho-survey-london-vol-22,henslowe-alleyn-henslowealleyn-digitisation-project-muniments,bho-stow-bridge-warde-without',3,'locations/london/landmarks.json','$[67]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/waterfront-north:located_at','landmark','london/waterfront-north','City waterfront','london','located_at',NULL,NULL,'City waterfront','The built-up river frontage of the City: successive timber and later stone revetments pushed the bank out into the Thames, creating wharves between Thames Street and the water.',51.5094,-0.091,'reconstructed','medium','gresham-discovering-port-roman-london,history-london-port-roman-london-secondary,lamas-saxon-origins-queenhithe-r',3,'locations/london/landmarks.json','$[68]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/waterfront-south:located_at','landmark','london/waterfront-south','Bankside and Southwark river wall','london','located_at',NULL,NULL,'Bankside and Southwark river wall','The embanked south shore from Paris Garden past Winchester Palace to the bridge foot and St Olave''s.',51.5069,-0.092,'reconstructed','low','gresham-discovering-port-roman-london,history-london-port-roman-london-secondary,lamas-saxon-origins-queenhithe-r',3,'locations/london/landmarks.json','$[69]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/river-traffic-roman:located_at','landmark','london/river-traffic-roman','Roman shipping','london','located_at',NULL,NULL,'Roman shipping','Three Roman vessels have been excavated in London: the Blackfriars ship (a flat-bottomed Romano-Celtic sailing barge that sank with Kentish ragstone about AD 150), the New Guy''s House river barge (abandoned about AD 200) and the County Hall ship (a sea-going ship of Mediterranean build that sank after 293). The harbour was maintained to about AD 250, its quays were dismantled in the later 3rd century and the riverside wall then cut the town off from the river, so the traffic shown thins after 250 and again after 300. No Roman warship is evidenced at London. The vessel TYPES are dated and sourced individually (open a type in docs/VESSELS.md or data/locations/london/vessels.json); the number of craft and where each lies are illustrative, so this entry''s own evidence class, which describes the placements, is conjectural.',51.5085,-0.091,'conjectural','low','ves-mass-blackfriars1,ves-lm-blackfriars-maststep,ves-marsden-county-hall,ves-milne-port-roman-london,ves-gresham-port-growth,ves-hol-roman-port,ves-tdp-foreshore',7,'locations/london/landmarks.json','$[70]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/river-traffic-medieval:located_at','landmark','london/river-traffic-medieval','River traffic, late Saxon to Jacobean','london','located_at',NULL,NULL,'River traffic, late Saxon to Jacobean','The river traffic of the walled city, changing with the evidence: clinker cargo ships with side rudders from the late Saxon revival; ships with castles and stern rudders from about 1200 and Hanseatic cogs from the 13th century; the clinker river barge called a shout in the 14th-15th centuries; carvel-built carracks below the bridge once the drawbridge was no longer raised (about 1500); then armed merchantmen in the Pool, hoys, lighters, Gravesend tilt-boats, western barges and the wherries of the watermen (Stow counted above 2,000 small boats in 1598). Sea-going ships lie below the bridge after 1500, oared craft everywhere. The vessel TYPES are dated and sourced individually (open a type in docs/VESSELS.md or data/locations/london/vessels.json); the number of craft and where each lies are illustrative, so this entry''s own evidence class, which describes the placements, is conjectural.',51.5082,-0.09,'conjectural','low','ves-fordham-billingsgate-tolls,ves-rmg-ipswich-seal,ves-hol-hanse,ves-granger-blackfriars3,ves-moeml-drawbridge,ves-hol-tudor-bridge,ves-stow-queenhithe,ves-stow-waters,ves-gresham-ship,ves-hol-watermen,ves-kas-tilt-boats,ves-gloriana-rowbarges,ves-cityoflondon-billingsgate',13,'locations/london/landmarks.json','$[71]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/river-craft-prehistoric:located_at','landmark','london/river-craft-prehistoric','Logboats (illustrative)','london','located_at',NULL,NULL,'Logboats (illustrative)','Before the Romans almost no craft are evidenced in this reach. Logboats (dugouts) are known from the Thames and its marshes, at Erith and upriver at Bourne End, so two are shown drawn up on the shore; sewn-plank boats such as the Dover boat are coastal and none is known from the Thames. The vessel TYPES are dated and sourced individually (open a type in docs/VESSELS.md or data/locations/london/vessels.json); the number of craft and where each lies are illustrative, so this entry''s own evidence class, which describes the placements, is conjectural.',51.5083,-0.0875,'conjectural','low','ves-gresham-early-thames,ves-bucks-her-bourne-end,ves-intarch-logboats,ves-intarch-sewn-plank,ves-citizan-prehistoric-boats',5,'locations/london/landmarks.json','$[72]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/lundenwic-beach-craft:located_at','landmark','london/lundenwic-beach-craft','Boats at the Lundenwic shore (illustrative)','london','located_at',NULL,NULL,'Boats at the Lundenwic shore (illustrative)','Middle Saxon London (Lundenwic) traded by ship along the Strand, ''the beach'', from about 600 until its abandonment by the 880s; wattle and timber embankments have been excavated, but no boat. Clinker-built traders and small boats are shown drawn up on the foreshore. In these centuries nothing is shown at the old Roman bridgehead, where no craft are evidenced. The vessel TYPES are dated and sourced individually (open a type in docs/VESSELS.md or data/locations/london/vessels.json); the number of craft and where each lies are illustrative, so this entry''s own evidence class, which describes the placements, is conjectural.',51.5098,-0.1185,'conjectural','low','ves-lm-lundenwic,london-museum-lundenwic-other-medieval-london,ves-kent-her-graveney',3,'locations/london/landmarks.json','$[73]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/olafs-fleet:located_at','landmark','london/olafs-fleet','Olaf''s ships at the bridge (saga tradition)','london','located_at',NULL,NULL,'Olaf''s ships at the bridge (saga tradition)','Longships below the timber bridge, standing for the saga account of an attack on London Bridge in 1014. The ships are drawn as Scandinavian longships of the period (Skuldelev 5 and Skuldelev 2 types, c. 1030-1042: clinker hulls, side rudders, single square sails, here furled while they row).',51.5076,-0.0862,'conjectural','low','ev-fact-or-folklore-the-viking-attack-on-london-bri,ev-heimskringla-saga-of-olaf-haraldson-chapter-on-t,ev-olaf-haraldsson-encyclopaedia-romana,ev-the-anglo-saxon-chronicle-eleventh-century-entri,ev-tooley-street-delight-19-march-2022-sigvatr-s-st,ves-vsm-skuldelev5,ves-vsm-skuldelev2',7,'locations/london/landmarks.json','$[74]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:stonehenge/trilithons:located_at','landmark','stonehenge/trilithons','Sarsen trilithon horseshoe','stonehenge','located_at',NULL,NULL,'Sarsen trilithon horseshoe','Five sarsen trilithons (ten uprights, five lintels) in a horseshoe about 13.7 m across, open to the north-east; the tallest, the Great Trilithon at the south-west, stood about 7 m above ground. Drawn from the stone catalogue: stone positions and sizes are surveyed from what stands today, the original complete form is reconstructed from them.',51.178868,-1.826196,'attested-standing','medium','sto-darvill-2012-remodelled,sto-marshall-2012-eh-chronology,sto-eh-stones,sto-sos-stones,sto-stukeley-1740,sto-long-1876,sto-barclay-1895,sto-eh-sources',8,'locations/stonehenge/landmarks.json','$[0]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:stonehenge/sarsen-circle:located_at','landmark','stonehenge/sarsen-circle','Sarsen circle and lintels','stonehenge','located_at',NULL,NULL,'Sarsen circle and lintels','The outer ring of thirty sarsen uprights (about 4.1 m high, 2.1 m wide) carrying a continuous ring of thirty lintels about 4.9 m above ground; outer diameter about 29.6 m. Seventeen uprights and six lintels stand today. The complete ring shown in the built phases is a reconstruction.',51.178868,-1.826196,'reconstructed','medium','sto-darvill-2012-remodelled,sto-marshall-2012-eh-chronology,sto-banton-2014-abstract,sto-eh-stones,sto-eh-description,sto-sos-stones,sto-sos-missing,sto-stukeley-1740,sto-barclay-1895,sto-wiki-stonehenge',10,'locations/stonehenge/landmarks.json','$[1]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:stonehenge/aubrey-bluestones:located_at','landmark','stonehenge/aubrey-bluestones','Bluestones in the Aubrey Holes (contested)','stonehenge','located_at',NULL,NULL,'Bluestones in the Aubrey Holes (contested)','On Parker Pearson''s interpretation the 56 Aubrey Holes held bluestones from about 3000 BCE, so Stonehenge''s first stones were a ring about 87 m across just inside the bank. Shown as 56 small standing bluestones.',51.178868,-1.826196,'reconstructed','low','sto-darvill-2012-remodelled,sto-wiki-aubrey-holes',2,'locations/stonehenge/landmarks.json','$[2]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:stonehenge/bluestone-arcs:located_at','landmark','stonehenge/bluestone-arcs','Q and R bluestone double arc (Stage 2)','stonehenge','located_at',NULL,NULL,'Q and R bluestone double arc (Stage 2)','A double ring of bluestones between the trilithons and the sarsen circle, set in the Q and R holes (paired ''dumbbell'' sockets on the east, a single line on the south and west). Drawn as two parametric rings of 54 stones in all.',51.178868,-1.826196,'reconstructed','low','sto-darvill-2012-remodelled,sto-marshall-2012-eh-chronology',2,'locations/stonehenge/landmarks.json','$[3]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:stonehenge/bluestone-circle-and-oval:located_at','landmark','stonehenge/bluestone-circle-and-oval','Central bluestone circle (Stage 3) and bluestone oval (Stage 4)','stonehenge','located_at',NULL,NULL,'Central bluestone circle (Stage 3) and bluestone oval (Stage 4)','Two bluestone settings inside the trilithons, one after the other: a small central circle in Stage 3 and the oval of about 25 stones in Stage 4, which later became the horseshoe. Both are parametric stand-ins.',51.178868,-1.826196,'conjectural','low','sto-darvill-2012-remodelled,sto-marshall-2012-eh-chronology',2,'locations/stonehenge/landmarks.json','$[4]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:stonehenge/bluestone-circle:located_at','landmark','stonehenge/bluestone-circle','Outer bluestone circle','stonehenge','located_at',NULL,NULL,'Outer bluestone circle','The bluestone circle between the trilithons and the sarsen circle, about 22 m across (radius 11 m), of 40-60 stones when complete (Stage 4). Nineteen stone positions are catalogued from the surviving stones and stumps; the complete ring is drawn as 60 parametric stones.',51.178868,-1.826196,'reconstructed','low','sto-darvill-2012-remodelled,sto-marshall-2012-eh-chronology,sto-sos-stones,sto-stukeley-1740,sto-barclay-1895',5,'locations/stonehenge/landmarks.json','$[5]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:stonehenge/bluestone-horseshoe:located_at','landmark','stonehenge/bluestone-horseshoe','Bluestone horseshoe','stonehenge','located_at',NULL,NULL,'Bluestone horseshoe','The bluestone horseshoe inside the trilithons, open to the north-east, of about 19 stones (Stage 5). Twelve positions are catalogued from surviving stones; the complete setting is drawn as 19 parametric stones.',51.178868,-1.826196,'reconstructed','low','sto-darvill-2012-remodelled,sto-marshall-2012-eh-chronology,sto-sos-stones,sto-stukeley-1740,sto-barclay-1895',5,'locations/stonehenge/landmarks.json','$[6]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:stonehenge/altar-stone:located_at','landmark','stonehenge/altar-stone','Altar Stone','stonehenge','located_at',NULL,NULL,'Altar Stone','A slab of green-grey sandstone about 4.9 x 1.0 x 0.5 m at the foot of the Great Trilithon. It is not from southern Britain: a 2024 study matched its chemistry and mineral ages most closely to the Old Red Sandstone of the Orcadian Basin in north-east Scotland, at least 750 km away; a 2026 study questions that match, and the exact source remains unresolved. Drawn lying flat at ground level.',51.178868,-1.826196,'attested-standing','low','sto-clarke2024-altar,sto-scinews-altar-2026,sto-wiki-altar-stone,sto-eh-research,sto-darvill-2012-remodelled,sto-sos-stones,sto-stukeley-1740,sto-long-1876',8,'locations/stonehenge/landmarks.json','$[7]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:stonehenge/station-stones:located_at','landmark','stonehenge/station-stones','Station Stones','stonehenge','located_at',NULL,NULL,'Station Stones','Four small sarsens (91-94) in a rectangle just inside the bank. Two (91, 93) survive; the other two positions are marked by modern plaques at the findspots of their barrows.',51.178868,-1.826196,'reconstructed','low','sto-wiki-station-stones,sto-darvill-2012-remodelled,sto-eh-history,sto-sos-stones,sto-osm-overpass',5,'locations/stonehenge/landmarks.json','$[8]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:stonehenge/slaughter-stone:located_at','landmark','stonehenge/slaughter-stone','Slaughter Stone','stonehenge','located_at',NULL,NULL,'Slaughter Stone','A fallen sarsen about 4.9 m long (6.1 m as catalogued when standing) in the north-east entrance, once standing there with companion stones D and E.',51.178868,-1.826196,'attested-standing','medium','sto-darvill-2012-remodelled,sto-eh-stones,sto-wiki-stonehenge,sto-sos-stones,sto-osm-overpass',5,'locations/stonehenge/landmarks.json','$[9]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:stonehenge/heel-stone:located_at','landmark','stonehenge/heel-stone','Heel Stone (and stonehole 97)','stonehenge','located_at',NULL,NULL,'Heel Stone (and stonehole 97)','An unshaped sarsen about 4.7 m high, 77.4 m from the centre on the solstice axis, with a second stonehole (97) beside it.',51.178868,-1.826196,'attested-standing','medium','sto-wiki-heel-stone,sto-darvill-2012-remodelled,sto-eh-stones,sto-sos-stones,sto-stukeley-1740,sto-barclay-1895,sto-osm-overpass',7,'locations/stonehenge/landmarks.json','$[10]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:stonehenge/aubrey-holes:located_at','landmark','stonehenge/aubrey-holes','Aubrey Holes','stonehenge','located_at',NULL,NULL,'Aubrey Holes','Fifty-six chalk pits in a ring about 87 m across (circumference 271.6 m), just inside the bank, each about 1.06 m wide and 0.76 m deep on average. Cremations were inserted in their upper fills.',51.178868,-1.826196,'attested-excavated','medium','sto-wiki-aubrey-holes,sto-darvill-2012-remodelled,sto-marshall-2012-eh-chronology',3,'locations/stonehenge/landmarks.json','$[11]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:stonehenge/stonehenge-ditch-bank:located_at','landmark','stonehenge/stonehenge-ditch-bank','Stonehenge ditch and bank','stonehenge','located_at',NULL,NULL,'Stonehenge ditch and bank','A circular bank with an external ditch, about 110 m across overall, with a wide entrance to the north-east on the solstice axis and a smaller one to the south. Ditch dug with antler picks; re-cut in Stage 3. Drawn with the ditch centreline at radius 53 m.',51.178868,-1.826196,'attested-excavated','medium','sto-darvill-2012-remodelled,sto-eh-description,sto-eh-history,sto-marshall-2012-eh-chronology',4,'locations/stonehenge/landmarks.json','$[12]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:stonehenge/solstice-sunrise-marker:located_at','landmark','stonehenge/solstice-sunrise-marker','Midsummer sunrise marker (computed)','stonehenge','located_at',NULL,NULL,'Midsummer sunrise marker (computed)','A computed marker for the Events menu: the direction of sunrise on the midsummer solstice seen from the centre of Stonehenge in 2500 BCE, azimuth 49.2 degrees. It is an analytical overlay, not a structure and not lighting. The lead computed the azimuth for 2500 BCE, latitude 51.179, obliquity 23.97 degrees, with the horizon assumed at 0.6 degrees.',51.178868,-1.826196,'reconstructed','medium','sto-skyatnight-astronomy,sto-wiki-archaeoastronomy,sto-darvill-2012-remodelled',3,'locations/stonehenge/landmarks.json','$[13]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:stonehenge/solstice-sunset-marker:located_at','landmark','stonehenge/solstice-sunset-marker','Midwinter sunset marker (computed)','stonehenge','located_at',NULL,NULL,'Midwinter sunset marker (computed)','A computed marker for the Events menu: the direction of sunset on the midwinter solstice seen from the centre of Stonehenge in 2500 BCE, azimuth 230 degrees. It is an analytical overlay, not a structure and not lighting. The lead computed the azimuth for 2500 BCE, latitude 51.179, obliquity 23.97 degrees, with the horizon assumed at 0.6 degrees.',51.178868,-1.826196,'reconstructed','medium','sto-skyatnight-astronomy,sto-wiki-archaeoastronomy,sto-darvill-2012-remodelled',3,'locations/stonehenge/landmarks.json','$[14]');
