INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:stonehenge/durrington-walls-henge:located_at','landmark','stonehenge/durrington-walls-henge','Durrington Walls henge','stonehenge','located_at',NULL,NULL,'Durrington Walls henge','The largest henge in Britain: a circular enclosure about 500 m across with a huge outer bank about 3 m high and a deep ditch, built c. 2480-2450 BCE over the line of an earlier ring of timber posts, beside the Neolithic village on the slope to the Avon.',51.192703,-1.78666,'attested-excavated','medium','sto-archco-durrington,sto-wp-durrington,sto-wikipedia-durrington,sto-gazetteer-durrington,sto-bristol-2007',5,'locations/stonehenge/landmarks.json','$[27]');
