INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/st-pauls:phase:4','landmark','london/st-pauls','St Paul''s Cathedral','london','phase',1251,1561,'Old St Paul''s extended east (the New Work, 1251–1314), with renewed spire','The Gothic ''New Work'' east end was begun in 1251 (VCH) and the renewed spire dedicated in 1314, used here as the completion of the work (the 1314 date is not confirmed by the VCH pages read). Extension phase: the Romanesque church stands until then. Spire destroyed by lightning and fire, 4 June 1561. All phases from 1087 share the west front (89.5 m west of the landmark point), so the New Work extends the church eastwards, and the crossing tower stays where the Romanesque church has it (93 m from the west front).',NULL,NULL,'attested-documentary','medium','bho-secular-canons-cathedral-st,gresham-archaeology-st-pauls-cathedral,gresham-london-notsodark-ages-lyn,project-gutenberg-w-benham-old-st,bho-stow-faringdon-ward-infra,london-museum-history-st-pauls-cathedral,current-archaeology-st-pauls-before-wren,nc-state-virtual-pauls-cross-project,bho-vch-london-1-st-pauls',9,'locations/london/landmarks.json','$[19].phases[4]');
