INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/st-olave:phase:0','landmark','london/st-olave','St Olave, Southwark','london','phase',1070,NULL,'Church','In existence by the late 11th century: probably the church recorded in Domesday (1086) and first named in 1096. 1070 is a display anchor, not a construction date; a pre-Conquest origin is possible but not established by the sources read.',NULL,NULL,'attested-documentary','low','bho-stow-bridge-warde-without,london-museum-vikings-london,current-archaeology-life-across-water-exploring',3,'locations/london/landmarks.json','$[31].phases[0]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/st-mary-overie:phase:0','landmark','london/st-mary-overie','St Mary Overie (St Saviour''s)','london','phase',1086,1106,'Minster recorded in Domesday (form unknown)','The first written reference is a ''minster'' in Domesday Book (1086); in 1106 the church was refounded as an Augustinian priory (Southwark Cathedral). Its form is unknown and the small church shown is a placeholder; 1086 is the date of the record, not of building.',NULL,NULL,'attested-standing','high','bho-austin-canons-priory-southwark,southwark-cathedral-augustinian-heritage,bho-stow-bridge-warde-without,southwark-cathedral-our-history,bho-vch-surrey-4-st-mary-overie',5,'locations/london/landmarks.json','$[32].phases[0]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/st-mary-overie:phase:1','landmark','london/st-mary-overie','St Mary Overie (St Saviour''s)','london','phase',1106,1212,'Norman priory church','Refounded 1106; burned 11 July 1212 in the same fire as the bridge.',NULL,NULL,'attested-standing','high','bho-austin-canons-priory-southwark,southwark-cathedral-augustinian-heritage,bho-stow-bridge-warde-without,southwark-cathedral-our-history,bho-vch-surrey-4-st-mary-overie',5,'locations/london/landmarks.json','$[32].phases[1]');
