INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/temple-church:phase:1','landmark','london/temple-church','Temple Church','london','phase',1240,NULL,'Round church with hall chancel','The chancel was added east of the round nave (consecrated 1240); both phases pin the junction with the round, so the extension grows eastwards only.',NULL,NULL,'attested-standing','high','bho-houses-military-orders-temple,temple-church-history',2,'locations/london/landmarks.json','$[44].phases[1]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/blackfriars:phase:0','landmark','london/blackfriars','Blackfriars','london','phase',1276,1538,'Dominican friary','Site granted 1276; church begun 1279 and built into the 1290s.',NULL,NULL,'attested-documentary','medium','bho-friaries-black-friars-vch,bho-stow-wall-about-citie,bho-stow-faringdon-ward-infra,folger-shakespeares-theater-folger-shakespeare,emlot-theatres',5,'locations/london/landmarks.json','$[45].phases[0]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/blackfriars:phase:1','landmark','london/blackfriars','Blackfriars','london','phase',1538,NULL,'Converted precinct (church demolished)','Surrendered 12 November 1538 (VCH); the church was demolished afterwards, in years these sources do not fix, so 1538 is the institutional, not the physical, boundary. Theatres in the former precinct: Blackfriars I from 1576 and Blackfriars II from 1596, distinct venues (EMLoT); the King''s Men used the second from 1608–09.',NULL,NULL,'attested-documentary','medium','bho-friaries-black-friars-vch,bho-stow-wall-about-citie,bho-stow-faringdon-ward-infra,folger-shakespeares-theater-folger-shakespeare,emlot-theatres',5,'locations/london/landmarks.json','$[45].phases[1]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/greyfriars:phase:0','landmark','london/greyfriars','Greyfriars (Christ Church)','london','phase',1225,1306,'First friary','Drawn in the place of the great church''s choir (its east end pinned to the great church''s), since parts of the first church were taken into the new choir. Its exact plan is not known.',NULL,NULL,'attested-documentary','high','bho-friaries-grey-friars-vch,bho-stow-faringdon-ward-infra',2,'locations/london/landmarks.json','$[46].phases[0]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/greyfriars:phase:1','landmark','london/greyfriars','Greyfriars (Christ Church)','london','phase',1306,NULL,'Great church','Foundation stone of the great church laid 1306, finished 1327 (VCH; a chronicler says it was still not dedicated in 1357). VCH gives 300 × 89 ft; the 64 ft height is from another account. Parts of the first church were taken into the new choir, so the first friary stays standing while the great church rises (extension phase). Surrendered 12 November 1538; kept as Christ Church parish church from 1547.',NULL,NULL,'attested-documentary','high','bho-friaries-grey-friars-vch,bho-stow-faringdon-ward-infra',2,'locations/london/landmarks.json','$[46].phases[1]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/austin-friars:phase:0','landmark','london/austin-friars','Austin Friars','london','phase',1253,1354,'Friary',NULL,NULL,NULL,'attested-documentary','medium','bho-friaries-austin-friars-vch,bho-stow-broadstreete-warde',2,'locations/london/landmarks.json','$[47].phases[0]');
