INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/austin-friars:phase:2','landmark','london/austin-friars','Austin Friars','london','phase',1600,NULL,'Nave only (Dutch Church)','Choir and steeple taken down around 1600. The nave kept is the west part of the rebuilt church: its west end is pinned to that church''s west front.',NULL,NULL,'attested-documentary','medium','bho-friaries-austin-friars-vch,bho-stow-broadstreete-warde',2,'locations/london/landmarks.json','$[47].phases[2]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/holy-trinity-aldgate:phase:0','landmark','london/holy-trinity-aldgate','Holy Trinity Priory, Aldgate','london','phase',1108,1532,'Priory','Founded 1107/08; burned 1132 and rebuilt; surrendered July 1531 (Stow) or 1532. VCH: surrendered February 1532 and granted to Lord Audley in 1534; when the church was pulled down is not established by the sources read, so the end shown is the surrender.',NULL,NULL,'attested-excavated','medium','bho-austin-canons-priory-holy,bho-stow-ealdgate-warde',2,'locations/london/landmarks.json','$[48].phases[0]');
