INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/st-bartholomew:phase:0','landmark','london/st-bartholomew','St Bartholomew''s Priory and Hospital','london','phase',1123,1543,'Priory church (surrendered 1539)','Surrendered in October 1539 (VCH). The nave was then demolished and the choir kept as the parish church (Great St Bartholomew); the sources do not give the year of demolition, so 1543 is a display boundary, not continued monastic life.',NULL,NULL,'attested-standing','high','bho-austin-canons-priory-st,bho-hospitals-st-bartholomew-vch,st-bartholomew-history,bho-stow-warde-faringdon-extra',4,'locations/london/landmarks.json','$[49].phases[0]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/st-bartholomew:phase:1','landmark','london/st-bartholomew','St Bartholomew''s Priory and Hospital','london','phase',1543,NULL,'Choir only (parish church)','The choir kept as the parish church: its east end is pinned to the priory church''s east end.',NULL,NULL,'attested-standing','high','bho-austin-canons-priory-st,bho-hospitals-st-bartholomew-vch,st-bartholomew-history,bho-stow-warde-faringdon-extra',4,'locations/london/landmarks.json','$[49].phases[1]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/charterhouse:phase:0','landmark','london/charterhouse','Charterhouse','london','phase',1371,1546,'Carthusian monastery (community disbanded 1538)','Founded 1371 on the plague cemetery of 1349; the cells took about 60 years to complete. Surrendered 10 June 1537 and formally disbanded 15 November 1538 (VCH). The buildings then stood, divided among Crown grantees, used as a royal storehouse from 1542 and largely derelict, until they were sold to Sir Edward North on 14 April 1546; the monastic community did not continue after 1538.',NULL,NULL,'attested-standing','high','bho-religious-houses-house-carthusian,charterhouse-history,bho-stow-suburbs-without-walls',3,'locations/london/landmarks.json','$[50].phases[0]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/charterhouse:phase:1','landmark','london/charterhouse','Charterhouse','london','phase',1546,NULL,'Mansion, later Sutton''s Hospital','Sir Edward North bought the site on 14 April 1546 and made a mansion of it; Sutton''s Hospital from 1611.',NULL,NULL,'attested-standing','high','bho-religious-houses-house-carthusian,charterhouse-history,bho-stow-suburbs-without-walls',3,'locations/london/landmarks.json','$[50].phases[1]');
