INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/river-craft-prehistoric:phase:0','landmark','london/river-craft-prehistoric','Logboats (illustrative)','london','phase',-2350,50,'Logboats on the shore','From the start of the period attributed to the nearest Thames logboat (Bourne End: Bronze or Iron Age, 2350 BCE-42 CE); no dated find in this reach allows a narrower window.',NULL,NULL,'conjectural','low','ves-gresham-early-thames,ves-bucks-her-bourne-end,ves-intarch-logboats,ves-intarch-sewn-plank,ves-citizan-prehistoric-boats',5,'locations/london/landmarks.json','$[72].phases[0]');
