INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:stonehenge/trilithons:begun:0','landmark','stonehenge/trilithons','Sarsen trilithon horseshoe','stonehenge','begun',-2580,NULL,'Trilithons raised (fresh-dressed)','Darvill et al. 2012 Stage 2 (2620-2480 BCE); EH chronology model for the trilithons 2585-2400 BCE (93%, from one antler in the socket of stones 53/54). Raising is animated 2580-2520; the single modelled date is 2540 BCE. Fresh-dressed (pale) until 2400 BCE, then weathered: that swap is conjectural.',NULL,NULL,'attested-standing','medium','sto-darvill-2012-remodelled,sto-marshall-2012-eh-chronology,sto-eh-stones,sto-sos-stones,sto-stukeley-1740,sto-long-1876,sto-barclay-1895,sto-eh-sources',8,'locations/stonehenge/landmarks.json','$[0].phases[0].from');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:stonehenge/sarsen-circle:begun:0','landmark','stonehenge/sarsen-circle','Sarsen circle and lintels','stonehenge','begun',-2560,NULL,'Sarsen circle raised (fresh-dressed)','EH chronology: sarsen circle 2580-2475 BCE (95%, one antler in the socket of stone 1); Darvill et al. 2012 Stage 2 (2620-2480). Raising is animated 2560-2470; the single modelled date is 2530 BCE, inside that span. Order relative to the trilithons uncertain (trilithons probably first). Fresh-dressed until 2400 BCE then weathered: conjectural.',NULL,NULL,'reconstructed','medium','sto-darvill-2012-remodelled,sto-marshall-2012-eh-chronology,sto-banton-2014-abstract,sto-eh-stones,sto-eh-description,sto-sos-stones,sto-sos-missing,sto-stukeley-1740,sto-barclay-1895,sto-wiki-stonehenge',10,'locations/stonehenge/landmarks.json','$[1].phases[0].from');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:stonehenge/aubrey-bluestones:begun:0','landmark','stonehenge/aubrey-bluestones','Bluestones in the Aubrey Holes (contested)','stonehenge','begun',-3000,NULL,'Bluestones in the Aubrey Holes (interpretation)','Parker Pearson: stones from c. 3000 BCE (Darvill et al. 2012 Stage 1, 3000-2620 BCE). Removal modelled at the start of Stage 2 (2620 BCE); the date is not known.',NULL,NULL,'reconstructed','low','sto-darvill-2012-remodelled,sto-wiki-aubrey-holes',2,'locations/stonehenge/landmarks.json','$[2].phases[0].from');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:stonehenge/bluestone-arcs:begun:0','landmark','stonehenge/bluestone-arcs','Q and R bluestone double arc (Stage 2)','stonehenge','begun',-2620,NULL,'Q and R bluestone double arc','Darvill et al. 2012 Stage 2 (2620-2480 BCE), dismantled in Stage 4 (from 2280 BCE) per the same account. Raising is animated 2620-2600: the time within Stage 2 is not known. ''replaced'': taken down over a year at 2280 BCE (conjectural timing).',NULL,NULL,'reconstructed','low','sto-darvill-2012-remodelled,sto-marshall-2012-eh-chronology',2,'locations/stonehenge/landmarks.json','$[3].phases[0].from');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:stonehenge/bluestone-circle-and-oval:begun:0','landmark','stonehenge/bluestone-circle-and-oval','Central bluestone circle (Stage 3) and bluestone oval (Stage 4)','stonehenge','begun',-2480,NULL,'Central bluestone circle (Stage 3; completion conjectural)','Darvill et al. 2012 Stage 3 (2480-2280 BCE). Taken down at the start of Stage 4 (2280 BCE); exact years unknown.',NULL,NULL,'conjectural','low','sto-darvill-2012-remodelled,sto-marshall-2012-eh-chronology',2,'locations/stonehenge/landmarks.json','$[4].phases[0].from');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:stonehenge/bluestone-circle-and-oval:begun:1','landmark','stonehenge/bluestone-circle-and-oval','Central bluestone circle (Stage 3) and bluestone oval (Stage 4)','stonehenge','begun',-2120,NULL,'Bluestone oval of c. 25 stones (Stage 4)','Modelled 2060 BCE (Darvill et al. 2012: oval 2205-1920 BCE at 95%, Stage 4 2280-2020). Hands over to the Stage 5 horseshoe at 2020 BCE; Darvill instead dates the reduction of the oval to a horseshoe to the Roman period.',NULL,NULL,'conjectural','low','sto-darvill-2012-remodelled,sto-marshall-2012-eh-chronology',2,'locations/stonehenge/landmarks.json','$[4].phases[1].from');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:stonehenge/bluestone-circle:begun:0','landmark','stonehenge/bluestone-circle','Outer bluestone circle','stonehenge','begun',-2220,NULL,'Outer bluestone circle (complete, parametric)','Darvill et al. 2012 Stage 4 (2280-2020 BCE); EH chronology: bluestone circle 2275-2030 BCE (95%). Modelled 2165 BCE. The handover at year 1 CE is a CONVENTION, not a dated event: losses and falls between the end of use (c. 1500 BCE) and the first drawings (c. 1573 CE) are undated. Roman-period disturbance is recorded at the site, and nothing else is known of when individual stones fell or were taken.',NULL,NULL,'reconstructed','low','sto-darvill-2012-remodelled,sto-marshall-2012-eh-chronology,sto-sos-stones,sto-stukeley-1740,sto-barclay-1895',5,'locations/stonehenge/landmarks.json','$[5].phases[0].from');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:stonehenge/bluestone-horseshoe:begun:0','landmark','stonehenge/bluestone-horseshoe','Bluestone horseshoe','stonehenge','begun',-2020,NULL,'Bluestone horseshoe (complete, parametric)','Stage 5 (2020-1520 BCE) modelled at its start; the date is disputed (see uncertainty). The handover at year 1 CE is a CONVENTION, not a dated event: losses and falls between the end of use (c. 1500 BCE) and the first drawings (c. 1573 CE) are undated. Roman-period disturbance is recorded at the site, and nothing else is known of when individual stones fell or were taken.',NULL,NULL,'reconstructed','low','sto-darvill-2012-remodelled,sto-marshall-2012-eh-chronology,sto-sos-stones,sto-stukeley-1740,sto-barclay-1895',5,'locations/stonehenge/landmarks.json','$[6].phases[0].from');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:stonehenge/altar-stone:begun:0','landmark','stonehenge/altar-stone','Altar Stone','stonehenge','begun',-2545,NULL,'Altar Stone in place','Modelled 2540 BCE with the trilithons (Darvill 2012: tentatively Stage 2, 2620-2480). The handover at year 1 CE is a CONVENTION, not a dated event: losses and falls between the end of use (c. 1500 BCE) and the first drawings (c. 1573 CE) are undated. Roman-period disturbance is recorded at the site, and nothing else is known of when individual stones fell or were taken.',NULL,NULL,'attested-standing','low','sto-clarke2024-altar,sto-scinews-altar-2026,sto-wiki-altar-stone,sto-eh-research,sto-darvill-2012-remodelled,sto-sos-stones,sto-stukeley-1740,sto-long-1876',8,'locations/stonehenge/landmarks.json','$[7].phases[0].from');
