INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:stonehenge/durrington-timber-ring:begun:0','landmark','stonehenge/durrington-timber-ring','Durrington Walls timber ring (beneath the later bank)','stonehenge','begun',-2530,NULL,'Timber ring of about 300 posts','Current Archaeology: the ring stood for at most about 50 years, its posts were removed and sockets filled before the henge bank (c. 2480-2450 BCE) covered them; when it went up is not directly dated. Display years 2530-2481 BCE so that it is gone when the henge begins (corrected after fact review glm-stonehenge-005).',NULL,NULL,'attested-excavated','medium','sto-archco-durrington,sto-wp-durrington',2,'locations/stonehenge/landmarks.json','$[28].phases[0].from');
