INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/st-mary-overie:completed:3','landmark','london/st-mary-overie','St Mary Overie (St Saviour''s)','london','completed',1528,NULL,'Church with heightened tower','The two upper stages of the tower were built in 1520–28 (VCH Surrey), shown as an extension rising while the earlier church stands. Priory surrendered 27 October 1539; parish church of St Saviour from 1540.',NULL,NULL,'attested-standing','high','bho-austin-canons-priory-southwark,southwark-cathedral-augustinian-heritage,bho-stow-bridge-warde-without,southwark-cathedral-our-history,bho-vch-surrey-4-st-mary-overie',5,'locations/london/landmarks.json','$[32].phases[3].built');
