INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/roman-quay:completed:1','landmark','london/roman-quay','Roman quays and warehouses','london','completed',102,NULL,'Timber quays and warehouses','Tree-ring anchors: great quay 63, landing stage c. 70, extension 102, further advances to the mid 3rd century; quays dismantled by the 4th century.',NULL,NULL,'attested-excavated','high','london-archaeologist-brigham-watson-regis-house,gresham-discovering-port-roman-london,britannia-brigham-late-roman-waterfront,rfla-roman-ad-43-410,history-london-port-roman-london-secondary',5,'locations/london/landmarks.json','$[35].phases[1].built');
