INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/westminster-hall:completed:1','landmark','london/westminster-hall','Westminster Hall and Palace','london','completed',1399,NULL,'Hall heightened and given its hammerbeam roof','Roof commissioned 1393; the Norman walls were kept, heightened and refaced to carry it. A Commons debate of 1914 gives the work as 1393–1402; the lanterns are usually dated 1397–98 and work stopped in 1401 with decoration unfinished. 1399 is an approximate display anchor for substantial completion, not a documented date. Extension phase: the Norman hall stays standing until then.',NULL,NULL,'attested-standing','high','bho-stow-citie-westminster,mola-saxon-ad-4101066-research,hansard-1914-westminster-hall-roof',3,'locations/london/landmarks.json','$[38].phases[1].built');
