INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/greyfriars:completed:1','landmark','london/greyfriars','Greyfriars (Christ Church)','london','completed',1327,NULL,'Great church','Foundation stone of the great church laid 1306, finished 1327 (VCH; a chronicler says it was still not dedicated in 1357). VCH gives 300 × 89 ft; the 64 ft height is from another account. Parts of the first church were taken into the new choir, so the first friary stays standing while the great church rises (extension phase). Surrendered 12 November 1538; kept as Christ Church parish church from 1547.',NULL,NULL,'attested-documentary','high','bho-friaries-grey-friars-vch,bho-stow-faringdon-ward-infra',2,'locations/london/landmarks.json','$[46].phases[1].built');
