INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/st-bartholomew:completed:0','landmark','london/st-bartholomew','St Bartholomew''s Priory and Hospital','london','completed',1160,NULL,'Priory church (surrendered 1539)','Surrendered in October 1539 (VCH). The nave was then demolished and the choir kept as the parish church (Great St Bartholomew); the sources do not give the year of demolition, so 1543 is a display boundary, not continued monastic life.',NULL,NULL,'attested-standing','high','bho-austin-canons-priory-st,bho-hospitals-st-bartholomew-vch,st-bartholomew-history,bho-stow-warde-faringdon-extra',4,'locations/london/landmarks.json','$[49].phases[0].built');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/charterhouse:completed:0','landmark','london/charterhouse','Charterhouse','london','completed',1436,NULL,'Carthusian monastery (community disbanded 1538)','Founded 1371 on the plague cemetery of 1349; the cells took about 60 years to complete. Surrendered 10 June 1537 and formally disbanded 15 November 1538 (VCH). The buildings then stood, divided among Crown grantees, used as a royal storehouse from 1542 and largely derelict, until they were sold to Sir Edward North on 14 April 1546; the monastic community did not continue after 1538.',NULL,NULL,'attested-standing','high','bho-religious-houses-house-carthusian,charterhouse-history,bho-stow-suburbs-without-walls',3,'locations/london/landmarks.json','$[50].phases[0].built');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/savoy:completed:0','landmark','london/savoy','Savoy Palace, later Savoy Hospital','london','completed',1360,NULL,'Savoy Palace','Peter of Savoy''s house from 1245–46; Lancastrian palace of the 1350s; burned 1381 and left a ruin.',NULL,NULL,'attested-documentary','medium','bho-stow-liberties-dutchie-lancaster',1,'locations/london/landmarks.json','$[51].phases[0].built');
