INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/guildhall:completed:0','landmark','london/guildhall','Guildhall','london','completed',1440,NULL,'Great Hall','Begun 1411. The City of London gives 1411–1440 for the building, and the Gresham lecture a wider civic campaign of about 1411–1450 including the precinct. The hall is shown complete only at the end of the City''s range; its exact completion year is not recorded in these sources.',NULL,NULL,'attested-standing','medium','bho-stow-cheape-warde,gresham-envy-kings-guildhall-london,city-of-london-many-lives-guildhall',3,'locations/london/landmarks.json','$[52].phases[0].built');
