INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:stonehenge/station-stones:completed:0','landmark','stonehenge/station-stones','Station Stones','stonehenge','completed',-2550,NULL,'Station Stones (four)','Stage 2 (2620-2480 BCE), modelled 2550 BCE. The handover at year 1 CE is a CONVENTION, not a dated event: losses and falls between the end of use (c. 1500 BCE) and the first drawings (c. 1573 CE) are undated. Roman-period disturbance is recorded at the site, and nothing else is known of when individual stones fell or were taken.',NULL,NULL,'reconstructed','low','sto-wiki-station-stones,sto-darvill-2012-remodelled,sto-eh-history,sto-sos-stones,sto-osm-overpass',5,'locations/stonehenge/landmarks.json','$[8].phases[0].built');
