INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:stonehenge/durrington-timber-ring:completed:0','landmark','stonehenge/durrington-timber-ring','Durrington Walls timber ring (beneath the later bank)','stonehenge','completed',-2520,NULL,'Timber ring of about 300 posts','Current Archaeology: the ring stood for at most about 50 years, its posts were removed and sockets filled before the henge bank (c. 2480-2450 BCE) covered them; when it went up is not directly dated. Display years 2530-2481 BCE so that it is gone when the henge begins (corrected after fact review glm-stonehenge-005).',NULL,NULL,'attested-excavated','medium','sto-archco-durrington,sto-wp-durrington',2,'locations/stonehenge/landmarks.json','$[28].phases[0].built');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:stonehenge/durrington-southern-circle:completed:0','landmark','stonehenge/durrington-southern-circle','Durrington Walls Southern Circle (timber)','stonehenge','completed',-2500,NULL,'Southern Circle of timber posts (illustrative)','Wikipedia: c. 2600 BCE with four rings, two more c. 200 years later; Current Archaeology: expanded with c. 200 posts c. 2480-2450 BCE. The accounts conflict; built here 2520-2500 BCE to match the settlement. Decay 2400-2300 BCE is a placeholder.',NULL,NULL,'conjectural','low','sto-wp-durrington,sto-archco-durrington,sto-wp-woodhenge,sto-gazetteer-durrington',4,'locations/stonehenge/landmarks.json','$[29].phases[0].built');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:stonehenge/woodhenge:completed:0','landmark','stonehenge/woodhenge','Woodhenge (six oval rings of timber posts)','stonehenge','completed',-2610,NULL,'Woodhenge: six oval rings of timber posts (all rings drawn together)','Historic England Research Report 94/2024 (as summarised): timber monument built 2635-2575 cal BC (95%), most likely 2635-2610; drawn 2635-2610 BCE. Ditch and bank are a separate, later landmark (interval 75-440 years). Decay 2500-2350 BCE is a placeholder; the rings may not all have decayed together (corrected after fact review glm-stonehenge-007).',NULL,NULL,'attested-excavated','medium','sto-he-woodhenge-2024-summary,sto-wp-woodhenge,sto-wikipedia-woodhenge,sto-osm-overpass',4,'locations/stonehenge/landmarks.json','$[31].phases[0].built');
