INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/charterhouse:ended:0','landmark','london/charterhouse','Charterhouse','london','ended',1546,NULL,'Carthusian monastery (community disbanded 1538) (handover)','Founded 1371 on the plague cemetery of 1349; the cells took about 60 years to complete. Surrendered 10 June 1537 and formally disbanded 15 November 1538 (VCH). The buildings then stood, divided among Crown grantees, used as a royal storehouse from 1542 and largely derelict, until they were sold to Sir Edward North on 14 April 1546; the monastic community did not continue after 1538.',NULL,NULL,'attested-standing','high','bho-religious-houses-house-carthusian,charterhouse-history,bho-stow-suburbs-without-walls',3,'locations/london/landmarks.json','$[50].phases[0].to');
