INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/mithraeum:gone_by:0','landmark','london/mithraeum','Temple of Mithras','london','gone_by',480,NULL,'Temple of Mithras, later repurposed','Built c. 240–250 (coin dates); MOLA says it was used as a mithraeum for about 80 years and then repurposed, i.e. in the early 4th century. The building stood on; 380 is a modelling estimate for its end, not a dated end of worship.',NULL,NULL,'attested-excavated','high','mola-mithras-mithraism-top-10,british-listed-temple-mithras-grade-ii,london-museum-timeline-roman-london',3,'locations/london/landmarks.json','$[10].phases[0].goneBy');
