INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/bridge-stone-gate:gone_by:0','landmark','london/bridge-stone-gate','Great Stone Gate','london','gone_by',1440,NULL,'Stone gate','Collapsed with two arches in January 1437.',NULL,NULL,'attested-documentary','medium','bho-stow-towers-castels-bridge,bho-stow-gates-wall,current-archaeology-life-across-water-exploring,lamas-medieval-london-bridge-role,bho-stow-bridges-this-citie,bho-austin-canons-priory-southwark,bho-old-new-london-vol,moeml-drawbridge-tower',8,'locations/london/landmarks.json','$[25].phases[0].goneBy');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/roman-quay:gone_by:1','landmark','london/roman-quay','Roman quays and warehouses','london','gone_by',400,NULL,'Timber quays and warehouses','Tree-ring anchors: great quay 63, landing stage c. 70, extension 102, further advances to the mid 3rd century; quays dismantled by the 4th century.',NULL,NULL,'attested-excavated','high','london-archaeologist-brigham-watson-regis-house,gresham-discovering-port-roman-london,britannia-brigham-late-roman-waterfront,rfla-roman-ad-43-410,history-london-port-roman-london-secondary',5,'locations/london/landmarks.json','$[35].phases[1].goneBy');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:london/savoy:gone_by:0','landmark','london/savoy','Savoy Palace, later Savoy Hospital','london','gone_by',1509,NULL,'Savoy Palace','Peter of Savoy''s house from 1245–46; Lancastrian palace of the 1350s; burned 1381 and left a ruin.',NULL,NULL,'attested-documentary','medium','bho-stow-liberties-dutchie-lancaster',1,'locations/london/landmarks.json','$[51].phases[0].goneBy');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:stonehenge/durrington-southern-circle:gone_by:0','landmark','stonehenge/durrington-southern-circle','Durrington Walls Southern Circle (timber)','stonehenge','gone_by',-2300,NULL,'Southern Circle of timber posts (illustrative)','Wikipedia: c. 2600 BCE with four rings, two more c. 200 years later; Current Archaeology: expanded with c. 200 posts c. 2480-2450 BCE. The accounts conflict; built here 2520-2500 BCE to match the settlement. Decay 2400-2300 BCE is a placeholder.',NULL,NULL,'conjectural','low','sto-wp-durrington,sto-archco-durrington,sto-wp-woodhenge,sto-gazetteer-durrington',4,'locations/stonehenge/landmarks.json','$[29].phases[0].goneBy');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:stonehenge/durrington-northern-circle:gone_by:0','landmark','stonehenge/durrington-northern-circle','Durrington Walls Northern Circle (timber)','stonehenge','gone_by',-2300,NULL,'Northern Circle of timber posts (illustrative)','Undated; shown with the Southern Circle (placeholder).',NULL,NULL,'conjectural','low','sto-wp-durrington',1,'locations/stonehenge/landmarks.json','$[30].phases[0].goneBy');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:stonehenge/woodhenge:gone_by:0','landmark','stonehenge/woodhenge','Woodhenge (six oval rings of timber posts)','stonehenge','gone_by',-2350,NULL,'Woodhenge: six oval rings of timber posts (all rings drawn together)','Historic England Research Report 94/2024 (as summarised): timber monument built 2635-2575 cal BC (95%), most likely 2635-2610; drawn 2635-2610 BCE. Ditch and bank are a separate, later landmark (interval 75-440 years). Decay 2500-2350 BCE is a placeholder; the rings may not all have decayed together (corrected after fact review glm-stonehenge-007).',NULL,NULL,'attested-excavated','medium','sto-he-woodhenge-2024-summary,sto-wp-woodhenge,sto-wikipedia-woodhenge,sto-osm-overpass',4,'locations/stonehenge/landmarks.json','$[31].phases[0].goneBy');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:stonehenge/coneybury-henge:gone_by:2','landmark','stonehenge/coneybury-henge','Coneybury henge','stonehenge','gone_by',1500,NULL,'Coneybury henge: grassed, silting ditch','Levelled by ploughing, plausibly medieval (Wikipedia); 1200-1500 CE is a placeholder.',NULL,NULL,'attested-excavated','low','sto-wp-coneybury,sto-osm-overpass',2,'locations/stonehenge/landmarks.json','$[33].phases[2].goneBy');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:stonehenge/amesbury-abbey:gone_by:1','landmark','stonehenge/amesbury-abbey','Amesbury Abbey (nunnery, then Fontevraud priory)','stonehenge','gone_by',1580,NULL,'Fontevraud priory church, new building 1177-1186 (form unknown)','Refounded 1177 as a Fontevraud priory; Henry II then built a new house and church, ready when the nuns moved in on 30 November 1186 (VCH Wilts vol 3). Dissolved c. 1539-1540 (sources differ). Demolition undated; gone by 1580 is a placeholder (corrected after fact review glm-stonehenge-004).',NULL,NULL,'conjectural','low','sto-vch-wilts3-amesbury-priory,sto-wp-amesburyabbey,sto-wikipedia-amesbury-abbey,sto-wp-amesbury',4,'locations/stonehenge/landmarks.json','$[45].phases[1].goneBy');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('landmark:stonehenge/roman-building-cuckoo-stone:gone_by:0','landmark','stonehenge/roman-building-cuckoo-stone','Roman building near the Cuckoo Stone','stonehenge','gone_by',600,NULL,'Small Roman building (generic form)','Roman Britain 43-410 CE; building dates not known.',NULL,NULL,'conjectural','low','sto-wp-cuckoo,sto-wp-amesbury',2,'locations/stonehenge/landmarks.json','$[49].phases[0].goneBy');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/bryn-celli-ddu:located_at','place','england-wales/bryn-celli-ddu','Bryn Celli Ddu','england-wales','located_at',NULL,NULL,'Bryn Celli Ddu','A Neolithic passage tomb on Anglesey under a mound about 26 m across, with a passage aligned on the midsummer sunrise. Cadw describes an earlier bank-and-ditch enclosure with a stone circle on the same spot.',53.2079,-4.2355,'attested-standing','medium','wal-cadw-bryn-celli-ddu',1,'national/places-wales.json','$[0]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/barclodiad-y-gawres:located_at','place','england-wales/barclodiad-y-gawres','Barclodiad y Gawres','england-wales','located_at',NULL,NULL,'Barclodiad y Gawres','A Neolithic passage tomb on the west coast of Anglesey. Several stones carry zig-zags and spirals like those in Irish tombs; Cadw notes Bryn Celli Ddu is the only other tomb in the UK with such art.',53.207,-4.5035,'attested-standing','medium','wal-cadw-barclodiad',1,'national/places-wales.json','$[1]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/pentre-ifan:located_at','place','england-wales/pentre-ifan','Pentre Ifan','england-wales','located_at',NULL,NULL,'Pentre Ifan','The best-preserved Neolithic portal dolmen in Wales: a capstone of about 16 tonnes on three uprights, once at the end of a cairn some 30 m long. Excavated by W. F. Grimes in 1936-7.',51.999,-4.77,'attested-standing','medium','wal-cadw-pentre-ifan,wal-coflein-pentre-ifan',2,'national/places-wales.json','$[2]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/trer-ceiri:located_at','place','england-wales/trer-ceiri','Tre''r Ceiri','england-wales','located_at',NULL,NULL,'Tre''r Ceiri','A stone-walled hillfort at about 480 m on Yr Eifl in Llŷn, crowded with some 150 round and sub-rectangular huts. Excavation shows it was probably built in the later Iron Age and stayed in use until at least the 4th century AD.',52.9747,-4.4238,'attested-excavated','medium','wal-coflein-trer-ceiri',1,'national/places-wales.json','$[3]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/great-orme-mines:located_at','place','england-wales/great-orme-mines','Great Orme copper mines','england-wales','located_at',NULL,NULL,'Great Orme copper mines','Bronze Age copper mines in the limestone of the Great Orme, with kilometres of tunnels dug with bone and stone tools. Nineteen radiocarbon dates span about 1700-900 BC; a 2019 study argues for a boom about 1600-1400 BC that supplied metal across Britain and as far as the Baltic.',53.331,-3.848,'attested-excavated','medium','wal-liverpool-great-orme,wal-great-orme-mines',2,'national/places-wales.json','$[4]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/parys-mountain:located_at','place','england-wales/parys-mountain','Parys Mountain','england-wales','located_at',NULL,NULL,'Parys Mountain','A copper-bearing hill in north Anglesey. Hammerstones and charcoal found in old workings point to Early Bronze Age mining; Roman working is inferred from stamped copper ingots found on Anglesey and Pleiades lists it as a Roman mine.',53.3887,-4.3432,'attested-excavated','low','wal-pleiades-parys-mountain',1,'national/places-wales.json','$[5]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/llyn-cerrig-bach:located_at','place','england-wales/llyn-cerrig-bach','Llyn Cerrig Bach','england-wales','located_at',NULL,NULL,'Llyn Cerrig Bach','A small lake in west Anglesey where more than 150 iron and bronze objects, including chariot fittings, swords, spearheads and slave chains, were found in peat in 1942-3 during airfield building. They are read as offerings made over several centuries.',53.2589,-4.5403,'attested-excavated','medium','wal-museum-llyn-cerrig-bach',1,'national/places-wales.json','$[6]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/castell-henllys:located_at','place','england-wales/castell-henllys','Castell Henllys','england-wales','located_at',NULL,NULL,'Castell Henllys','A small inland promontory fort in north Pembrokeshire, about 88 by 74 m, excavated over many seasons. The main gateway was begun in the 5th century BC; occupation inside ended about the turn of the era, when a settlement was set up in the annexe.',52.0178,-4.7453,'attested-excavated','medium','wal-coflein-castell-henllys',1,'national/places-wales.json','$[7]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/caerleon:located_at','place','england-wales/caerleon','Caerleon','england-wales','located_at',NULL,NULL,'Caerleon','One of three permanent legionary fortresses in Roman Britain, base of the Second Augustan Legion from about AD 75, with baths, barracks and an amphitheatre still visible. A Norman castle and small borough followed in the late 11th century.',51.6099,-2.9565,'attested-excavated','high','wal-pleiades-isca,wal-cadw-caerleon',2,'national/places-wales.json','$[8]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/segontium:located_at','place','england-wales/segontium','Segontium','england-wales','located_at',NULL,NULL,'Segontium','The main Roman fort of north-west Wales, founded under Agricola about AD 77 for a 1,000-strong auxiliary regiment and linked by road to Chester and Caerleon. Coins show it was held until about 394, longer than any other fort in Wales.',53.1373,-4.2658,'attested-excavated','medium','wal-cadw-segontium,wal-pleiades-segontium',2,'national/places-wales.json','$[9]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/carmarthen:located_at','place','england-wales/carmarthen','Carmarthen','england-wales','located_at',NULL,NULL,'Carmarthen','The westernmost town of Roman Britain, Moridunum, capital of the Demetae, with an amphitheatre. A royal castle was founded on the Tywi in the early 12th century and the borough became the centre of English royal government in south-west Wales.',51.8593,-4.3035,'attested-excavated','medium','wal-pleiades-moridunum,wal-coflein-carmarthen-castle',2,'national/places-wales.json','$[10]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/caerwent:located_at','place','england-wales/caerwent','Caerwent','england-wales','located_at',NULL,NULL,'Caerwent','The Roman market town and administrative centre of the Silures, founded about AD 75-80. Its town walls, among the best preserved in northern Europe, still surround the village.',51.6111,-2.7687,'attested-standing','high','wal-cadw-caerwent,wal-pleiades-venta-silurum',2,'national/places-wales.json','$[11]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/dolaucothi:located_at','place','england-wales/dolaucothi','Dolaucothi gold mines','england-wales','located_at',NULL,NULL,'Dolaucothi gold mines','The only known Roman gold mine in Britain, at Pumsaint in Carmarthenshire: opencasts, adits and long aqueducts spread over at least a kilometre, beside a Roman fort.',52.0446,-3.9498,'attested-excavated','low','wal-coflein-dolaucothi',1,'national/places-wales.json','$[12]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/nidum:located_at','place','england-wales/nidum','Nidum','england-wales','located_at',NULL,NULL,'Nidum','A Roman auxiliary fort on the west bank of the river Neath. Excavation shows a first fort of about AD 75-80, a smaller one of 80-90 held until about 125, reoccupation from about 140 to 170 and a late military phase about 275-320.',51.664,-3.8124,'attested-excavated','medium','wal-coflein-nidum,wal-pleiades-nidum',2,'national/places-wales.json','$[13]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/abergavenny:located_at','place','england-wales/abergavenny','Abergavenny','england-wales','located_at',NULL,NULL,'Abergavenny','A Roman fort guarding the Usk valley road, known as Gobannium. A Norman lord built a castle and priory here in the late 11th century and a walled market town grew beside them.',51.8234,-3.0195,'attested-excavated','low','wal-pleiades-gobannium',1,'national/places-wales.json','$[14]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/usk:located_at','place','england-wales/usk','Usk','england-wales','located_at',NULL,NULL,'Usk','Site of an early legionary fortress, Burrium, built in the mid-50s AD during the war against the Silures and given up when the legion moved; Caerleon replaced it about AD 75. A Norman castle and planted borough followed in the 12th century.',51.7039,-2.9025,'attested-excavated','low','wal-pleiades-burrium',1,'national/places-wales.json','$[15]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/canovium:located_at','place','england-wales/canovium','Canovium','england-wales','located_at',NULL,NULL,'Canovium','A Roman auxiliary fort at Caerhun, guarding the crossing of the Conwy on the road from Chester to Caernarfon. It was occupied, with breaks, from Agricola’s campaign of AD 77/8 into the 4th century.',53.216,-3.8341,'attested-excavated','medium','wal-coflein-canovium,wal-pleiades-canovium',2,'national/places-wales.json','$[16]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/tomen-y-mur:located_at','place','england-wales/tomen-y-mur','Tomen y Mur','england-wales','located_at',NULL,NULL,'Tomen y Mur','An upland Roman fort in Meirionnydd with a rare set of surrounding earthworks: a small amphitheatre, parade ground, bath-house and practice camps. A castle mound was later raised inside it.',52.9299,-3.9268,'attested-standing','medium','wal-coflein-tomen-y-mur',1,'national/places-wales.json','$[17]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/brecon-gaer:located_at','place','england-wales/brecon-gaer','Y Gaer, Brecon','england-wales','located_at',NULL,NULL,'Y Gaer, Brecon','A Roman fort west of Brecon, founded about AD 75 where two main roads met and garrisoned by a Spanish cavalry regiment, the Vettones.',51.957,-3.451,'attested-standing','medium','wal-cadw-brecon-gaer',1,'national/places-wales.json','$[18]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/st-davids:located_at','place','england-wales/st-davids','St Davids','england-wales','located_at',NULL,NULL,'St Davids','The monastery founded by St David in the 6th century was already the seat of bishops in the 9th century (Asser names Archbishop Nobis, his kinsman), long before the first Norman bishop in 1115. The present church was begun in 1181; a 12th-century pope ruled two pilgrimages here equal to one to Rome, and Bishop Henry de Gower built the great palace in 1328-47.',51.8819,-5.2678,'attested-standing','medium','wal-cadw-st-davids,wal-asser-life-alfred',2,'national/places-wales.json','$[19]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/llantwit-major:located_at','place','england-wales/llantwit-major','Llantwit Major','england-wales','located_at',NULL,NULL,'Llantwit Major','Llanilltud Fawr, the monastery of St Illtud in the Vale of Glamorgan, was remembered as the great school of early Christian Wales; the 7th-century Life of St Samson is the earliest witness. Carved stones of the 9th-11th centuries commemorate kings of Glywysing.',51.4062,-3.475,'attested-documentary','medium','wal-dwb-illtud',1,'national/places-wales.json','$[20]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/bangor:located_at','place','england-wales/bangor','Bangor','england-wales','located_at',NULL,NULL,'Bangor','A monastery founded by St Deiniol in the 6th century, the seat of the bishops of Gwynedd. The cathedral was rebuilt in stone in the 12th century and damaged in the wars of 1211, 1282 and 1402.',53.2266,-4.1274,'attested-documentary','medium','wal-dwb-deiniol',1,'national/places-wales.json','$[21]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/llandaff:located_at','place','england-wales/llandaff','Llandaff','england-wales','located_at',NULL,NULL,'Llandaff','A church on the Taff associated with Saints Teilo, Dyfrig and Euddogwy. Bishop Urban began the present cathedral in 1120 and the Book of Llandaff was compiled to back its claims.',51.4958,-3.2181,'attested-standing','medium','wal-llandaff-cathedral-history',1,'national/places-wales.json','$[22]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/deganwy:located_at','place','england-wales/deganwy','Deganwy','england-wales','located_at',NULL,NULL,'Deganwy','Twin hills above the Conwy estuary: by tradition the seat of Maelgwn, king of Gwynedd, in the 6th century. It was burnt by lightning in 812 and destroyed by the English in 822. Robert of Rhuddlan held it in the late 11th century; Henry III built a great castle in 1245-50, which Llywelyn ap Gruffudd destroyed in 1263.',53.298,-3.8287,'attested-excavated','medium','wal-coflein-deganwy',1,'national/places-wales.json','$[23]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/dinefwr:located_at','place','england-wales/dinefwr','Dinefwr','england-wales','located_at',NULL,NULL,'Dinefwr','A castle above the Tywi near Llandeilo, thought to have been founded in the later 12th century by the Lord Rhys and remembered as the principal court of Deheubarth. The standing remains are 13th and early 14th century.',51.8768,-4.0185,'attested-standing','medium','wal-coflein-dinefwr',1,'national/places-wales.json','$[24]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/mathrafal:located_at','place','england-wales/mathrafal','Mathrafal','england-wales','located_at',NULL,NULL,'Mathrafal','An earthwork enclosure and mound on the river Banwy, named in later tradition as the chief court of the kings of Powys.',52.6878,-3.2865,'attested-excavated','low','wal-coflein-mathrafal',1,'national/places-wales.json','$[25]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/aberffraw:located_at','place','england-wales/aberffraw','Aberffraw','england-wales','located_at',NULL,NULL,'Aberffraw','By tradition the chief seat of the kings of Gwynedd, on the west coast of Anglesey; the princes styled themselves ‘prince of Aberffraw’ in the 13th century. The settlement declined after a great storm in 1331 altered the coast.',53.1954,-4.4635,'attested-documentary','medium','wal-coflein-aberffraw',1,'national/places-wales.json','$[26]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/dinas-emrys:located_at','place','england-wales/dinas-emrys','Dinas Emrys','england-wales','located_at',NULL,NULL,'Dinas Emrys','A rocky stronghold above Nant Gwynant, the legendary site of Vortigern’s fortress and Merlin’s dragons. Excavations in 1910 and 1954-6 found Iron Age, Roman and early medieval occupation; a stone tower was added at the end of the 12th century.',53.022,-4.079,'attested-excavated','low','wal-coflein-dinas-emrys',1,'national/places-wales.json','$[27]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/llangorse-crannog:located_at','place','england-wales/llangorse-crannog','Llangorse crannog','england-wales','located_at',NULL,NULL,'Llangorse crannog','The only crannog (artificial island) known in Wales, built in Llangorse Lake for the king of Brycheiniog from timbers felled between AD 889 and 893. The Anglo-Saxon Chronicle records that a Mercian army sent by Æthelflæd destroyed ‘Brecenanmere’ in 916 and took the king’s wife captive.',51.931,-3.2628,'attested-excavated','high','wal-nmw-llangors',1,'national/places-wales.json','$[28]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/dinas-powys:located_at','place','england-wales/dinas-powys','Dinas Powys hillfort','england-wales','located_at',NULL,NULL,'Dinas Powys hillfort','A small defended hilltop near Cardiff, excavated by Leslie Alcock in the 1950s. Imported Mediterranean and Gaulish pottery, glass and fine metalworking show a wealthy household of the 5th to 7th centuries.',51.4375,-3.2206,'attested-excavated','medium',NULL,0,'national/places-wales.json','$[29]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/pillar-of-eliseg:located_at','place','england-wales/pillar-of-eliseg','Pillar of Eliseg','england-wales','located_at',NULL,NULL,'Pillar of Eliseg','The shaft of a 9th-century cross near Llangollen, set up by Cyngen, king of Powys (died 854/5), in honour of his great-grandfather Eliseg. Its long Latin inscription, now illegible, traced the dynasty’s descent.',52.9921,-3.1892,'attested-standing','medium','wal-cadw-valle-crucis',1,'national/places-wales.json','$[30]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/chepstow:located_at','place','england-wales/chepstow','Chepstow','england-wales','located_at',NULL,NULL,'Chepstow','A castle on a cliff above the Wye, begun in 1067 by William fitz Osbern, earl of Hereford, and one of the first Norman strongholds in Wales. Its great tower is among the oldest stone castle buildings in Britain; a walled port town grew beside it.',51.6439,-2.6757,'attested-standing','high','wal-cadw-chepstow',1,'national/places-wales.json','$[31]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/pembroke:located_at','place','england-wales/pembroke','Pembroke','england-wales','located_at',NULL,NULL,'Pembroke','A castle on a tidal promontory, established by the Normans about 1093-4 and never taken by the Welsh. The round great tower was built at the start of the 13th century; Henry Tudor, later Henry VII, was born here in 1457.',51.6769,-4.9206,'attested-standing','high','wal-coflein-pembroke',1,'national/places-wales.json','$[32]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/cardiff:located_at','place','england-wales/cardiff','Cardiff','england-wales','located_at',NULL,NULL,'Cardiff','A series of Roman forts stood beside the Taff from the late 50s AD to the late 4th century. About 1081 William I set a castle inside the walls of the last fort, and the borough beside it became the head of the lordship of Glamorgan and one of the larger towns in Wales.',51.4823,-3.1811,'attested-standing','medium','wal-coflein-cardiff,wal-pleiades-cardiff-fort',2,'national/places-wales.json','$[33]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/caerphilly:located_at','place','england-wales/caerphilly','Caerphilly Castle','england-wales','located_at',NULL,NULL,'Caerphilly Castle','The largest castle in Wales, begun in 1268 by Gilbert de Clare, lord of Glamorgan, against Llywelyn ap Gruffudd. Its concentric walls and wide artificial lakes were new to Britain.',51.5761,-3.2203,'attested-standing','high','wal-cadw-caerphilly',1,'national/places-wales.json','$[34]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/dolwyddelan:located_at','place','england-wales/dolwyddelan','Dolwyddelan Castle','england-wales','located_at',NULL,NULL,'Dolwyddelan Castle','A stone keep guarding a route through Snowdonia, built by Llywelyn ap Iorwerth, ruler of Gwynedd from 1201 to 1240. It fell to Edward I in 1283, who refitted it.',53.0531,-3.9083,'attested-standing','medium','wal-cadw-dolwyddelan',1,'national/places-wales.json','$[35]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/castell-y-bere:located_at','place','england-wales/castell-y-bere','Castell y Bere','england-wales','located_at',NULL,NULL,'Castell y Bere','A castle on a rock in the Dysynni valley, begun in 1221 by Llywelyn ap Iorwerth to guard the southern border of Gwynedd. It was taken by Edward I’s forces in 1283 and given up after the Welsh rising of 1294.',52.6583,-3.9711,'attested-standing','high','wal-cadw-castell-y-bere',1,'national/places-wales.json','$[36]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/dolbadarn:located_at','place','england-wales/dolbadarn','Dolbadarn Castle','england-wales','located_at',NULL,NULL,'Dolbadarn Castle','A round stone tower at the foot of the Llanberis pass, most likely built by Llywelyn ap Iorwerth in the late 12th or early 13th century.',53.1166,-4.1142,'attested-standing','medium','wal-cadw-dolbadarn',1,'national/places-wales.json','$[37]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/criccieth:located_at','place','england-wales/criccieth','Criccieth Castle','england-wales','located_at',NULL,NULL,'Criccieth Castle','A castle on a headland in Cardigan Bay. Llywelyn ap Iorwerth built the twin-towered gatehouse, Llywelyn ap Gruffudd added the outer ward, Edward I refitted it, and Owain Glyndŵr burnt it in 1404.',52.9161,-4.2325,'attested-standing','medium','wal-cadw-criccieth',1,'national/places-wales.json','$[38]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/flint:located_at','place','england-wales/flint','Flint','england-wales','located_at',NULL,NULL,'Flint','The first of Edward I’s castles in Wales, begun in 1277 and largely finished by 1284, with a planned borough beside it. Richard II met Henry Bolingbroke here in 1399.',53.2517,-3.1299,'attested-standing','high','wal-cadw-flint',1,'national/places-wales.json','$[39]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/rhuddlan:located_at','place','england-wales/rhuddlan','Rhuddlan','england-wales','located_at',NULL,NULL,'Rhuddlan','The lowest crossing of the Clwyd. Edward the Elder founded a burh here in 921; it was Gruffudd ap Llywelyn’s seat until 1063; Robert of Rhuddlan raised a motte in 1073. Edward I began the present concentric castle in 1277 and issued the Statute of Rhuddlan here in 1284.',53.2892,-3.4642,'attested-standing','medium','wal-cadw-rhuddlan,wal-bodleian-welsh-law',2,'national/places-wales.json','$[40]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/conwy:located_at','place','england-wales/conwy','Conwy','england-wales','located_at',NULL,NULL,'Conwy','Edward I and Master James of St George built the castle and a 1.3 km circuit of town walls here between 1283 and 1287. The site had been the Cistercian abbey of Aberconwy, burial place of Llywelyn ap Iorwerth, which the king moved up the valley to Maenan.',53.2801,-3.8256,'attested-standing','high','wal-cadw-conwy,wal-monasticwales-aberconwy-1186',2,'national/places-wales.json','$[41]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/caernarfon:located_at','place','england-wales/caernarfon','Caernarfon','england-wales','located_at',NULL,NULL,'Caernarfon','Edward I began the castle and walled borough in 1283, with a quay, all at once; work lasted 47 years and was still unfinished about 1330. It was the centre of royal government in North Wales. The castle was in decay by the 16th century.',53.1393,-4.2769,'attested-standing','high','wal-coflein-caernarfon,wal-cadw-caernarfon',2,'national/places-wales.json','$[42]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/harlech:located_at','place','england-wales/harlech','Harlech Castle','england-wales','located_at',NULL,NULL,'Harlech Castle','A concentric castle on a crag above Cardigan Bay, begun in May 1283 and largely complete by 1289. Owain Glyndŵr took it in 1404 and kept his court and family here until it was retaken in 1409; it fell again to the Yorkists in 1468 after a long siege.',52.86,-4.1092,'attested-standing','high','wal-coflein-harlech,wal-cadw-harlech',2,'national/places-wales.json','$[43]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/beaumaris:located_at','place','england-wales/beaumaris','Beaumaris','england-wales','located_at',NULL,NULL,'Beaumaris','The last of Edward I’s Welsh castles, begun in 1295 after the rising of Madog ap Llywelyn. Money ran short and work petered out by the 1320s, leaving the towers below their planned height. The borough became the main port of Anglesey.',53.2649,-4.0896,'attested-standing','high','wal-coflein-beaumaris,wal-cadw-beaumaris',2,'national/places-wales.json','$[44]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/kidwelly:located_at','place','england-wales/kidwelly','Kidwelly','england-wales','located_at',NULL,NULL,'Kidwelly','A Norman ringwork of the early 12th century, rebuilt in stone as a concentric castle in the late 13th and 14th centuries. The Lord Rhys captured it in 1159.',51.7394,-4.3057,'attested-standing','medium','wal-cadw-kidwelly',1,'national/places-wales.json','$[45]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/montgomery:located_at','place','england-wales/montgomery','Montgomery','england-wales','located_at',NULL,NULL,'Montgomery','Henry III began the stone castle about 1223 against Llywelyn ap Iorwerth, replacing the nearby timber castle of Hen Domen. It withstood attacks in 1228, 1231 and 1245. The treaty that recognised Llywelyn ap Gruffudd as Prince of Wales was sealed at the nearby ford in 1267.',52.5633,-3.1499,'attested-standing','medium','wal-cadw-montgomery',1,'national/places-wales.json','$[46]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/dolforwyn:located_at','place','england-wales/dolforwyn','Dolforwyn Castle','england-wales','located_at',NULL,NULL,'Dolforwyn Castle','A castle built by Llywelyn ap Gruffudd in 1273 on a ridge above the Severn, in defiance of the king and facing royal Montgomery. Roger Mortimer took it in 1277 after a two-week siege.',52.5465,-3.252,'attested-excavated','high','wal-cadw-dolforwyn',1,'national/places-wales.json','$[47]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/raglan:located_at','place','england-wales/raglan','Raglan Castle','england-wales','located_at',NULL,NULL,'Raglan Castle','A late medieval fortress-palace in Gwent. Sir William ap Thomas built the moated Great Tower about 1435 and his son William Herbert, earl of Pembroke, enlarged it.',51.7703,-2.8501,'attested-standing','high','wal-cadw-raglan',1,'national/places-wales.json','$[48]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/denbigh:located_at','place','england-wales/denbigh','Denbigh','england-wales','located_at',NULL,NULL,'Denbigh','A Welsh princely residence of Dafydd ap Gruffudd, whose attack on Hawarden in 1282 set off Edward I’s final war. Henry de Lacy then built a large castle and walled town on the site; the half-built castle was captured in the rising of 1294.',53.1806,-3.4206,'attested-standing','medium','wal-cadw-denbigh',1,'national/places-wales.json','$[49]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/sycharth:located_at','place','england-wales/sycharth','Sycharth','england-wales','located_at',NULL,NULL,'Sycharth','A motte and bailey in the Cynllaith valley, the chief home of Owain Glyndŵr. A poem of about 1390 praises its fine timber hall on a green mound; it was burnt in 1403 and has no later history.',52.8248,-3.1805,'attested-excavated','medium','wal-coflein-sycharth,wal-dwb-owain-glyndwr',2,'national/places-wales.json','$[50]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/dinas-bran:located_at','place','england-wales/dinas-bran','Castell Dinas Brân','england-wales','located_at',NULL,NULL,'Castell Dinas Brân','A hilltop castle above Llangollen, built inside an Iron Age hillfort by the rulers of northern Powys in the 1260s and burnt by its own garrison before Edward I’s army in 1277.',52.9792,-3.1596,'attested-standing','medium',NULL,0,'national/places-wales.json','$[51]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/tintern:located_at','place','england-wales/tintern','Tintern Abbey','england-wales','located_at',NULL,NULL,'Tintern Abbey','The first Cistercian abbey in Wales, founded in 1131 on the Wye. The great church was begun in 1269. The abbey surrendered in 1536 in the first round of the dissolution.',51.6971,-2.6772,'attested-standing','high','wal-cadw-tintern',1,'national/places-wales.json','$[52]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/strata-florida:located_at','place','england-wales/strata-florida','Strata Florida Abbey','england-wales','located_at',NULL,NULL,'Strata Florida Abbey','A Cistercian abbey in the Ceredigion uplands, founded in 1164 by a Norman lord and soon taken under the patronage of the Lord Rhys. The monks entered their new church in 1201. Welsh princes were buried here and it supported the Welsh cause; it closed by 1539.',52.2754,-3.8383,'attested-excavated','high','wal-coflein-strata-florida,wal-cadw-strata-florida',2,'national/places-wales.json','$[53]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/valle-crucis:located_at','place','england-wales/valle-crucis','Valle Crucis Abbey','england-wales','located_at',NULL,NULL,'Valle Crucis Abbey','A Cistercian abbey near Llangollen, founded in 1201 by Madog ap Gruffudd, prince of northern Powys, and named after the nearby Pillar of Eliseg. It was dissolved in 1537.',52.9887,-3.1865,'attested-standing','high','wal-cadw-valle-crucis',1,'national/places-wales.json','$[54]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/neath-abbey:located_at','place','england-wales/neath-abbey','Neath Abbey','england-wales','located_at',NULL,NULL,'Neath Abbey','Founded in 1130 by the Norman knight Richard de Granville; by the late 13th century one of the wealthiest abbeys in Wales.',51.6609,-3.8261,'attested-standing','medium','wal-cadw-neath-abbey',1,'national/places-wales.json','$[55]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/margam:located_at','place','england-wales/margam','Margam Abbey','england-wales','located_at',NULL,NULL,'Margam Abbey','A Cistercian abbey founded about 1147 and dissolved in 1536, thought to stand on an earlier monastic site: early Christian carved stones were found around it. The western part of the nave survives as the parish church.',51.5624,-3.7299,'attested-standing','high','wal-coflein-margam',1,'national/places-wales.json','$[56]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/basingwerk:located_at','place','england-wales/basingwerk','Basingwerk Abbey','england-wales','located_at',NULL,NULL,'Basingwerk Abbey','An abbey near Holywell on the Dee estuary, founded in 1131 and much rebuilt in the 13th century. Wat’s Dyke reaches the estuary close by.',53.288,-3.2073,'attested-standing','medium','wal-cadw-basingwerk,wal-monasticwales-basingwerk',2,'national/places-wales.json','$[57]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/swansea:located_at','place','england-wales/swansea','Swansea','england-wales','located_at',NULL,NULL,'Swansea','The castle at the mouth of the Tawe was founded in or soon after 1106 as the head of the Norman lordship of Gower; a borough and port grew beside it. The first castle was earth and timber, rebuilt in stone probably between 1221 and 1284.',51.6204,-3.9411,'attested-documentary','medium','wal-coflein-swansea-castle',1,'national/places-wales.json','$[58]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/haverfordwest:located_at','place','england-wales/haverfordwest','Haverfordwest','england-wales','located_at',NULL,NULL,'Haverfordwest','A castle founded about 1110 by Tancred, a Fleming, at the tidal limit of the Western Cleddau. The town below it became one of the largest and richest in medieval Wales.',51.8024,-4.9703,'attested-standing','medium','wal-coflein-haverfordwest',1,'national/places-wales.json','$[59]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/brecon:located_at','place','england-wales/brecon','Brecon','england-wales','located_at',NULL,NULL,'Brecon','Bernard de Neufmarché defeated the king of Brycheiniog near here in 1093 and built a castle and a Benedictine priory (now the cathedral) at the meeting of the Usk and Honddu. A walled town followed.',51.9513,-3.3918,'attested-standing','medium',NULL,0,'national/places-wales.json','$[60]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/wrexham:located_at','place','england-wales/wrexham','Wrexham','england-wales','located_at',NULL,NULL,'Wrexham','A market town on the Welsh side of the border, first recorded in the 12th century. It was never a chartered walled borough but by the 16th century was among the most populous towns in Wales.',53.0467,-2.9936,'attested-documentary','low',NULL,0,'national/places-wales.json','$[61]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/aberystwyth:located_at','place','england-wales/aberystwyth','Aberystwyth','england-wales','located_at',NULL,NULL,'Aberystwyth','Edward I’s brother Edmund began the castle and borough in 1277, at first called Llanbadarn. Owain Glyndŵr held it from 1404 to 1408.',52.4133,-4.0895,'attested-standing','medium','wal-dwb-owain-glyndwr',1,'national/places-wales.json','$[62]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/monmouth:located_at','place','england-wales/monmouth','Monmouth','england-wales','located_at',NULL,NULL,'Monmouth','William fitz Osbern built a castle where the Monnow meets the Wye soon after 1066; a priory and walled town followed. Henry V was born in the castle in 1386 or 1387. A Roman fort, Blestium, had stood here.',51.8125,-2.7167,'attested-standing','medium',NULL,0,'national/places-wales.json','$[63]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/machynlleth:located_at','place','england-wales/machynlleth','Machynlleth','england-wales','located_at',NULL,NULL,'Machynlleth','A small market town in the Dyfi valley, with a market charter of 1291. By tradition Owain Glyndŵr was crowned Prince of Wales and held a parliament here in 1404.',52.591,-3.849,'attested-documentary','low',NULL,0,'national/places-wales.json','$[64]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/battle-mynydd-carn:located_at','place','england-wales/battle-mynydd-carn','Battle of Mynydd Carn (site unknown)','england-wales','located_at',NULL,NULL,'Battle of Mynydd Carn (site unknown)','In 1081 Gruffudd ap Cynan, returning from exile in Ireland, and Rhys ap Tewdwr defeated and killed Trahaearn ap Caradog, Caradog ap Gruffudd and Meilyr ap Rhiwallon. The victory secured Gwynedd for Gruffudd’s line and Deheubarth for Rhys’s.',51.7642,-4.7603,'attested-documentary','low','wal-coflein-mynydd-carn,wal-dwb-gruffudd-ap-cynan,wal-cadw-battlefields',3,'national/places-wales.json','$[65]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/battle-crug-mawr:located_at','place','england-wales/battle-crug-mawr','Battle of Crug Mawr','england-wales','located_at',NULL,NULL,'Battle of Crug Mawr','In 1136 Owain and Cadwaladr of Gwynedd with Gruffudd ap Rhys routed a Norman and Flemish army near Cardigan; many of the defeated drowned in the Teifi. It was the largest Welsh victory of the rising that followed Henry I’s death.',52.0958,-4.6204,'attested-documentary','medium','wal-coflein-crug-mawr,wal-cadw-battlefields',2,'national/places-wales.json','$[66]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/battle-orewin-bridge:located_at','place','england-wales/battle-orewin-bridge','Battle of Orewin Bridge','england-wales','located_at',NULL,NULL,'Battle of Orewin Bridge','On 11 December 1282 the king’s forces with Roger Mortimer and Gruffudd ap Gwenwynwyn came on the Welsh army without warning near Builth. Llywelyn ap Gruffudd, Prince of Wales, and his leading men were killed; native rule in Wales ended within months.',52.1532,-3.4192,'attested-documentary','medium','wal-coflein-irfon-bridge,wal-dwb-llywelyn-ap-gruffydd,wal-cadw-battlefields',3,'national/places-wales.json','$[67]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/battle-bryn-glas:located_at','place','england-wales/battle-bryn-glas','Battle of Bryn Glas','england-wales','located_at',NULL,NULL,'Battle of Bryn Glas','On 22 June 1402 Owain Glyndŵr’s men defeated the levies of Herefordshire at Pilleth in Maelienydd and captured Edmund Mortimer, who then joined Glyndŵr’s cause.',52.3066,-3.0938,'attested-documentary','medium','wal-coflein-bryn-glas,wal-dwb-owain-glyndwr,wal-cadw-battlefields',3,'national/places-wales.json','$[68]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/battle-bryn-derwin:located_at','place','england-wales/battle-bryn-derwin','Battle of Bryn Derwin','england-wales','located_at',NULL,NULL,'Battle of Bryn Derwin','In 1255 Llywelyn ap Gruffudd defeated his brothers Owain and Dafydd and became sole ruler of Gwynedd west of the Conwy, the first step toward his principality.',52.995,-4.285,'attested-documentary','low','wal-dwb-llywelyn-ap-gruffydd,wal-cadw-battlefields',2,'national/places-wales.json','$[69]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/stonehenge:located_at','place','england-wales/stonehenge','Stonehenge','england-wales','located_at',NULL,NULL,'Stonehenge','The ditch and bank were dug about 3000 BCE and the great stones set up about 2500 BCE. The bluestones were rearranged two or three centuries later and the last known digging, the Y and Z holes, dates to 1800-1500 BCE.',51.179,-1.826,'attested-standing','high','nat-eh-stonehenge',1,'national/places.json','$[0]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/durrington-walls:located_at','place','england-wales/durrington-walls','Durrington Walls','england-wales','located_at',NULL,NULL,'Durrington Walls','A very large late Neolithic settlement beside the Avon, later enclosed by Britain''s largest henge. It is linked to the building of the sarsen phase at Stonehenge, 3 km away.',51.192,-1.787,'attested-excavated','medium','nat-eh-stonehenge-reconstructed',1,'national/places.json','$[1]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/avebury:located_at','place','england-wales/avebury','Avebury','england-wales','located_at',NULL,NULL,'Avebury','The largest stone circle in Britain, inside a huge henge ditch, built and altered from about 2850 to about 2200 BCE. Its monuments were abandoned around 1800 BCE.',51.429,-1.854,'attested-standing','high','nat-eh-avebury',1,'national/places.json','$[2]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/silbury-hill:located_at','place','england-wales/silbury-hill','Silbury Hill','england-wales','located_at',NULL,NULL,'Silbury Hill','The largest artificial prehistoric mound in Europe, probably raised over a short period between about 2470 and 2350 BCE. Its purpose is unknown.',51.416,-1.857,'attested-standing','high','nat-eh-silbury',1,'national/places.json','$[3]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/west-kennet-long-barrow:located_at','place','england-wales/west-kennet-long-barrow','West Kennet Long Barrow','england-wales','located_at',NULL,NULL,'West Kennet Long Barrow','One of the largest Neolithic chambered tombs in Britain, built around 3650 BCE, used for at least a thousand years and blocked with great sarsens around 2000 BCE.',51.409,-1.851,'attested-standing','high','nat-eh-west-kennet',1,'national/places.json','$[4]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/windmill-hill:located_at','place','england-wales/windmill-hill','Windmill Hill','england-wales','located_at',NULL,NULL,'Windmill Hill','The largest known Neolithic causewayed enclosure, three rings of interrupted ditch on a low hill near Avebury.',51.441,-1.876,'attested-excavated','high','nat-eh-windmill-hill',1,'national/places.json','$[5]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/hambledon-hill:located_at','place','england-wales/hambledon-hill','Hambledon Hill','england-wales','located_at',NULL,NULL,'Hambledon Hill','A chalk spur in Dorset used twice: as a large early Neolithic enclosure complex and, three thousand years later, as a multivallate hillfort.',50.912,-2.222,'attested-excavated','medium',NULL,0,'national/places.json','$[6]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/cissbury:located_at','place','england-wales/cissbury','Cissbury','england-wales','located_at',NULL,NULL,'Cissbury','Among the earliest flint mines in Britain, with over 200 shafts on the South Downs, later enclosed by one of the largest hillforts in Sussex.',50.86,-0.383,'attested-excavated','medium',NULL,0,'national/places.json','$[7]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/langdale-axe-factory:located_at','place','england-wales/langdale-axe-factory','Langdale axe quarries','england-wales','located_at',NULL,NULL,'Langdale axe quarries','High fell-side quarries whose green volcanic stone was made into polished axes found all over Britain.',54.4559,-3.1229,'attested-excavated','medium',NULL,0,'national/places.json','$[8]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/castlerigg:located_at','place','england-wales/castlerigg','Castlerigg','england-wales','located_at',NULL,NULL,'Castlerigg','A ring of 38 stones among the Lake District fells, probably raised in the late Neolithic.',54.603,-3.098,'attested-standing','low','nat-eh-castlerigg',1,'national/places.json','$[9]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/thornborough-henges:located_at','place','england-wales/thornborough-henges','Thornborough Henges','england-wales','located_at',NULL,NULL,'Thornborough Henges','Three large henges in a line across the Ure-Swale plain, the largest ritual complex between the Thames and Orkney.',54.21,-1.563,'attested-standing','medium','nat-eh-thornborough',1,'national/places.json','$[10]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/arbor-low:located_at','place','england-wales/arbor-low','Arbor Low','england-wales','located_at',NULL,NULL,'Arbor Low','A henge and recumbent stone circle on the White Peak limestone plateau.',53.169,-1.762,'attested-standing','low',NULL,0,'national/places.json','$[11]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/grimes-graves:located_at','place','england-wales/grimes-graves','Grime''s Graves','england-wales','located_at',NULL,NULL,'Grime''s Graves','A field of more than 400 late Neolithic flint mine shafts in the Norfolk Breckland. The deep galleried shafts were worked from about 2650 to about 2400 BCE and shallower pits for perhaps three centuries more; mining resumed briefly in the mid 2nd millennium BCE.',52.476,0.675,'attested-excavated','high','nat-eh-grimes-graves,nat-healy-2018-grimes-graves',2,'national/places.json','$[12]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/seahenge:located_at','place','england-wales/seahenge','Holme timber circle (Seahenge)','england-wales','located_at',NULL,NULL,'Holme timber circle (Seahenge)','A ring of 55 split oak posts around an inverted tree stump, built on a saltmarsh. Tree rings show the timbers were felled in 2049 BCE.',52.968,0.521,'attested-excavated','medium',NULL,0,'national/places.json','$[13]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/flag-fen:located_at','place','england-wales/flag-fen','Flag Fen','england-wales','located_at',NULL,NULL,'Flag Fen','A kilometre-long post alignment and timber platform across the fen edge near Peterborough, built in stages between about 1365 and 967 BCE and used for ritual deposits long afterwards.',52.574,-0.19,'attested-excavated','medium','nat-wp-flag-fen',1,'national/places.json','$[14]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/must-farm:located_at','place','england-wales/must-farm','Must Farm','england-wales','located_at',NULL,NULL,'Must Farm','A small late Bronze Age settlement of round houses on stilts over a fen channel, destroyed by fire very soon after it was built and preserved in the silt.',52.555,-0.178,'attested-excavated','medium',NULL,0,'national/places.json','$[15]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/grimspound:located_at','place','england-wales/grimspound','Grimspound','england-wales','located_at',NULL,NULL,'Grimspound','The best-known of the Bronze Age enclosed settlements on Dartmoor, part of a moor then divided by long field boundaries (reaves).',50.613,-3.837,'attested-standing','low','nat-eh-grimspound',1,'national/places.json','$[16]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/uffington:located_at','place','england-wales/uffington','Uffington White Horse and Castle','england-wales','located_at',NULL,NULL,'Uffington White Horse and Castle','A 110 m stylised horse cut into the chalk of the Berkshire Downs, with an early Iron Age hillfort on the ridge above.',51.578,-1.567,'attested-standing','medium','nat-eh-uffington',1,'national/places.json','$[17]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/maiden-castle:located_at','place','england-wales/maiden-castle','Maiden Castle','england-wales','located_at',NULL,NULL,'Maiden Castle','One of the largest hillforts in Britain (Ham Hill in Somerset is larger, at 84 ha). In the middle Iron Age (about 400-120 BCE) it was the main settlement of southern Dorset; by the Roman invasion it was almost empty.',50.695,-2.47,'attested-excavated','high','nat-eh-maiden-castle,nat-ox-hillforts-ham-hill',2,'national/places.json','$[18]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/danebury:located_at','place','england-wales/danebury','Danebury','england-wales','located_at',NULL,NULL,'Danebury','The most thoroughly excavated hillfort in Britain, with streets of round houses and thousands of grain storage pits; perhaps 200-350 people lived inside.',51.137,-1.538,'attested-excavated','medium','nat-wp-danebury',1,'national/places.json','$[19]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/cadbury-castle:located_at','place','england-wales/cadbury-castle','Cadbury Castle','england-wales','located_at',NULL,NULL,'Cadbury Castle','A Somerset hillfort reoccupied on a large scale in the late 5th and 6th centuries, one of the strongest pieces of evidence for post-Roman British lordship in the south-west.',51.024,-2.531,'attested-excavated','medium',NULL,0,'national/places.json','$[20]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/glastonbury-lake-village:located_at','place','england-wales/glastonbury-lake-village','Glastonbury Lake Village','england-wales','located_at',NULL,NULL,'Glastonbury Lake Village','A waterlogged Iron Age village in the Somerset Levels, exceptionally well preserved.',51.1639,-2.7265,'attested-excavated','medium',NULL,0,'national/places.json','$[21]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/hengistbury-head:located_at','place','england-wales/hengistbury-head','Hengistbury Head','england-wales','located_at',NULL,NULL,'Hengistbury Head','The main known port of late Iron Age Britain before Caesar: Italian wine, glass and figs came in, and metals went out to Armorica.',50.716,-1.754,'attested-excavated','medium','nat-wp-hengistbury',1,'national/places.json','$[22]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/stanwick:located_at','place','england-wales/stanwick','Stanwick','england-wales','located_at',NULL,NULL,'Stanwick','Some 300 hectares of earthworks in North Yorkshire, probably the seat of the Brigantian rulers who were clients of Rome until about 69 CE.',54.502,-1.722,'attested-excavated','medium','nat-eh-stanwick',1,'national/places.json','$[23]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/london:located_at','place','england-wales/london','London','england-wales','located_at',NULL,NULL,'London','Founded about 47-50 CE, burned in 60/61, the largest town of Roman Britain, then almost deserted for two centuries. From the late 9th century it grew back inside its Roman walls and by 1377 had about three times as many taxpayers as any other English town.',51.509,-0.087,'attested-excavated','medium','nat-wp-historical-population,nat-londonmuseum-roman-timeline,nat-eh-london-wall',3,'national/places.json','$[24]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/colchester:located_at','place','england-wales/colchester','Colchester','england-wales','located_at',NULL,NULL,'Colchester','The chief centre of late Iron Age Britain, then a legionary fortress and the first Roman colonia, burned by Boudica in 60/61. It was tenth among English towns in the 1377 poll tax.',51.889,0.898,'attested-excavated','medium','nat-wp-camulodunum,nat-wp-historical-population,nat-vch-colchester-roman,nat-vch-colchester-medieval',4,'national/places.json','$[25]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/st-albans:located_at','place','england-wales/st-albans','St Albans','england-wales','located_at',NULL,NULL,'St Albans','The third great town of Roman Britain by tradition, burned by Boudica in 61. The medieval abbey and town grew on the hill outside the Roman walls, around the supposed grave of Britain''s first martyr.',51.75,-0.354,'attested-excavated','medium','nat-wp-verulamium,nat-eh-st-albans-wall',2,'national/places.json','$[26]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/york:located_at','place','england-wales/york','York','england-wales','located_at',NULL,NULL,'York','Founded as a legionary fortress in 71. Two emperors died here and Constantine was proclaimed here in 306. It was the Viking capital of the north from 866/7 to 954 and the second town of England in 1377.',53.96,-1.082,'attested-excavated','medium','nat-wp-eboracum,nat-wp-scandinavian-york,nat-wp-historical-population,nat-vch-york-pre-conquest',4,'national/places.json','$[27]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/lincoln:located_at','place','england-wales/lincoln','Lincoln','england-wales','located_at',NULL,NULL,'Lincoln','A fortress of about 60 CE turned into a colonia for veterans, probably in 86. It revived under Danish rule and stood among the four or five largest English towns from Domesday to the 13th century.',53.234,-0.538,'attested-excavated','medium','nat-wp-lindum,nat-wp-danelaw,nat-wp-historical-population,nat-eh-lincoln-bishops-palace',4,'national/places.json','$[28]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/gloucester:located_at','place','england-wales/gloucester','Gloucester','england-wales','located_at',NULL,NULL,'Gloucester','A colonia founded under Nerva at the lowest crossing of the Severn. It was eighth by Russell''s Domesday estimate and seventeenth in 1377.',51.865,-2.246,'attested-excavated','medium','nat-wp-glevum,nat-wp-historical-population,nat-vch-gloucester-intro,nat-vch-gloucester-saxon,nat-vch-gloucester-abbey',5,'national/places.json','$[29]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/chester:located_at','place','england-wales/chester','Chester','england-wales','located_at',NULL,NULL,'Chester','Begun in the mid 70s as the largest legionary fortress in Britain and held until the late 4th or early 5th century. Refortified in 907, it became the seat of a Norman marcher earldom.',53.19,-2.891,'attested-excavated','medium','nat-wp-deva,nat-vch-chester-roman,nat-vch-chester-early-medieval,nat-eh-chester-amphitheatre',4,'national/places.json','$[30]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/wroxeter:located_at','place','england-wales/wroxeter','Wroxeter','england-wales','located_at',NULL,NULL,'Wroxeter','Founded as a military base about 47 and refounded as a city in the 90s. At 78 hectares it was one of the largest cities of Roman Britain. Most of the Roman city was never built over, but a small community stayed on by the river ford, where the village and St Andrew''s church now stand.',52.674,-2.644,'attested-excavated','high','nat-eh-wroxeter',1,'national/places.json','$[31]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/silchester:located_at','place','england-wales/silchester','Silchester','england-wales','located_at',NULL,NULL,'Silchester','An Iron Age centre founded about 20-10 BCE which became a Roman town and, unusually, was never reoccupied.',51.357,-1.082,'attested-excavated','high','nat-eh-silchester',1,'national/places.json','$[32]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/richborough:located_at','place','england-wales/richborough','Richborough','england-wales','located_at',NULL,NULL,'Richborough','Widely believed to be the landing place of 43 CE and long the formal gateway to Britain. The town was cleared after 250 for a fort, rebuilt in stone in 275-290.',51.293,1.332,'attested-excavated','high','nat-eh-richborough',1,'national/places.json','$[33]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/canterbury:located_at','place','england-wales/canterbury','Canterbury','england-wales','located_at',NULL,NULL,'Canterbury','Roman capital of Kent, then from 597 the centre of the English church. It was fourteenth in the 1377 poll tax and tenth by wealth in the 1520s.',51.28,1.08,'attested-excavated','medium','nat-wp-kent,nat-wp-historical-population,nat-eh-st-augustines,nat-vch-canterbury-christ-church',4,'national/places.json','$[34]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/winchester:located_at','place','england-wales/winchester','Winchester','england-wales','located_at',NULL,NULL,'Winchester','Roman Venta, refounded by Alfred with a new street grid and one of the two largest assessments in the Burghal Hidage (2,400 hides, the same as Wallingford). It was second only to London at Domesday but thirtieth in the 1377 poll tax.',51.063,-1.317,'attested-excavated','medium','nat-wp-winchester,nat-wp-burghal-hidage,nat-wp-historical-population,nat-vch-winchester-st-swithun,nat-ads-burghal-hidage',5,'national/places.json','$[35]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/cirencester:located_at','place','england-wales/cirencester','Cirencester','england-wales','located_at',NULL,NULL,'Cirencester','Civitas capital of the Dobunni and, on the usual reconstruction, capital of the 4th-century province of Britannia Prima.',51.719,-1.968,'attested-excavated','medium','nat-wp-roman-britain,nat-eh-cirencester-amphitheatre',2,'national/places.json','$[36]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/bath:located_at','place','england-wales/bath','Bath','england-wales','located_at',NULL,NULL,'Bath','A sanctuary and bathing complex around the hot spring, not an ordinary town. The Roman Baths'' own timeline has the buildings collapsing by about 500 and a Saxon church founded in 675.',51.381,-2.359,'attested-excavated','medium','nat-romanbaths-timeline,nat-wp-burghal-hidage,nat-vch-bath-priory',3,'national/places.json','$[37]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/exeter:located_at','place','england-wales/exeter','Exeter','england-wales','located_at',NULL,NULL,'Exeter','The western end of the Fosse Way, held successively as fortress, Roman town, burh and cathedral city. It ranked 24th in 1377 and 6th in the 1520s.',50.722,-3.53,'attested-excavated','medium','nat-wp-burghal-hidage,nat-wp-historical-population',2,'national/places.json','$[38]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/leicester:located_at','place','england-wales/leicester','Leicester','england-wales','located_at',NULL,NULL,'Leicester','Civitas capital of the Corieltauvi and later one of the Five Boroughs of the Danelaw. It ranked eighteenth in 1377.',52.635,-1.139,'attested-excavated','medium','nat-wp-danelaw,nat-wp-historical-population,nat-eh-jewry-wall',3,'national/places.json','$[39]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/chichester:located_at','place','england-wales/chichester','Chichester','england-wales','located_at',NULL,NULL,'Chichester','Roman capital of the client kingdom of Togidubnus and its successor civitas, refortified as a burh and made a bishop''s seat in 1075.',50.836,-0.78,'attested-excavated','medium','nat-wp-burghal-hidage,nat-vch-chichester',2,'national/places.json','$[40]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/fishbourne:located_at','place','england-wales/fishbourne','Fishbourne Roman Palace','england-wales','located_at',NULL,NULL,'Fishbourne Roman Palace','The largest Roman residence known north of the Alps, commonly linked to the client king Togidubnus.',50.837,-0.81,'attested-excavated','medium',NULL,0,'national/places.json','$[41]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/dorchester:located_at','place','england-wales/dorchester','Dorchester','england-wales','located_at',NULL,NULL,'Dorchester','Founded about 70 CE, after nearby Maiden Castle had emptied.',50.715,-2.437,'attested-excavated','medium','nat-eh-maiden-castle',1,'national/places.json','$[42]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/caistor-st-edmund:located_at','place','england-wales/caistor-st-edmund','Caistor St Edmund','england-wales','located_at',NULL,NULL,'Caistor St Edmund','A small Roman town laid out in Iceni territory after the Boudican revolt and never built over.',52.583,1.292,'attested-excavated','medium',NULL,0,'national/places.json','$[43]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/aldborough:located_at','place','england-wales/aldborough','Aldborough','england-wales','located_at',NULL,NULL,'Aldborough','The northernmost civitas capital of Roman Britain: a trading settlement from about 70, laid out as a planned town about 120 and walled in stone in the late 2nd century.',54.092,-1.382,'attested-excavated','medium','nat-eh-aldborough',1,'national/places.json','$[44]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/carlisle:located_at','place','england-wales/carlisle','Carlisle','england-wales','located_at',NULL,NULL,'Carlisle','The Roman town at the west end of the frontier. It was taken into the English kingdom only in 1092.',54.895,-2.937,'attested-excavated','medium','nat-eh-carlisle-castle',1,'national/places.json','$[45]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/brough-on-humber:located_at','place','england-wales/brough-on-humber','Brough-on-Humber','england-wales','located_at',NULL,NULL,'Brough-on-Humber','Usually taken to be the civitas centre of the Parisi, on the strength of one theatre inscription.',53.728,-0.576,'attested-excavated','low',NULL,0,'national/places.json','$[46]');
