INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/catterick:located_at','place','england-wales/catterick','Catterick','england-wales','located_at',NULL,NULL,'Catterick','A Roman fort and town at the Swale crossing; Bede names it as a place where Paulinus baptised.',54.3842,-1.6497,'attested-excavated','medium',NULL,0,'national/places.json','$[48]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/corbridge:located_at','place','england-wales/corbridge','Corbridge','england-wales','located_at',NULL,NULL,'Corbridge','The most northerly town of the Roman empire, where Dere Street crossed the Tyne.',54.978,-2.03,'attested-excavated','medium','nat-eh-corbridge',1,'national/places.json','$[49]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/vindolanda:located_at','place','england-wales/vindolanda','Vindolanda','england-wales','located_at',NULL,NULL,'Vindolanda','A fort built before Hadrian''s Wall and rebuilt nine times. Its ink writing tablets, of about 100 CE, are the oldest surviving handwritten documents in Britain.',54.991,-2.361,'attested-excavated','medium','nat-vindolanda',1,'national/places.json','$[50]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/housesteads:located_at','place','england-wales/housesteads','Housesteads','england-wales','located_at',NULL,NULL,'Housesteads','Built within a decade of 122 for an 800-strong infantry regiment, and held to the end of the 4th century.',55.013,-2.331,'attested-standing','medium','nat-eh-housesteads',1,'national/places.json','$[51]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/chesters:located_at','place','england-wales/chesters','Chesters','england-wales','located_at',NULL,NULL,'Chesters','Built about 124 for a 500-strong cavalry regiment and occupied until the Roman army left Britain.',55.026,-2.139,'attested-standing','medium','nat-eh-chesters',1,'national/places.json','$[52]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('place:england-wales/birdoswald:located_at','place','england-wales/birdoswald','Birdoswald','england-wales','located_at',NULL,NULL,'Birdoswald','A Wall fort where large timber halls show a community staying on under local leaders after Roman pay stopped.',54.99,-2.602,'attested-excavated','medium','nat-eh-birdoswald',1,'national/places.json','$[53]');
