INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('line:england-wales/hadrians-wall:existed','line','england-wales/hadrians-wall','Hadrian’s Wall','england-wales','existed',122,410,'frontier-wall: Hadrian’s Wall','The north-west frontier of the Roman empire for nearly 300 years: a wall 80 Roman miles long from the Tyne to the Solway, built by the army on Hadrian’s orders after his visit in AD 122, with forts, milecastles and turrets. It was given up about AD 142 when the frontier moved north to the Antonine Wall, and reoccupied some twenty years later.',NULL,NULL,'attested-standing','high','wal-eh-hadrians-wall',1,'national/lines.json','$[31]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('line:england-wales/military-way:existed','line','england-wales/military-way','Military Way (Hadrian’s Wall)','england-wales','existed',160,410,'roman-road: Military Way (Hadrian’s Wall)','The road added behind Hadrian’s Wall when it was recommissioned about AD 160, linking the forts and milecastles.',NULL,NULL,'reconstructed','medium','wal-eh-hadrians-wall',1,'national/lines.json','$[32]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('line:england-wales/offas-dyke:existed','line','england-wales/offas-dyke','Offa’s Dyke','england-wales','existed',785,NULL,'dyke: Offa’s Dyke','A bank up to 2.5 m high with a ditch on the Welsh side, the longest earthwork in Britain, marking the western edge of Mercia. Asser, writing about 893, credits it to King Offa (757-796); English Heritage places the work in the 780s.',NULL,NULL,'attested-standing','medium','wal-eh-offas-dyke,wal-oda-dating',2,'national/lines.json','$[33]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('line:england-wales/offas-dyke-wye:existed','line','england-wales/offas-dyke-wye','Offa’s Dyke (lower Wye section)','england-wales','existed',785,NULL,'dyke: Offa’s Dyke (lower Wye section)','Lengths of bank on the English side of the Wye gorge, from Sedbury Cliffs on the Severn to near Redbrook and English Bicknor, long treated as the southern end of Offa’s Dyke.',NULL,NULL,'attested-standing','low','wal-eh-offas-dyke',1,'national/lines.json','$[34]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('line:england-wales/wats-dyke:existed','line','england-wales/wats-dyke','Wat’s Dyke','england-wales','existed',820,NULL,'dyke: Wat’s Dyke','A bank with a ditch on its west side, running about 60 km from Basingwerk on the Dee estuary south past Wrexham and Oswestry to the river Morda at Maesbury, a few kilometres east of Offa’s Dyke.',NULL,NULL,'attested-standing','low','wal-coflein-wats-dyke,wal-oda-dating',2,'national/lines.json','$[35]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('line:england-wales/wansdyke-east:existed','line','england-wales/wansdyke-east','East Wansdyke','england-wales','existed',500,NULL,'dyke: East Wansdyke','A massive bank and north-facing ditch running some 20 km along the crest of the Marlborough Downs from Morgan’s Hill to Savernake Forest. The name means ‘Woden’s dyke’.',NULL,NULL,'attested-standing','low',NULL,0,'national/lines.json','$[36]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('line:england-wales/wansdyke-west:existed','line','england-wales/wansdyke-west','West Wansdyke','england-wales','existed',500,NULL,'dyke: West Wansdyke','A smaller, broken earthwork south of Bristol and Bath, from the hillfort of Maes Knoll by Stantonbury to Odd Down above Bath.',NULL,NULL,'attested-standing','low',NULL,0,'national/lines.json','$[37]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('line:england-wales/devils-dyke-cambs:existed','line','england-wales/devils-dyke-cambs','Devil’s Dyke (Cambridgeshire)','england-wales','existed',550,NULL,'dyke: Devil’s Dyke (Cambridgeshire)','A straight bank and ditch about 12 km long from the fen edge at Reach to the wooded clay at Woodditton, the largest of several dykes barring the chalk corridor of the Icknield Way.',NULL,NULL,'attested-standing','low',NULL,0,'national/lines.json','$[38]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('line:england-wales/ridgeway:existed','line','england-wales/ridgeway','The Ridgeway','england-wales','existed',-3000,NULL,'road: The Ridgeway','The chalk ridge route from the Avebury area along the Berkshire Downs to the Thames at Goring, and on along the Chiltern scarp (as the Icknield Way) to Ivinghoe Beacon, passing Barbury, Uffington and Segsbury hillforts. National Trails describe it as in use for at least 5,000 years.',NULL,NULL,'conjectural','low','wal-nationaltrail-ridgeway',1,'national/lines.json','$[39]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('line:england-wales/great-north-road:existed','line','england-wales/great-north-road','Great North Road (London–York–Berwick)','england-wales','existed',1200,NULL,'road: Great North Road (London–York–Berwick)','The main medieval road from London to the north, by Barnet, Hatfield, Baldock, Stamford, Grantham, Newark, Doncaster, Boroughbridge, Durham and Newcastle to Berwick, with York reached by a branch from near Wetherby or Ferrybridge. Kings and armies used it throughout the Scottish wars.',NULL,NULL,'attested-documentary','low',NULL,0,'national/lines.json','$[40]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('line:england-wales/england-wales-border:existed','line','england-wales/england-wales-border','England–Wales border','england-wales','existed',1536,NULL,'border: England–Wales border','The boundary between Wales and England as fixed by the Laws in Wales Acts of 1535-6 and 1542-3, which assigned each marcher lordship to a Welsh or an English county. It runs from the Dee estuary to the Severn, near but seldom on Offa’s Dyke.',NULL,NULL,'attested-documentary','medium','wal-legislation-laws-in-wales-1535,wal-legislation-laws-in-wales-1542,wal-ons-counties',3,'national/lines.json','$[41]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/silures:existed','polity','england-wales/silures','Silures','england-wales','existed',-100,410,'people: Silures','The people of south-east Wales, who fought Rome from about AD 48 until their conquest in the mid 70s. Under Roman rule they formed a self-governing community with its centre at Venta Silurum (Caerwent), which lasted to the end of the Roman period. The name is first recorded by Roman writers in the 1st and 2nd centuries AD (Tacitus, Ptolemy); projecting the people back before the conquest is conjecture, and their territory had no known boundary.',NULL,NULL,'attested-documentary','medium','wal-cadw-caerwent,wal-pleiades-venta-silurum',2,'national/polities-wales.json','$[0]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/demetae:existed','polity','england-wales/demetae','Demetae','england-wales','existed',-100,410,'people: Demetae','The people of south-west Wales, whose Roman-period centre was Moridunum (Carmarthen). Their name survived in the early medieval kingdom of Dyfed. The name is first recorded by Roman writers in the 1st and 2nd centuries AD (Tacitus, Ptolemy); projecting the people back before the conquest is conjecture, and their territory had no known boundary.',NULL,NULL,'attested-documentary','medium','wal-pleiades-moridunum',1,'national/polities-wales.json','$[1]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/ordovices:existed','polity','england-wales/ordovices','Ordovices','england-wales','existed',-100,200,'people: Ordovices','The people of central and north-west Wales. Agricola crushed their rising in AD 77 and founded Segontium afterwards. No Roman-period town or self-governing community is known for them. The name is first recorded by Roman writers in the 1st and 2nd centuries AD (Tacitus, Ptolemy); projecting the people back before the conquest is conjecture, and their territory had no known boundary. The end date is a placeholder: nothing is heard of them after Ptolemy (about AD 150).',NULL,NULL,'attested-documentary','medium','wal-cadw-segontium',1,'national/polities-wales.json','$[2]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/deceangli:existed','polity','england-wales/deceangli','Deceangli','england-wales','existed',-100,200,'people: Deceangli','The people of north-east Wales, attacked by the Roman governor Ostorius Scapula about AD 48. A lead pig from Flintshire dated AD 74 is stamped with their name (RIB 2404.32), whose commentary takes these pigs to establish the form Deceangli. The name is otherwise first recorded by Roman writers (Tacitus, Ptolemy); projecting the people back before the conquest is conjecture, and their territory had no known boundary. The end date is a placeholder.',NULL,NULL,'attested-documentary','low','wal-rib-2404-32',1,'national/polities-wales.json','$[3]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/gwynedd:existed','polity','england-wales/gwynedd','Gwynedd','england-wales','existed',450,1283,'kingdom: Gwynedd','The kingdom of north-west Wales, with courts at Deganwy and Aberffraw. It became the strongest Welsh power under Rhodri Mawr (844-878), Gruffudd ap Cynan (died 1137), Owain Gwynedd and the two Llywelyns, and ended with Edward I’s conquest in 1282-3. The polygon is indicative for about 1200-1240 under Llywelyn ap Iorwerth: Gwynedd above and below the Conwy with Anglesey, Llŷn, Meirionnydd and Penllyn. The eastern part (the Perfeddwlad, between Conwy and Dee) changed hands repeatedly. The start date is conventional; the dynasty’s origin legend (Cunedda) is not history.',NULL,NULL,'attested-documentary','medium','wal-coflein-deganwy,wal-dwb-gruffudd-ap-cynan,wal-dwb-llywelyn-ap-iorwerth,wal-dwb-llywelyn-ap-gruffydd',4,'national/polities-wales.json','$[4]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/powys:existed','polity','england-wales/powys','Powys','england-wales','existed',500,1160,'kingdom: Powys','The kingdom of the central borderland. Its early extent reached further east, into what became Shropshire, before Mercian expansion and the building of Offa’s Dyke. Rhodri Mawr took it over in 855 according to the Dictionary of Welsh Biography; the ODNB says only that he may have controlled it from 855 or later. It was divided for good after the death of Madog ap Maredudd in 1160. The polygon is indicative for about 1100-1160; it is not a surveyed boundary. The start date is conventional.',NULL,NULL,'attested-documentary','medium','wal-dwb-rhodri-mawr,wal-cadw-valle-crucis,wal-odnb-rhodri-mawr',3,'national/polities-wales.json','$[5]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/powys-fadog:existed','polity','england-wales/powys-fadog','Powys Fadog','england-wales','existed',1160,1283,'principality: Powys Fadog','Northern Powys after the division of 1160, ruled from Castell Dinas Brân in the later 13th century; its princes founded Valle Crucis in 1201. It was broken up into marcher lordships (Bromfield and Yale, Chirk) after 1282-3. Only the Valle Crucis foundation is from a fetched source; the rest is general knowledge.',NULL,NULL,'attested-documentary','medium','wal-cadw-valle-crucis',1,'national/polities-wales.json','$[6]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/powys-wenwynwyn:existed','polity','england-wales/powys-wenwynwyn','Powys Wenwynwyn','england-wales','existed',1160,1283,'principality: Powys Wenwynwyn','Southern Powys after the division of 1160, centred on Welshpool. Its ruler Gruffudd ap Gwenwynwyn submitted to Llywelyn ap Gruffudd in 1263, defected in 1274 and fought for Edward I; his heirs kept it as the marcher lordship of Powis.',NULL,NULL,'attested-documentary','medium','wal-dwb-llywelyn-ap-gruffydd',1,'national/polities-wales.json','$[7]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/dyfed:existed','polity','england-wales/dyfed','Dyfed','england-wales','existed',450,920,'kingdom: Dyfed','The kingdom of south-west Wales, heir to the Roman-period Demetae, with a dynasty of partly Irish origin. Hywel Dda acquired it by marriage and joined it to Seisyllwg about 920 to form Deheubarth. The polygon is indicative for about 800. The start date is conventional.',NULL,NULL,'attested-documentary','medium','wal-dwb-hywel-dda',1,'national/polities-wales.json','$[8]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/ceredigion:existed','polity','england-wales/ceredigion','Ceredigion','england-wales','existed',500,730,'kingdom: Ceredigion','A small kingdom on Cardigan Bay between the Dyfi and the Teifi, by tradition founded by Ceredig. About 730 its king Seisyll is said to have annexed Ystrad Tywi, creating the larger kingdom later called Seisyllwg. The polygon follows the later county and is indicative. Dates are traditional. No source was fetched for this entry; it rests on general knowledge of the standard literature.',NULL,NULL,'attested-documentary','low',NULL,0,'national/polities-wales.json','$[9]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/seisyllwg:existed','polity','england-wales/seisyllwg','Seisyllwg','england-wales','existed',730,920,'kingdom: Seisyllwg','Ceredigion together with Ystrad Tywi (the Tywi valley). On the death of its king Gwgon in 872 it came under Rhodri Mawr; his grandson Hywel Dda joined it to Dyfed about 920 to form Deheubarth. The name ‘Seisyllwg’ appears only in later texts and some historians doubt it was used at the time; the start date is traditional.',NULL,NULL,'attested-documentary','low','wal-dwb-rhodri-mawr,wal-dwb-hywel-dda',2,'national/polities-wales.json','$[10]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/deheubarth:existed','polity','england-wales/deheubarth','Deheubarth','england-wales','existed',920,1283,'kingdom: Deheubarth','The kingdom of the south-west, formed about 920 when Hywel Dda united Dyfed and Seisyllwg. The Normans overran most of it after 1093; Rhys ap Gruffudd (the Lord Rhys) rebuilt it between 1155 and his death in 1197, after which it split among his descendants, who lost their last lands in 1277-87. The polygon is indicative for the Lord Rhys’s rule about 1170-1197: Ceredigion, Ystrad Tywi and parts of Dyfed, excluding the Norman lordships of Pembroke and Gower.',NULL,NULL,'attested-documentary','medium','wal-dwb-hywel-dda,wal-dwb-rhys-ap-gruffydd,wal-coflein-dinefwr',3,'national/polities-wales.json','$[11]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/glywysing:existed','polity','england-wales/glywysing','Glywysing (later Morgannwg)','england-wales','existed',500,1091,'kingdom: Glywysing (later Morgannwg)','The kingdom between the Tawe and the Usk. In the 10th century, united with Gwent under Morgan Hen (died 974), it came to be called Morgannwg, the origin of ‘Glamorgan’. The Norman Robert fitz Hamon conquered the lowlands about 1091-3. The polygon is indicative for about 950 and excludes Gwent. The start date is conventional. No source was fetched for this entry; it rests on general knowledge of the standard literature.',NULL,NULL,'attested-documentary','low',NULL,0,'national/polities-wales.json','$[12]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/gwent:existed','polity','england-wales/gwent','Gwent','england-wales','existed',450,1070,'kingdom: Gwent','The kingdom between the Usk and the Wye, named after Venta Silurum (Caerwent). It was at times joined with Glywysing. William fitz Osbern began its conquest from Chepstow after 1067. The polygon is indicative for about 1000. The start and end dates are approximate.',NULL,NULL,'attested-documentary','low','wal-cadw-chepstow,wal-cadw-caerwent',2,'national/polities-wales.json','$[13]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/brycheiniog:existed','polity','england-wales/brycheiniog','Brycheiniog','england-wales','existed',500,1093,'kingdom: Brycheiniog','A small kingdom in the upper Usk valley with a dynasty claiming Irish descent. Its king built the Llangorse crannog about 890; a Mercian army destroyed it in 916. Bernard de Neufmarché conquered the kingdom in 1093 and it became the lordship of Brecon. The polygon is indicative for about 900. The start date is conventional; the conquest date is from general knowledge.',NULL,NULL,'attested-documentary','medium','wal-nmw-llangors',1,'national/polities-wales.json','$[14]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/rhodri-mawr:existed','polity','england-wales/rhodri-mawr','Lands of Rhodri Mawr','england-wales','existed',872,878,'realm: Lands of Rhodri Mawr','Rhodri became king of Gwynedd in 844, took Powys in 855 (so the Dictionary of Welsh Biography; the ODNB treats control of Powys from 855 or later only as possible) and Seisyllwg in 872, so that for a few years one king ruled most of Wales outside the south-east and Dyfed. He was killed fighting the English; the Dictionary of Welsh Biography gives 877, other reckonings 878. His sons divided the lands. No boundary is drawn because none is known.',NULL,NULL,'attested-documentary','medium','wal-dwb-rhodri-mawr,wal-odnb-rhodri-mawr',2,'national/polities-wales.json','$[15]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/hywel-dda:existed','polity','england-wales/hywel-dda','Lands of Hywel Dda','england-wales','existed',942,950,'realm: Lands of Hywel Dda','Hywel held Seisyllwg from 920 and Dyfed by marriage, and on the death of Idwal Foel in 942 took Gwynedd (and with it Powys), ruling all Wales except Morgannwg and Gwent until his death in 950. The Welsh law-books are attributed to him, though the earliest surviving manuscript dates from the last quarter of the 12th century and the attribution is not contemporary. His kingdom broke up at his death.',NULL,NULL,'attested-documentary','medium','wal-dwb-hywel-dda,wal-bodleian-welsh-law',2,'national/polities-wales.json','$[16]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/gruffudd-ap-llywelyn:existed','polity','england-wales/gruffudd-ap-llywelyn','Kingdom of Gruffudd ap Llywelyn','england-wales','existed',1055,1063,'realm: Kingdom of Gruffudd ap Llywelyn','King of Gwynedd and Powys from 1039, Gruffudd took Deheubarth in 1055 and Morgannwg soon after: the only king ever to rule the whole of Wales, with land east of Offa’s Dyke as well. Harold Godwinson’s campaign of 1063 broke his power and he was killed by his own men (5 August 1063 in the usual reckoning; the Dictionary of Welsh Biography’s revised article argues for 1064). The polygon is modern Wales, used as an indication; his holdings beyond the dyke are not drawn.',NULL,NULL,'attested-documentary','medium','wal-dwb-gruffudd-ap-llywelyn',1,'national/polities-wales.json','$[17]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/principality-llywelyn:existed','polity','england-wales/principality-llywelyn','Principality of Wales (Llywelyn ap Gruffudd)','england-wales','existed',1267,1283,'principality: Principality of Wales (Llywelyn ap Gruffudd)','Llywelyn ap Gruffudd took the homage of the other Welsh lords in 1258 and styled himself Prince of Wales; Henry III recognised the title and the principality in the Treaty of Montgomery (1267). Edward I’s war of 1276-7 cut it back to Gwynedd west of the Conwy; Llywelyn was killed in December 1282 and his brother Dafydd captured in 1283. The polygon is a rough indication of the lands under Llywelyn’s lordship at the treaty in 1267: Gwynedd, both parts of Powys, Builth, Brecon, Gwerthrynion and the Welsh lords of Deheubarth. Its southern and eastern edges were contested and are not well defined.',NULL,NULL,'attested-documentary','low','wal-dwb-llywelyn-ap-gruffydd,wal-cadw-montgomery,wal-cadw-dolforwyn',3,'national/polities-wales.json','$[18]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/principality-north:existed','polity','england-wales/principality-north','Principality of Wales (royal counties of Anglesey, Caernarfon and Merioneth)','england-wales','existed',1284,1536,'principality: Principality of Wales (royal counties of Anglesey, Caernarfon and Merioneth)','After the conquest the Statute of Rhuddlan (1284) annexed Llywelyn’s principality to the English crown and set up counties on the English model, governed from Caernarfon. From 1301 the principality was usually granted to the king’s eldest son. Flintshire, also created in 1284, was attached to Chester and is not drawn. The polygon is indicative: the three north-western shires as they stood from 1284. The Laws in Wales Act of 1535-6 ended the legal distinction between Principality and March.',NULL,NULL,'attested-documentary','medium','wal-bodleian-welsh-law,wal-coflein-caernarfon,wal-legislation-laws-in-wales-1535',3,'national/polities-wales.json','$[19]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/principality-south:existed','polity','england-wales/principality-south','Principality of Wales (royal counties of Cardigan and Carmarthen)','england-wales','existed',1284,1536,'principality: Principality of Wales (royal counties of Cardigan and Carmarthen)','The southern part of the crown’s principality: the counties of Cardigan and Carmarthen, governed from Carmarthen and built up from royal lands held since the 1240s and the forfeited lands of the princes of Deheubarth (1277-87). The polygon is indicative for about 1300; medieval Carmarthenshire was smaller than the later county and its edges against the marcher lordships of Kidwelly, Llandovery and Emlyn are approximate. The make-up of these counties is from general knowledge.',NULL,NULL,'attested-documentary','low','wal-bodleian-welsh-law,wal-coflein-carmarthen-castle',2,'national/polities-wales.json','$[20]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/march-of-wales:existed','polity','england-wales/march-of-wales','March of Wales (marcher lordships)','england-wales','existed',1067,1536,'march: March of Wales (marcher lordships)','The belt of some forty or more lordships along the border and across south Wales, conquered piecemeal by Norman lords from 1067 (Chepstow, Montgomery, Brecon, Glamorgan, Pembroke) and enlarged after 1282 with new lordships in the north-east (Denbigh, Ruthin, Bromfield and Yale, Chirk). Each lord held royal powers in his lordship and the king’s writ did not run there. The Laws in Wales Act of 1535-6 abolished these powers and divided the lordships among new and existing shires. No polygon is drawn: the March was not one territory, and its extent changed with every war.',NULL,NULL,'attested-documentary','medium','wal-cadw-chepstow,wal-coflein-pembroke,wal-legislation-laws-in-wales-1535',3,'national/polities-wales.json','$[21]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/glyndwr:existed','polity','england-wales/glyndwr','Wales under Owain Glyndŵr','england-wales','existed',1400,1415,'principality: Wales under Owain Glyndŵr','Owain Glyndŵr attacked Ruthin on 16 September 1400 and took the title Prince of Wales. After Bryn Glas (1402) and the capture of Aberystwyth and Harlech (1404) he controlled most of Wales, made a treaty with France and planned a parliament and an independent Welsh church. Defeats from 1405 and the loss of Aberystwyth and Harlech (1408-9) ended his rule; he still raided in 1410 and is not heard of after 1412. The end date is nominal: he never surrendered and probably died about 1415-16. No polygon is drawn because control shifted from year to year.',NULL,NULL,'attested-documentary','medium','wal-dwb-owain-glyndwr,wal-coflein-harlech',2,'national/polities-wales.json','$[22]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/wales-shired:existed','polity','england-wales/wales-shired','Wales (shired and united with England)','england-wales','existed',1536,NULL,'principality: Wales (shired and united with England)','The Laws in Wales Acts of 1535-6 and 1542-3 united Wales with England, abolished the powers of the marcher lords, created the counties of Monmouth, Brecknock, Radnor, Montgomery and Denbigh beside the older ones, gave Wales members of Parliament and made English the language of the courts. The acts also fixed the boundary with England. The polygon is the modern outline of Wales, generalised; it includes Monmouthshire, which the 1542-3 act placed under the Westminster courts and whose status was long ambiguous. The fetched legislation.gov.uk pages confirm the two acts and their dates; the summary of their provisions is from general knowledge.',NULL,NULL,'attested-documentary','high','wal-legislation-laws-in-wales-1535,wal-legislation-laws-in-wales-1542',2,'national/polities-wales.json','$[23]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/cantiaci:existed','polity','england-wales/cantiaci','Cantiaci','england-wales','existed',-50,410,'people: Cantiaci','People of Kent, with a centre at Canterbury. Ptolemy (about 150 CE) still names them, with Durovernum (Canterbury); their Roman-period capital was Durovernum Cantiacorum. Shown to the end of Roman rule (410), as for the Silures and Demetae: AD 43 did not end the people. The label marks the heartland only; no boundary is known.',NULL,NULL,'attested-documentary','medium','nat-ptolemy-geography-2-2',1,'national/polities.json','$[0]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/trinovantes:existed','polity','england-wales/trinovantes','Trinovantes','england-wales','existed',-50,410,'people: Trinovantes','People of Essex and south Suffolk; Caesar restored their king Mandubracius in 54 BCE. Ptolemy (about 150 CE) still names them, with Camulodunum (Colchester). Shown to the end of Roman rule (410), as for the Silures and Demetae: AD 43 did not end the people. The label marks the heartland only; no boundary is known.',NULL,NULL,'attested-documentary','medium','nat-ptolemy-geography-2-2',1,'national/polities.json','$[1]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/catuvellauni:existed','polity','england-wales/catuvellauni','Catuvellauni','england-wales','existed',-50,410,'people: Catuvellauni','The dominant power north of the Thames under Tasciovanus and Cunobelin, with centres at Verlamion and, by conquest, Camulodunon. Ptolemy (about 150 CE) still names them, with Verulamium; a building stone of the civitas Catuvellaunorum on Hadrian''s Wall (RIB 1962) shows the civitas still existed in the late Roman period. Shown to the end of Roman rule (410), as for the Silures and Demetae: AD 43 did not end the people. The label marks the heartland only; no boundary is known.',NULL,NULL,'attested-documentary','medium','nat-ptolemy-geography-2-2,nat-rib-1962',2,'national/polities.json','$[2]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/iceni:existed','polity','england-wales/iceni','Iceni','england-wales','existed',-50,410,'people: Iceni','People of Norfolk and north Suffolk. After 43 they kept a client kingdom under Prasutagus until the revolt of Boudica in 60/61 (Tacitus, Annals XIV.29-31, dated by the consuls of 61); afterwards they formed a Roman civitas, and Ptolemy (about 150 CE) names them with Venta (Caistor St Edmund). Shown to the end of Roman rule (410), as for the Silures and Demetae: AD 43 did not end the people. The label marks the heartland only; no boundary is known.',NULL,NULL,'attested-documentary','medium','nat-tacitus-annals-14,nat-ptolemy-geography-2-2',2,'national/polities.json','$[3]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/atrebates:existed','polity','england-wales/atrebates','Atrebates','england-wales','existed',-50,410,'people: Atrebates','A kingdom ruled by the heirs of Commius, centred on Calleva (Silchester). Ptolemy (about 150 CE) still names them, with Calleva (Silchester). Shown to the end of Roman rule (410), as for the Silures and Demetae: AD 43 did not end the people. The label marks the heartland only; no boundary is known.',NULL,NULL,'attested-documentary','medium','nat-ptolemy-geography-2-2',1,'national/polities.json','$[4]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/regni:existed','polity','england-wales/regni','Regni','england-wales','existed',-50,410,'people: Regni','People of Sussex; the name''s form (Regni or Regini) is uncertain and it may be a Roman creation for Togidubnus''s client kingdom. Togidubnus, named as a great king in Britain on a Chichester inscription (RIB 91), held a client kingdom here after 43; Ptolemy (about 150 CE) names the Regni with Noviomagus (Chichester). Shown to the end of Roman rule (410), as for the Silures and Demetae: AD 43 did not end the people. The label marks the heartland only; no boundary is known.',NULL,NULL,'attested-documentary','low','nat-rib-91,nat-ptolemy-geography-2-2',2,'national/polities.json','$[5]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/belgae:existed','polity','england-wales/belgae','Belgae','england-wales','existed',-50,410,'people: Belgae','A civitas centred on Winchester; it may be a Roman administrative grouping rather than a pre-conquest people. Ptolemy (about 150 CE) names them with Venta (Winchester) and Aquae Calidae (Bath). Shown to the end of Roman rule (410), as for the Silures and Demetae: AD 43 did not end the people. The label marks the heartland only; no boundary is known.',NULL,NULL,'attested-documentary','low','nat-ptolemy-geography-2-2',1,'national/polities.json','$[6]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/durotriges:existed','polity','england-wales/durotriges','Durotriges','england-wales','existed',-50,410,'people: Durotriges','People of Dorset and south Somerset, the builders of the last great hillforts. Ptolemy (about 150 CE) names them with Dunium; building stones of the civitas Durotrigum Lendiniensis on Hadrian''s Wall (RIB 1672) show the civitas in the late Roman period. Shown to the end of Roman rule (410), as for the Silures and Demetae: AD 43 did not end the people. The label marks the heartland only; no boundary is known.',NULL,NULL,'attested-documentary','medium','nat-ptolemy-geography-2-2,nat-rib-1672',2,'national/polities.json','$[7]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/dumnonii:existed','polity','england-wales/dumnonii','Dumnonii','england-wales','existed',-50,410,'people: Dumnonii','People of Devon and Cornwall, later centred on Exeter. Ptolemy (about 150 CE) names them with Isca (Exeter); a building stone of the civitas Dumnoniorum on Hadrian''s Wall (RIB 1843) shows the civitas in the late Roman period. Shown to the end of Roman rule (410), as for the Silures and Demetae: AD 43 did not end the people. The label marks the heartland only; no boundary is known.',NULL,NULL,'attested-documentary','medium','nat-ptolemy-geography-2-2,nat-rib-1843',2,'national/polities.json','$[8]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/dobunni:existed','polity','england-wales/dobunni','Dobunni','england-wales','existed',-50,410,'people: Dobunni','People of the Cotswolds and lower Severn, later centred on Cirencester. Ptolemy (about 150 CE) names them with Corinium (Cirencester); a milestone of 283-4 from Kenchester (RIB 2250) probably names their respublica, though the last letter is disputed. Shown to the end of Roman rule (410), as for the Silures and Demetae: AD 43 did not end the people. The label marks the heartland only; no boundary is known.',NULL,NULL,'attested-documentary','medium','nat-ptolemy-geography-2-2,nat-rib-2250',2,'national/polities.json','$[9]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/corieltauvi:existed','polity','england-wales/corieltauvi','Corieltauvi','england-wales','existed',-50,410,'people: Corieltauvi','People of the east Midlands, later centred on Leicester; formerly read as ''Coritani''. Ptolemy (about 150 CE) names them (as Coritani) with Lindum and Ratae (Leicester). Shown to the end of Roman rule (410), as for the Silures and Demetae: AD 43 did not end the people. The label marks the heartland only; no boundary is known.',NULL,NULL,'attested-documentary','medium','nat-ptolemy-geography-2-2',1,'national/polities.json','$[10]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/cornovii:existed','polity','england-wales/cornovii','Cornovii','england-wales','existed',-50,410,'people: Cornovii','People of Shropshire and Cheshire, later centred on Wroxeter. The forum inscription of 129-130 at Wroxeter was set up by the civitas Cornoviorum (RIB 288), and Ptolemy (about 150 CE) names them with Viroconium. Shown to the end of Roman rule (410), as for the Silures and Demetae: AD 43 did not end the people. The label marks the heartland only; no boundary is known.',NULL,NULL,'attested-documentary','medium','nat-eh-wroxeter,nat-rib-288,nat-ptolemy-geography-2-2',3,'national/polities.json','$[11]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/brigantes:existed','polity','england-wales/brigantes','Brigantes','england-wales','existed',-50,410,'people: Brigantes','A large confederation across the Pennines. After 43 Cartimandua ruled them as a client of Rome; in 69 she was rescued by Roman troops and Venutius held the kingdom (Tacitus, Histories III.45) until Cerialis attacked the Brigantes (Agricola 17). They then formed a Roman civitas: Ptolemy (about 150 CE) names them with Isurium (Aldborough) and other towns, and a lost Wall stone probably names the civitas Brigantum (RIB 2022). Shown to the end of Roman rule (410), as for the Silures and Demetae: AD 43 did not end the people. The label marks the heartland only; no boundary is known.',NULL,NULL,'attested-documentary','medium','nat-tacitus-histories-3,nat-tacitus-agricola,nat-ptolemy-geography-2-2,nat-rib-2022,nat-eh-stanwick',5,'national/polities.json','$[12]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/parisi:existed','polity','england-wales/parisi','Parisi','england-wales','existed',-50,410,'people: Parisi','People of east Yorkshire, known for chariot burials. Ptolemy (about 150 CE) names them with Petuaria (Brough-on-Humber), where an inscription of about 139 names the vicus of Petuaria (RIB 707). Shown to the end of Roman rule (410), as for the Silures and Demetae: AD 43 did not end the people. The label marks the heartland only; no boundary is known.',NULL,NULL,'attested-documentary','medium','nat-ptolemy-geography-2-2,nat-rib-707',2,'national/polities.json','$[13]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/carvetii:existed','polity','england-wales/carvetii','Carvetii','england-wales','existed',222,410,'people: Carvetii','People of the Eden valley and Solway plain. They are known only as the Roman civitas Carvetiorum, first named on a milestone of 222/223 near Brougham (RIB 3526, its earliest dated evidence); before that they were probably part of the Brigantes, so no pre-Roman span is shown. The civitas may be older than its first inscription. Shown to the end of Roman rule (410). The label marks the heartland only; no boundary is known.',NULL,NULL,'attested-documentary','medium','nat-rib-3526',1,'national/polities.json','$[14]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/votadini:existed','polity','england-wales/votadini','Votadini','england-wales','existed',-50,410,'people: Votadini','People of Northumberland and Lothian, mostly beyond the northern edge of this map. Ptolemy (about 150 CE) names them (as Otadini) with Bremenium and other places, mostly beyond the province. Shown to the end of Roman rule (410), as for the Silures and Demetae: AD 43 did not end the people. The label marks the heartland only; no boundary is known.',NULL,NULL,'attested-documentary','low','nat-ptolemy-geography-2-2',1,'national/polities.json','$[15]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/britannia:existed','polity','england-wales/britannia','Britannia','england-wales','existed',43,196,'province: Britannia','The single Roman province, governed by a consular legate. Its limit moved north by stages to Hadrian''s Wall (from 122). No polygon: the area held changed decade by decade in the 1st century. Dates are supported here only by Wikipedia, which is a lead rather than verification.',NULL,NULL,'attested-documentary','medium','nat-wp-roman-britain',1,'national/polities.json','$[16]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/britannia-superior:existed','polity','england-wales/britannia-superior','Britannia Superior','england-wales','existed',197,295,'province: Britannia Superior','The southern province after Severus split Britain; governed from London. The division is placed about 197 by one ancient account and as late as 213 by modern scholars. The line between the two provinces is not recorded. Dates are supported here only by Wikipedia, which is a lead rather than verification.',NULL,NULL,'attested-documentary','medium','nat-wp-roman-britain',1,'national/polities.json','$[17]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/britannia-inferior:existed','polity','england-wales/britannia-inferior','Britannia Inferior','england-wales','existed',197,295,'province: Britannia Inferior','The northern province, governed from York, which was a colonia by 237. Same dating caveat as Britannia Superior. Dates are supported here only by Wikipedia, which is a lead rather than verification.',NULL,NULL,'attested-documentary','medium','nat-wp-roman-britain,nat-wp-eboracum',2,'national/polities.json','$[18]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/maxima-caesariensis:existed','polity','england-wales/maxima-caesariensis','Maxima Caesariensis','england-wales','existed',296,410,'province: Maxima Caesariensis','Usually placed in the south-east with London as capital. One of the four provinces of the Diocese of the Britains, created between 296 and about 312. Their names are certain; their boundaries and, for most, their capitals are not, and the label position is the common modern reconstruction only. Dates are supported here only by Wikipedia, which is a lead rather than verification.',NULL,NULL,'conjectural','low','nat-wp-roman-britain',1,'national/polities.json','$[19]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/britannia-prima:existed','polity','england-wales/britannia-prima','Britannia Prima','england-wales','existed',296,410,'province: Britannia Prima','Usually placed in the west, with Cirencester as capital on the evidence of one inscription. One of the four provinces of the Diocese of the Britains, created between 296 and about 312. Their names are certain; their boundaries and, for most, their capitals are not, and the label position is the common modern reconstruction only. Dates are supported here only by Wikipedia, which is a lead rather than verification.',NULL,NULL,'conjectural','low','nat-wp-roman-britain',1,'national/polities.json','$[20]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/flavia-caesariensis:existed','polity','england-wales/flavia-caesariensis','Flavia Caesariensis','england-wales','existed',296,410,'province: Flavia Caesariensis','Usually placed in the east Midlands around Lincoln, though some would exchange it with Britannia Secunda. One of the four provinces of the Diocese of the Britains, created between 296 and about 312. Their names are certain; their boundaries and, for most, their capitals are not, and the label position is the common modern reconstruction only. Dates are supported here only by Wikipedia, which is a lead rather than verification.',NULL,NULL,'conjectural','low','nat-wp-roman-britain,nat-wp-lindum',2,'national/polities.json','$[21]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/britannia-secunda:existed','polity','england-wales/britannia-secunda','Britannia Secunda','england-wales','existed',296,410,'province: Britannia Secunda','Usually placed in the north around York, though some would exchange it with Flavia Caesariensis. One of the four provinces of the Diocese of the Britains, created between 296 and about 312. Their names are certain; their boundaries and, for most, their capitals are not, and the label position is the common modern reconstruction only. Dates are supported here only by Wikipedia, which is a lead rather than verification.',NULL,NULL,'conjectural','low','nat-wp-roman-britain,nat-wp-eboracum',2,'national/polities.json','$[22]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/valentia:existed','polity','england-wales/valentia','Valentia','england-wales','existed',369,410,'province: Valentia','A fifth province named by Ammianus as restored by Count Theodosius in 369. Its location is unknown: around Carlisle (shown), around Chester, or between the Walls have all been argued. Dates are supported here only by Wikipedia, which is a lead rather than verification.',NULL,NULL,'conjectural','low','nat-wp-roman-britain',1,'national/polities.json','$[23]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/kent:existed','polity','england-wales/kent','Kingdom of Kent','england-wales','existed',455,825,'kingdom: Kingdom of Kent','Traditionally founded about 455; its first securely attested king, Aethelberht, received Augustine in 597. Under Mercian control 764-825, then absorbed by Wessex. The polygon is the kingdom of about 600, roughly the later county. Frontiers were zones of shifting lordship, not lines. Dates are supported here only by Wikipedia, which is a lead rather than verification.',NULL,NULL,'attested-documentary','medium','nat-wp-kent',1,'national/polities.json','$[24]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/sussex:existed','polity','england-wales/sussex','Kingdom of the South Saxons','england-wales','existed',477,860,'kingdom: Kingdom of the South Saxons','Traditional foundation by Aelle in 477; converted by Wilfrid from 681; under Mercia 771-796, subject to Wessex from about 827 and fully absorbed in 860. The polygon is the kingdom of about 700, bounded inland by the Weald forest. Frontiers were zones of shifting lordship, not lines. Dates are supported here only by Wikipedia, which is a lead rather than verification.',NULL,NULL,'attested-documentary','medium','nat-wp-sussex',1,'national/polities.json','$[25]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/essex:existed','polity','england-wales/essex','Kingdom of the East Saxons','england-wales','existed',527,825,'kingdom: Kingdom of the East Saxons','Founded in the 6th century (527 is a traditional and uncertain date). It ceded itself to Wessex in 825. The polygon is the kingdom of about 650, when it still included Middlesex, London and much of Hertfordshire; Mercia took those by the mid 8th century. Frontiers were zones of shifting lordship, not lines. Dates are supported here only by Wikipedia, which is a lead rather than verification.',NULL,NULL,'attested-documentary','medium','nat-wp-essex',1,'national/polities.json','$[26]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/east-anglia:existed','polity','england-wales/east-anglia','Kingdom of the East Angles','england-wales','existed',520,869,'kingdom: Kingdom of the East Angles','Organised in the first half of the 6th century and ruled by the Wuffingas, of whom Raedwald (died about 624) was the most powerful. King Edmund was killed by the Danes in 869. The polygon is the kingdom of about 700: Norfolk and Suffolk, with the Fens as its western march. Frontiers were zones of shifting lordship, not lines. Dates are supported here only by Wikipedia, which is a lead rather than verification.',NULL,NULL,'attested-documentary','medium','nat-wp-east-anglia',1,'national/polities.json','$[27]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/east-anglia-danish:existed','polity','england-wales/east-anglia-danish','Danish kingdom of East Anglia','england-wales','existed',870,917,'kingdom: Danish kingdom of East Anglia','East Anglia under Danish kings, including Guthrum (baptised Aethelstan) from 880; it also held Essex. Submitted to Edward the Elder in 917-918. No polygon: its western limit is not known. Dates are supported here only by Wikipedia, which is a lead rather than verification.',NULL,NULL,'attested-documentary','medium','nat-wp-east-anglia,nat-wp-essex',2,'national/polities.json','$[28]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/wessex:existed','polity','england-wales/wessex','Kingdom of the West Saxons','england-wales','existed',519,926,'kingdom: Kingdom of the West Saxons','519 is the legendary date of Cerdic; the historical kingdom grew from the Gewisse of the upper Thames in the 7th century. From 825 it also held Kent, Sussex, Surrey and Essex, and from about 886 Alfred styled himself king of the Anglo-Saxons. The polygon is the core kingdom of about 800, before those gains, with Devon included and Cornwall still British. Frontiers were zones of shifting lordship, not lines. Dates are supported here only by Wikipedia, which is a lead rather than verification.',NULL,NULL,'attested-documentary','medium','nat-wp-wessex',1,'national/polities.json','$[29]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/mercia:existed','polity','england-wales/mercia','Kingdom of the Mercians','england-wales','existed',585,918,'kingdom: Kingdom of the Mercians','Attested from the late 6th century and dominant south of the Humber under Penda (died 655), Aethelbald and Offa (757-796). The Danes took its eastern half in 877; the western half was ruled by Ealdorman Aethelred and Aethelflaed under West Saxon lordship until Edward the Elder annexed it in 918. The polygon is Mercia proper about 790 under Offa, including Lindsey, the Hwicce, Middlesex and London but not the client kingdoms of Kent, Sussex, Essex and East Anglia. Frontiers were zones of shifting lordship, not lines. Dates are supported here only by Wikipedia, which is a lead rather than verification.',NULL,NULL,'attested-documentary','medium','nat-wp-mercia',1,'national/polities.json','$[30]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/bernicia:existed','polity','england-wales/bernicia','Bernicia','england-wales','existed',547,654,'kingdom: Bernicia','The northern Anglian kingdom, centred on Bamburgh; 547 is the traditional date of Ida. It may have begun as a British kingdom. United with Deira for good by 654. Extent unknown. Dates are supported here only by Wikipedia, which is a lead rather than verification.',NULL,NULL,'attested-documentary','low','nat-wp-northumbria',1,'national/polities.json','$[31]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/deira:existed','polity','england-wales/deira','Deira','england-wales','existed',560,654,'kingdom: Deira','The southern Anglian kingdom between Humber and Tees, centred on the Yorkshire Wolds and York. Its last king was killed in 651 and it was ruled from Bernicia thereafter. The start date is nominal. Dates are supported here only by Wikipedia, which is a lead rather than verification.',NULL,NULL,'attested-documentary','low','nat-wp-northumbria',1,'national/polities.json','$[32]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/northumbria-early:existed','polity','england-wales/northumbria-early','Bernicia and Deira under one king','england-wales','existed',604,642,'kingdom: Bernicia and Deira under one king','Before the lasting union, Bernicia and Deira were ruled together by Aethelfrith (from about 604), Edwin (616-633) and Oswald (634-642); Bede says Oswald peacefully united the two provinces (III.6). The union broke at Edwin''s death and again after Oswald''s, so this span is not continuous: the kingdoms are also shown separately. Extent unknown.',NULL,NULL,'attested-documentary','medium','nat-bede-he-sellar',1,'national/polities.json','$[33]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/northumbria:existed','polity','england-wales/northumbria','Kingdom of the Northumbrians','england-wales','existed',654,867,'kingdom: Kingdom of the Northumbrians','Bernicia and Deira united for good under Oswiu in the 650s (earlier unions under Aethelfrith, Edwin and Oswald are shown as their own record). At its height it ran from the Humber and Mersey to the Firth of Forth; the polygon shows about 700 and is cut off at the northern edge of this map. York fell to the Great Army in 867. Frontiers were zones of shifting lordship, not lines. The 654 start is approximate (Bede places Oswiu''s sole rule after the deaths of Oswine and Penda).',NULL,NULL,'attested-documentary','medium','nat-wp-northumbria,nat-bede-he-sellar',2,'national/polities.json','$[34]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/lindsey:existed','polity','england-wales/lindsey','Lindsey','england-wales','existed',550,700,'kingdom: Lindsey','A small kingdom between the Humber and the Witham with its own king-list and bishop. It was fought over by Northumbria and Mercia in the 7th century and was Mercian for good by about 700. Both dates are nominal. Dates are supported here only by Wikipedia, which is a lead rather than verification.',NULL,NULL,'attested-documentary','low','nat-wp-lindsey',1,'national/polities.json','$[35]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/hwicce:existed','polity','england-wales/hwicce','Hwicce','england-wales','existed',577,780,'kingdom: Hwicce','A kingdom of the lower Severn and Cotswolds (roughly the later diocese of Worcester), a Mercian sub-kingdom from about 628; its rulers cease to be called kings about 780. The 577 start is the Anglo-Saxon Chronicle''s and doubtful. Dates are supported here only by Wikipedia, which is a lead rather than verification.',NULL,NULL,'attested-documentary','medium','nat-wp-hwicce',1,'national/polities.json','$[36]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/elmet:existed','polity','england-wales/elmet','Elmet','england-wales','existed',450,617,'kingdom: Elmet','A British kingdom around Leeds, annexed by Edwin of Northumbria about 617. Start date nominal; extent unknown. Not checked against a fetched source: dates and size come from general reference knowledge.',NULL,NULL,'attested-documentary','low',NULL,0,'national/polities.json','$[37]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/dumnonia:existed','polity','england-wales/dumnonia','Dumnonia','england-wales','existed',410,838,'kingdom: Dumnonia','The British kingdom of the south-west. Wessex took Devon by the early 8th century; Cornwall kept kings until the 9th century and was brought under English rule between Egbert''s victory at Hingston Down (838) and Aethelstan. Label placed in Cornwall; dates nominal. Not checked against a fetched source: dates and size come from general reference knowledge.',NULL,NULL,'attested-documentary','low',NULL,0,'national/polities.json','$[38]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/jorvik:existed','polity','england-wales/jorvik','Kingdom of York','england-wales','existed',867,954,'kingdom: Kingdom of York','Scandinavian kingdom between Humber and Tees after the Great Army took York in 866/7. Taken by Aethelstan in 927, lost again, and ended when Eric Bloodaxe was driven out and killed in 954. Dates are supported here only by Wikipedia, which is a lead rather than verification.',NULL,NULL,'attested-documentary','medium','nat-wp-scandinavian-york,nat-wp-northumbria',2,'national/polities.json','$[39]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/danelaw:existed','polity','england-wales/danelaw','Danelaw','england-wales','existed',886,954,'realm: Danelaw','Not a state but the part of England under Danish armies and law: East Anglia, the Five Boroughs (Lincoln, Stamford, Leicester, Nottingham, Derby) and York. The polygon shows about 890, with the Alfred-Guthrum treaty boundary (886-890) on the south-west running up the Lea to Bedford and then along Watling Street. Edward the Elder and Aethelflaed retook everything south of the Humber in the 910s; the term itself is first used in the 11th century. Frontiers were zones of shifting lordship, not lines. Dates are supported here only by Wikipedia, which is a lead rather than verification.',NULL,NULL,'reconstructed','medium','nat-wp-danelaw',1,'national/polities.json','$[40]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/england:existed','polity','england-wales/england','Kingdom of the English (England)','england-wales','existed',927,NULL,'realm: Kingdom of the English (England)','Aethelstan took York in 927 and was the first king to rule all the English. The polygon is the kingdom of about 1000: Cumbria was under Strathclyde until William II took Carlisle in 1092, Lothian had passed to the Scots, the Tweed border was fixed in practice only in the 12th-13th centuries (Berwick 1482), and Wales was annexed in law in 1536-42. Frontiers were zones of shifting lordship, not lines. Dates are supported here only by Wikipedia, which is a lead rather than verification.',NULL,NULL,'attested-documentary','medium','nat-wp-aethelstan,nat-wp-wessex',2,'national/polities.json','$[41]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/earldom-wessex:existed','polity','england-wales/earldom-wessex','Earldom of Wessex','england-wales','existed',1020,1066,'earldom: Earldom of Wessex','Held by Godwin from about 1020 and by his son Harold from 1053 until he became king. One of the great earldoms through which Cnut and Edward the Confessor governed. Label only: earldoms were bundles of shires that were regrouped whenever an earl died or fell. Dates are supported here only by Wikipedia, which is a lead rather than verification.',NULL,NULL,'attested-documentary','medium','nat-wp-wessex',1,'national/polities.json','$[42]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/earldom-mercia:existed','polity','england-wales/earldom-mercia','Earldom of Mercia','england-wales','existed',1017,1070,'earldom: Earldom of Mercia','Held by Eadric Streona, then by Leofric, Aelfgar and Edwin. End date approximate. One of the great earldoms through which Cnut and Edward the Confessor governed. Label only: earldoms were bundles of shires that were regrouped whenever an earl died or fell. Not checked against a fetched source: dates and size come from general reference knowledge.',NULL,NULL,'attested-documentary','medium',NULL,0,'national/polities.json','$[43]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/earldom-east-anglia:existed','polity','england-wales/earldom-east-anglia','Earldom of East Anglia','england-wales','existed',1017,1075,'earldom: Earldom of East Anglia','Held by Thorkell the Tall and later by Harold and Gyrth Godwinson; suppressed after the revolt of 1075. One of the great earldoms through which Cnut and Edward the Confessor governed. Label only: earldoms were bundles of shires that were regrouped whenever an earl died or fell. Not checked against a fetched source: dates and size come from general reference knowledge.',NULL,NULL,'attested-documentary','medium',NULL,0,'national/polities.json','$[44]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/earldom-northumbria:existed','polity','england-wales/earldom-northumbria','Earldom of Northumbria','england-wales','existed',954,1075,'earldom: Earldom of Northumbria','After 954 the north was governed by earls appointed by the English kings, among them Siward and Tostig; the house of Bamburgh kept the land beyond the Tees for much of the time. Label only. The last English earl, Waltheof, fell in 1075-6 (from memory). Dates are supported here only by Wikipedia, which is a lead rather than verification.',NULL,NULL,'attested-documentary','medium','nat-wp-northumbria,nat-wp-scandinavian-york',2,'national/polities.json','$[45]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/earldom-chester:existed','polity','england-wales/earldom-chester','Earldom of Chester','england-wales','existed',1071,1237,'earldom: Earldom of Chester','Marcher earldom created by William I to contain north Wales; a palatinate, annexed to the Crown in 1237 (date from memory). Dates are supported here only by Wikipedia, which is a lead rather than verification.',NULL,NULL,'attested-documentary','medium','nat-wp-welsh-marches',1,'national/polities.json','$[46]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/earldom-shrewsbury:existed','polity','england-wales/earldom-shrewsbury','Earldom of Shrewsbury','england-wales','existed',1071,1102,'earldom: Earldom of Shrewsbury','Marcher earldom of Roger of Montgomery; forfeited by Robert of Belleme in 1102 (dates from memory). Dates are supported here only by Wikipedia, which is a lead rather than verification.',NULL,NULL,'attested-documentary','medium','nat-wp-welsh-marches',1,'national/polities.json','$[47]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('polity:england-wales/earldom-hereford:existed','polity','england-wales/earldom-hereford','Earldom of Hereford','england-wales','existed',1067,1075,'earldom: Earldom of Hereford','Marcher earldom of William fitz Osbern; forfeited by his son after the revolt of 1075 (dates from memory). Dates are supported here only by Wikipedia, which is a lead rather than verification.',NULL,NULL,'attested-documentary','medium','nat-wp-welsh-marches',1,'national/polities.json','$[48]');
