INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('event:barnet/1453#0:event','event','barnet/1453#0','Barnet chapel rebuilt','barnet','event',1453,1453,'Barnet chapel rebuilt','John Beauchamp, who died in 1453, rebuilt the nave arcades and clerestory of the chapel of St John the Baptist; the tower is early 15th century and the chancel about 1450. The dates are architectural estimates apart from Beauchamp''s death.',NULL,NULL,NULL,NULL,'bar-vch-herts-barnet',1,'locations/barnet/events.json','$[0]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('event:barnet/1455#0:event','event','barnet/1455#0','First Battle of St Albans','barnet','event',1455,1455,'First Battle of St Albans','22 May 1455, about 15 km to the north-west along the same road: the opening battle of the Wars of the Roses. Off this map.',NULL,NULL,NULL,NULL,NULL,0,'locations/barnet/events.json','$[1]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('event:barnet/1461#0:event','event','barnet/1461#0','Towton; Edward IV becomes king','barnet','event',1461,1461,'Towton; Edward IV becomes king','After the second battle of St Albans (17 February) Edward of York was proclaimed king in London in March and won at Towton in Yorkshire on 29 March 1461. Off this map.',NULL,NULL,NULL,NULL,NULL,0,'locations/barnet/events.json','$[2]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('event:barnet/1470#0:event','event','barnet/1470#0','Henry VI restored by Warwick','barnet','event',1470,1470,'Henry VI restored by Warwick','The ''readeption'': Warwick, now allied with the Lancastrians, restored Henry VI in October 1470 and Edward IV fled abroad. He landed in Yorkshire in March 1471 and entered London on 11 April.',NULL,NULL,NULL,NULL,NULL,0,'locations/barnet/events.json','$[3]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('event:barnet/1471#0:event','event','barnet/1471#0','Battle of Barnet, 14 April','barnet','event',1471,1471,'Battle of Barnet, 14 April','Easter Sunday. Edward IV defeated the Earl of Warwick somewhere between half a mile and a mile north of the town, at dawn in thick mist; Warwick and his brother Montagu were killed. The exact ground has not been found.',NULL,NULL,NULL,NULL,'bar-barnet-battlefield-project-2015-2018,bar-arrivall-part-3,bar-warkworth-barnet,bar-battlefields-trust-barnet',4,'locations/barnet/events.json','$[4]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('event:barnet/1471#1:event','event','barnet/1471#1','Battle of Tewkesbury, 4 May','barnet','event',1471,1471,'Battle of Tewkesbury, 4 May','Three weeks later Edward defeated Margaret of Anjou''s army in Gloucestershire, ending the Lancastrian challenge. Off this map.',NULL,NULL,NULL,NULL,NULL,0,'locations/barnet/events.json','$[5]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('event:barnet/1479#0:event','event','barnet/1479#0','Kitts End heath first named','barnet','event',1479,1479,'Kitts End heath first named','A close roll entry of 1479 names Kitts (Kicks) End heath, Bentley heath and many hedged closes north of the common: the earliest detailed record of the landscape north of Hadley, eight years after the battle.',NULL,NULL,NULL,NULL,'bar-barnet-battlefield-project-2015-2018,bar-vch-middx-south-mimms-intro',2,'locations/barnet/events.json','$[6]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('event:barnet/1485#0:event','event','barnet/1485#0','Bosworth; Henry VII becomes king','barnet','event',1485,1485,'Bosworth; Henry VII becomes king','22 August 1485, in Leicestershire. Off this map.',NULL,NULL,NULL,NULL,NULL,0,'locations/barnet/events.json','$[7]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('event:barnet/1494#0:event','event','barnet/1494#0','Hadley church rebuilt','barnet','event',1494,1494,'Hadley church rebuilt','The church of St Mary at Monken Hadley was rebuilt about 1494, the date carved on its west tower, presumably on the site of an older church.',NULL,NULL,NULL,NULL,'bar-vch-middx-monken-hadley-church,bar-listing-st-mary-monken-hadley',2,'locations/barnet/events.json','$[8]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('event:brentford/996#0:event','event','brentford/996#0','Half a Thames fishery at Brentford granted to Winchester','brentford','event',996,996,'Half a Thames fishery at Brentford granted to Winchester','King Æthelred granted half of a Thames fishery at Brentford to the church of St Peter and St Paul, Winchester. It is the only record of activity at Brentford found for the half-century before the battle.',NULL,NULL,NULL,NULL,'bre-vch-mdx7-econ,bre-vch-mdx7-growth',2,'locations/brentford/events.json','$[0]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('event:brentford/1013#0:event','event','brentford/1013#0','Swein''s army loses men crossing the Thames','brentford','event',1013,1013,'Swein''s army loses men crossing the Thames','On its way towards London, the Chronicle says, many of Swein Forkbeard''s army drowned in the Thames ''because they kept not to any bridge''. The place is not given and need not be Brentford; it shows what a crossing of the river could cost.',NULL,NULL,NULL,NULL,'bre-asc-avalon',1,'locations/brentford/events.json','$[1]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('event:brentford/1016#0:event','event','brentford/1016#0','Cnut besieges London','brentford','event',1016,1016,'Cnut besieges London','The Danish ships came to London, dug a ditch on the south side and dragged their ships to the west of the bridge, then shut the city in. Edmund gathered an army, came to London north of the Thames and drove the besiegers to their ships.',NULL,NULL,NULL,NULL,'bre-asc-avalon,bre-clerk-siege-london',2,'locations/brentford/events.json','$[2]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('event:brentford/1016#1:event','event','brentford/1016#1','Battle of Brentford','brentford','event',1016,1016,'Battle of Brentford','Within two nights of relieving London, Edmund ''went over at Brentford'', fought the Danish army and put it to flight. Many of the English drowned ''from their own carelessness'', having gone ahead of the army to plunder. Site, numbers and course are unknown; the figures shown are stand-ins.',NULL,NULL,NULL,NULL,'bre-asc-avalon,bre-vch-mdx7-growth',2,'locations/brentford/events.json','$[3]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('event:brentford/1016#2:event','event','brentford/1016#2','Edmund fords the Thames at Brentford again','brentford','event',1016,1016,'Edmund fords the Thames at Brentford again','Later in the year Edmund gathered the English a fourth time, ''forded over the Thames at Brentford'' and went into Kent, driving the Danes to Sheppey. He was beaten at Assandun and died on St Andrew''s day (30 November); Cnut took the whole kingdom.',NULL,NULL,NULL,NULL,'bre-asc-avalon',1,'locations/brentford/events.json','$[4]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('event:brentford/1066#0:event','event','brentford/1066#0','Norman Conquest','brentford','event',1066,1066,'Norman Conquest','Nothing is recorded at Brentford in the sources read. Isleworth, held by Earl Ælfgar in 1066, had passed to Walter of St Valery by 1086.',NULL,NULL,NULL,NULL,'bre-opendomesday-isleworth',1,'locations/brentford/events.json','$[5]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('event:brentford/1086#0:event','event','brentford/1086#0','Domesday Book: Brentford is not named','brentford','event',1086,1086,'Domesday Book: Brentford is not named','The ground lay in three manors. Isleworth had 118 households, land for 55 ploughs, two mills and woodland for 500 pigs, and was worth £72 (£80 in 1066). Hanwell, held by Westminster Abbey and assessed at 8 hides, had about 17 households and a mill (figures from a secondary summary). The county history thinks Old Brentford was probably counted within the bishop of London''s manor of Fulham.',NULL,NULL,NULL,NULL,'bre-opendomesday-isleworth,bre-aubrey-domesday-hanwell,bre-vch-mdx7-growth',3,'locations/brentford/events.json','$[6]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('event:london/-1500#0:event','event','london/-1500#0','Bronze Age farming on the Southwark eyots','london','event',-1500,-1500,'Bronze Age farming on the Southwark eyots','Plough (ard) marks and timber trackways are known from Southwark and Bermondsey; the cultivation was short-lived and was drowned as water levels rose.',NULL,NULL,NULL,NULL,'cup-bramcote-green-bermondsey-bronze,rfla-prehistory-research-framework-london,southwark-council-archaeology-southwark-prehistoric,gresham-early-river-thames-iron',4,'locations/london/events.json','$[0]');
