INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('event:england-wales/-2400#0:event','event','england-wales/-2400#0','Silbury Hill built; first metal and Beaker pottery','england-wales','event',-2400,-2400,'Silbury Hill built; first metal and Beaker pottery','The mound was raised between about 2470 and 2350 BCE. Copper, gold and Beaker burials appear in Britain at about the same time.',NULL,NULL,NULL,NULL,'nat-eh-silbury',1,'national/events.json','$[6]');
