INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:barnet/barnet-1471:attested:0','episode','barnet/barnet-1471','Battle of Barnet','barnet','episode_attested',1471,1471,'Date, commanders and outcome: Edward IV, with his brothers Gloucester and Clarence and Lord Hastings, defeated Warwick, Montagu, Oxford and Exeter. Warwick and Montagu were killed, Exeter was left for dead, Oxford escaped.',NULL,NULL,NULL,NULL,NULL,'bar-barnet-battlefield-project-2015-2018,bar-watson-2022-looking-for-the-site,bar-battlefields-trust-barnet,bar-arrivall-part-3,bar-warkworth-barnet,bar-barnet-society-2021,bar-barnet-museum-battle',7,'locations/barnet/episodes.json','$[0].attested[0]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:barnet/barnet-1471:attested:1','episode','barnet/barnet-1471','Battle of Barnet','barnet','episode_attested',1471,1471,'Mist: the Arrivall speaks of ''a greate myste'' that stopped either side seeing the other; Warkworth independently says neither could see the other perfectly.',NULL,NULL,NULL,NULL,NULL,'bar-barnet-battlefield-project-2015-2018,bar-watson-2022-looking-for-the-site,bar-battlefields-trust-barnet,bar-arrivall-part-3,bar-warkworth-barnet,bar-barnet-society-2021,bar-barnet-museum-battle',7,'locations/barnet/episodes.json','$[0].attested[1]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:barnet/barnet-1471:attested:2','episode','barnet/barnet-1471','Battle of Barnet','barnet','episode_attested',1471,1471,'Misaligned lines: the Arrivall says the hosts did not meet ''directly frount to frount''. At the west end Warwick''s line overreached the king''s and drove it back, with many fleeing ''towards Barnet, and so forthe to London''; at the east end the king''s line overreached theirs.',NULL,NULL,NULL,NULL,NULL,'bar-barnet-battlefield-project-2015-2018,bar-watson-2022-looking-for-the-site,bar-battlefields-trust-barnet,bar-arrivall-part-3,bar-warkworth-barnet,bar-barnet-society-2021,bar-barnet-museum-battle',7,'locations/barnet/episodes.json','$[0].attested[2]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:barnet/barnet-1471:attested:3','episode','barnet/barnet-1471','Battle of Barnet','barnet','episode_attested',1471,1471,'The night before: Edward would not let his men stay in the town, lodged them much nearer the enemy than he supposed and kept silence; Warwick''s guns fired through the night and ''alway ovarshote the Kyngs hoste''.',NULL,NULL,NULL,NULL,NULL,'bar-barnet-battlefield-project-2015-2018,bar-watson-2022-looking-for-the-site,bar-battlefields-trust-barnet,bar-arrivall-part-3,bar-warkworth-barnet,bar-barnet-society-2021,bar-barnet-museum-battle',7,'locations/barnet/episodes.json','$[0].attested[3]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:barnet/barnet-1471:attested:4','episode','barnet/barnet-1471','Battle of Barnet','barnet','episode_attested',1471,1471,'Warwick arrived first and chose the ground; the Arrivall has his people drawn up ''undre an hedge-syde'' rather more than half a mile from Barnet. Other accounts say a mile, on a ''plain''.',NULL,NULL,NULL,NULL,NULL,'bar-barnet-battlefield-project-2015-2018,bar-watson-2022-looking-for-the-site,bar-battlefields-trust-barnet,bar-arrivall-part-3,bar-warkworth-barnet,bar-barnet-society-2021,bar-barnet-museum-battle',7,'locations/barnet/episodes.json','$[0].attested[4]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:barnet/barnet-1471:attested:5','episode','barnet/barnet-1471','Battle of Barnet','barnet','episode_attested',1471,1471,'A chapel for the dead was built afterwards on or near the field (Great Chronicle of London, about 1512).',NULL,NULL,NULL,NULL,NULL,'bar-barnet-battlefield-project-2015-2018,bar-watson-2022-looking-for-the-site,bar-battlefields-trust-barnet,bar-arrivall-part-3,bar-warkworth-barnet,bar-barnet-society-2021,bar-barnet-museum-battle',7,'locations/barnet/episodes.json','$[0].attested[5]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:barnet/barnet-1471:attested:6','episode','barnet/barnet-1471','Battle of Barnet','barnet','episode_attested',1471,1471,'Survey 2015–18: systematic metal-detecting, mainly in Wrotham Park, found no clear battle scatter. A few lead round shot found earlier in the Wrotham Park, Kitts End and Old Fold area are probably from the battle. No mass grave has been found.',NULL,NULL,NULL,NULL,NULL,'bar-barnet-battlefield-project-2015-2018,bar-watson-2022-looking-for-the-site,bar-battlefields-trust-barnet,bar-arrivall-part-3,bar-warkworth-barnet,bar-barnet-society-2021,bar-barnet-museum-battle',7,'locations/barnet/episodes.json','$[0].attested[6]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:barnet/barnet-1471:tradition:0','episode','barnet/barnet-1471','Battle of Barnet','barnet','episode_tradition',1471,1471,'Army sizes. The Arrivall (the king''s side) gives 9,000 against 30,000; Warkworth gives Warwick 20,000. Modern figures of about 10,000–12,000 Yorkists against about 15,000 Lancastrians (Battlefields Trust; Barnet Museum gives 10,000–13,000 and 13,000–15,000) are estimates.',NULL,NULL,NULL,NULL,NULL,'bar-barnet-battlefield-project-2015-2018,bar-watson-2022-looking-for-the-site,bar-battlefields-trust-barnet,bar-arrivall-part-3,bar-warkworth-barnet,bar-barnet-society-2021,bar-barnet-museum-battle',7,'locations/barnet/episodes.json','$[0].tradition[0]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:barnet/barnet-1471:tradition:1','episode','barnet/barnet-1471','Battle of Barnet','barnet','episode_tradition',1471,1471,'The textbook deployment (Lancastrians: Oxford on the right, Montagu in the centre, Exeter on the left, Warwick in reserve; Yorkists: Hastings left, Edward centre, Gloucester right) is a modern reconstruction, not something a contemporary wrote down.',NULL,NULL,NULL,NULL,NULL,'bar-barnet-battlefield-project-2015-2018,bar-watson-2022-looking-for-the-site,bar-battlefields-trust-barnet,bar-arrivall-part-3,bar-warkworth-barnet,bar-barnet-society-2021,bar-barnet-museum-battle',7,'locations/barnet/episodes.json','$[0].tradition[1]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:barnet/barnet-1471:tradition:2','episode','barnet/barnet-1471','Battle of Barnet','barnet','episode_tradition',1471,1471,'Oxford''s badge of a star with streams being mistaken for Edward''s sun with streams, and the cry of ''Treason'': from Warkworth alone.',NULL,NULL,NULL,NULL,NULL,'bar-barnet-battlefield-project-2015-2018,bar-watson-2022-looking-for-the-site,bar-battlefields-trust-barnet,bar-arrivall-part-3,bar-warkworth-barnet,bar-barnet-society-2021,bar-barnet-museum-battle',7,'locations/barnet/episodes.json','$[0].tradition[2]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:barnet/barnet-1471:tradition:3','episode','barnet/barnet-1471','Battle of Barnet','barnet','episode_tradition',1471,1471,'Casualties: Warkworth says 4,000; other figures run from about 1,000 to 10,000. None is reliable.',NULL,NULL,NULL,NULL,NULL,'bar-barnet-battlefield-project-2015-2018,bar-watson-2022-looking-for-the-site,bar-battlefields-trust-barnet,bar-arrivall-part-3,bar-warkworth-barnet,bar-barnet-society-2021,bar-barnet-museum-battle',7,'locations/barnet/episodes.json','$[0].tradition[3]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:barnet/barnet-1471:tradition:4','episode','barnet/barnet-1471','Battle of Barnet','barnet','episode_tradition',1471,1471,'''Dead Man''s Bottom'': a name for the valley running from Bentley Heath towards Monken Mead, marked in slightly different places on 17th-century and modern maps. The report notes it may have nothing to do with the battle.',NULL,NULL,NULL,NULL,NULL,'bar-barnet-battlefield-project-2015-2018,bar-watson-2022-looking-for-the-site,bar-battlefields-trust-barnet,bar-arrivall-part-3,bar-warkworth-barnet,bar-barnet-society-2021,bar-barnet-museum-battle',7,'locations/barnet/episodes.json','$[0].tradition[4]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:barnet/barnet-1471:tradition:5','episode','barnet/barnet-1471','Battle of Barnet','barnet','episode_tradition',1471,1471,'The Hadley Highstone (an obelisk of 1740, later moved) marks a traditional spot for Warwick''s death; there is no evidence for it.',NULL,NULL,NULL,NULL,NULL,'bar-barnet-battlefield-project-2015-2018,bar-watson-2022-looking-for-the-site,bar-battlefields-trust-barnet,bar-arrivall-part-3,bar-warkworth-barnet,bar-barnet-society-2021,bar-barnet-museum-battle',7,'locations/barnet/episodes.json','$[0].tradition[5]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:barnet/barnet-1471:unknown:0','episode','barnet/barnet-1471','Battle of Barnet','barnet','episode_unknown',1471,1471,'Where the battle was fought within a zone about 2 km long from Hadley Green to Kitts End and beyond: the survey report weighs six possible deployments and concludes that the battlefield cannot yet be identified.',NULL,NULL,NULL,NULL,NULL,'bar-barnet-battlefield-project-2015-2018,bar-watson-2022-looking-for-the-site,bar-battlefields-trust-barnet,bar-arrivall-part-3,bar-warkworth-barnet,bar-barnet-society-2021,bar-barnet-museum-battle',7,'locations/barnet/episodes.json','$[0].unknown[0]');
