INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:london/boudica-60:attested:0','episode','london/boudica-60','Boudica''s sack of Londinium','london','episode_attested',60,60,'Tacitus (Annals 14.33) is the only ancient writer to name Londinium in this context. He calls it a busy centre of merchants and goods, says Suetonius marched there, considered making it his base, decided to sacrifice the one town to save the province, and left; those who stayed behind were killed. Verulamium suffered the same.',NULL,NULL,NULL,NULL,NULL,'ev-tacitus-annals-book-xiv-chapters-29-39-loeb-tran,ev-cassius-dio-roman-history-epitome-of-book-lxii-l,ev-introduction-london-in-a-d-60-in-an-inventory-of,ev-a-research-framework-for-london-archaeology-2002,ev-roman-fort-built-in-response-to-boudica-s-uprisi,ev-bloomberg-writing-tablets-contract-of-21-october,ev-letters-from-londinium,ev-ad-50-the-story-of-roman-london,ev-london-s-catastrophic-fires,ev-boudica-s-revolt-and-the-sack-of-london-secondar',10,'locations/london/episodes.json','$[0].attested[0]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:london/boudica-60:attested:1','episode','london/boudica-60','Boudica''s sack of Londinium','london','episode_attested',60,60,'Tacitus says Londinium did not have the status of a colonia. It was a trading town about a decade or so old.',NULL,NULL,NULL,NULL,NULL,'ev-tacitus-annals-book-xiv-chapters-29-39-loeb-tran,ev-cassius-dio-roman-history-epitome-of-book-lxii-l,ev-introduction-london-in-a-d-60-in-an-inventory-of,ev-a-research-framework-for-london-archaeology-2002,ev-roman-fort-built-in-response-to-boudica-s-uprisi,ev-bloomberg-writing-tablets-contract-of-21-october,ev-letters-from-londinium,ev-ad-50-the-story-of-roman-london,ev-london-s-catastrophic-fires,ev-boudica-s-revolt-and-the-sack-of-london-secondar',10,'locations/london/episodes.json','$[0].attested[1]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:london/boudica-60:attested:2','episode','london/boudica-60','Boudica''s sack of Londinium','london','episode_attested',60,60,'There was no defence of the town: the governor abandoned it. No pitched fight at London is described in any source.',NULL,NULL,NULL,NULL,NULL,'ev-tacitus-annals-book-xiv-chapters-29-39-loeb-tran,ev-cassius-dio-roman-history-epitome-of-book-lxii-l,ev-introduction-london-in-a-d-60-in-an-inventory-of,ev-a-research-framework-for-london-archaeology-2002,ev-roman-fort-built-in-response-to-boudica-s-uprisi,ev-bloomberg-writing-tablets-contract-of-21-october,ev-letters-from-londinium,ev-ad-50-the-story-of-roman-london,ev-london-s-catastrophic-fires,ev-boudica-s-revolt-and-the-sack-of-london-secondar',10,'locations/london/episodes.json','$[0].attested[2]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:london/boudica-60:attested:3','episode','london/boudica-60','Boudica''s sack of Londinium','london','episode_attested',60,60,'A widespread layer of burnt red clay (daub), charred wood and debris, containing pre-60 coins and samian pottery, is recorded on City sites between the Walbrook and the bridgehead. MOLA treats the ''Boudican destruction of the settlement in AD 60'' as an event documented by both archaeology and text, and uses it as a dating horizon.',NULL,NULL,NULL,NULL,NULL,'ev-tacitus-annals-book-xiv-chapters-29-39-loeb-tran,ev-cassius-dio-roman-history-epitome-of-book-lxii-l,ev-introduction-london-in-a-d-60-in-an-inventory-of,ev-a-research-framework-for-london-archaeology-2002,ev-roman-fort-built-in-response-to-boudica-s-uprisi,ev-bloomberg-writing-tablets-contract-of-21-october,ev-letters-from-londinium,ev-ad-50-the-story-of-roman-london,ev-london-s-catastrophic-fires,ev-boudica-s-revolt-and-the-sack-of-london-secondar',10,'locations/london/episodes.json','$[0].attested[3]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:london/boudica-60:attested:4','episode','london/boudica-60','Boudica''s sack of Londinium','london','episode_attested',60,60,'Burning of this date has also been found in buildings beside the Roman road at the south end of the bridge in Southwark (reported from the mid-1990s onward), so the destruction is taken to have crossed the river.',NULL,NULL,NULL,NULL,NULL,'ev-tacitus-annals-book-xiv-chapters-29-39-loeb-tran,ev-cassius-dio-roman-history-epitome-of-book-lxii-l,ev-introduction-london-in-a-d-60-in-an-inventory-of,ev-a-research-framework-for-london-archaeology-2002,ev-roman-fort-built-in-response-to-boudica-s-uprisi,ev-bloomberg-writing-tablets-contract-of-21-october,ev-letters-from-londinium,ev-ad-50-the-story-of-roman-london,ev-london-s-catastrophic-fires,ev-boudica-s-revolt-and-the-sack-of-london-secondar',10,'locations/london/episodes.json','$[0].attested[4]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:london/boudica-60:attested:5','episode','london/boudica-60','Boudica''s sack of Londinium','london','episode_attested',60,60,'Buildings of the period were timber and clay (wattle-and-daub or mud-brick) and mostly low; burnt daub is the main component of the layer.',NULL,NULL,NULL,NULL,NULL,'ev-tacitus-annals-book-xiv-chapters-29-39-loeb-tran,ev-cassius-dio-roman-history-epitome-of-book-lxii-l,ev-introduction-london-in-a-d-60-in-an-inventory-of,ev-a-research-framework-for-london-archaeology-2002,ev-roman-fort-built-in-response-to-boudica-s-uprisi,ev-bloomberg-writing-tablets-contract-of-21-october,ev-letters-from-londinium,ev-ad-50-the-story-of-roman-london,ev-london-s-catastrophic-fires,ev-boudica-s-revolt-and-the-sack-of-london-secondar',10,'locations/london/episodes.json','$[0].attested[5]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:london/boudica-60:attested:6','episode','london/boudica-60','Boudica''s sack of Londinium','london','episode_attested',60,60,'Recovery: a stylus tablet from the Bloomberg site records a contract dated 21 October AD 62 to bring twenty loads of provisions from Verulamium to London; a fort of about 3.7 acres with earth-and-timber ramparts and double ditches was built at Plantation Place (Fenchurch Street) in about AD 63.',NULL,NULL,NULL,NULL,NULL,'ev-tacitus-annals-book-xiv-chapters-29-39-loeb-tran,ev-cassius-dio-roman-history-epitome-of-book-lxii-l,ev-introduction-london-in-a-d-60-in-an-inventory-of,ev-a-research-framework-for-london-archaeology-2002,ev-roman-fort-built-in-response-to-boudica-s-uprisi,ev-bloomberg-writing-tablets-contract-of-21-october,ev-letters-from-londinium,ev-ad-50-the-story-of-roman-london,ev-london-s-catastrophic-fires,ev-boudica-s-revolt-and-the-sack-of-london-secondar',10,'locations/london/episodes.json','$[0].attested[6]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:london/boudica-60:tradition:0','episode','london/boudica-60','Boudica''s sack of Londinium','london','episode_tradition',60,60,'Casualties: Tacitus gives ''close upon seventy thousand'' Roman citizens and allies killed across the places attacked (Camulodunum, Londinium, Verulamium together, not London alone). Cassius Dio gives 80,000 and ''two cities'' sacked, without naming London. Both are rhetorical round numbers; the Loeb editor''s note on Tacitus calls the figure probably valueless.',NULL,NULL,NULL,NULL,NULL,'ev-tacitus-annals-book-xiv-chapters-29-39-loeb-tran,ev-cassius-dio-roman-history-epitome-of-book-lxii-l,ev-introduction-london-in-a-d-60-in-an-inventory-of,ev-a-research-framework-for-london-archaeology-2002,ev-roman-fort-built-in-response-to-boudica-s-uprisi,ev-bloomberg-writing-tablets-contract-of-21-october,ev-letters-from-londinium,ev-ad-50-the-story-of-roman-london,ev-london-s-catastrophic-fires,ev-boudica-s-revolt-and-the-sack-of-london-secondar',10,'locations/london/episodes.json','$[0].tradition[0]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:london/boudica-60:tradition:1','episode','london/boudica-60','Boudica''s sack of Londinium','london','episode_tradition',60,60,'Atrocities: Dio''s detailed account of mutilation and impalement of captives is not tied to London and has no archaeological support. Dio survives here only in a later epitome and wrote about 150 years after the event (epitome status not verified here).',NULL,NULL,NULL,NULL,NULL,'ev-tacitus-annals-book-xiv-chapters-29-39-loeb-tran,ev-cassius-dio-roman-history-epitome-of-book-lxii-l,ev-introduction-london-in-a-d-60-in-an-inventory-of,ev-a-research-framework-for-london-archaeology-2002,ev-roman-fort-built-in-response-to-boudica-s-uprisi,ev-bloomberg-writing-tablets-contract-of-21-october,ev-letters-from-londinium,ev-ad-50-the-story-of-roman-london,ev-london-s-catastrophic-fires,ev-boudica-s-revolt-and-the-sack-of-london-secondar',10,'locations/london/episodes.json','$[0].tradition[1]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:london/boudica-60:tradition:2','episode','london/boudica-60','Boudica''s sack of Londinium','london','episode_tradition',60,60,'Rebel army size: Dio gives 120,000 at the outset and 230,000 at the final battle. Not usable.',NULL,NULL,NULL,NULL,NULL,'ev-tacitus-annals-book-xiv-chapters-29-39-loeb-tran,ev-cassius-dio-roman-history-epitome-of-book-lxii-l,ev-introduction-london-in-a-d-60-in-an-inventory-of,ev-a-research-framework-for-london-archaeology-2002,ev-roman-fort-built-in-response-to-boudica-s-uprisi,ev-bloomberg-writing-tablets-contract-of-21-october,ev-letters-from-londinium,ev-ad-50-the-story-of-roman-london,ev-london-s-catastrophic-fires,ev-boudica-s-revolt-and-the-sack-of-london-secondar',10,'locations/london/episodes.json','$[0].tradition[2]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:london/boudica-60:tradition:3','episode','london/boudica-60','Boudica''s sack of Londinium','london','episode_tradition',60,60,'Layer thickness: a secondary website gives ''typically 30-60 cm'' of bright red burnt daub, with pits filled to 1.5 m; the 1928 RCHME survey records the layer at 10-13 ft below modern ground. No primary excavation figure was verified here, and the figure will vary site to site.',NULL,NULL,NULL,NULL,NULL,'ev-tacitus-annals-book-xiv-chapters-29-39-loeb-tran,ev-cassius-dio-roman-history-epitome-of-book-lxii-l,ev-introduction-london-in-a-d-60-in-an-inventory-of,ev-a-research-framework-for-london-archaeology-2002,ev-roman-fort-built-in-response-to-boudica-s-uprisi,ev-bloomberg-writing-tablets-contract-of-21-october,ev-letters-from-londinium,ev-ad-50-the-story-of-roman-london,ev-london-s-catastrophic-fires,ev-boudica-s-revolt-and-the-sack-of-london-secondar',10,'locations/london/episodes.json','$[0].tradition[3]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:london/boudica-60:tradition:4','episode','london/boudica-60','Boudica''s sack of Londinium','london','episode_tradition',60,60,'Population of Londinium in AD 60: modern estimates of roughly 9,000-10,000 circulate in popular accounts (seen only in search results, not verified here). There is no ancient figure.',NULL,NULL,NULL,NULL,NULL,'ev-tacitus-annals-book-xiv-chapters-29-39-loeb-tran,ev-cassius-dio-roman-history-epitome-of-book-lxii-l,ev-introduction-london-in-a-d-60-in-an-inventory-of,ev-a-research-framework-for-london-archaeology-2002,ev-roman-fort-built-in-response-to-boudica-s-uprisi,ev-bloomberg-writing-tablets-contract-of-21-october,ev-letters-from-londinium,ev-ad-50-the-story-of-roman-london,ev-london-s-catastrophic-fires,ev-boudica-s-revolt-and-the-sack-of-london-secondar',10,'locations/london/episodes.json','$[0].tradition[4]');
