INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:london/london-bridge-1014:attested:0','episode','london/london-bridge-1014','Battle of London Bridge','london','episode_attested',1014,1014,'A fortified timber bridge at London existed at this time: structural timbers are tree-ring dated to c. 987-1032, and the bridge is mentioned in the law code IV Aethelred.',NULL,NULL,NULL,NULL,NULL,'ev-fact-or-folklore-the-viking-attack-on-london-bri,ev-heimskringla-saga-of-olaf-haraldson-chapter-on-t,ev-olaf-haraldsson-encyclopaedia-romana,ev-the-anglo-saxon-chronicle-eleventh-century-entri,ev-tooley-street-delight-19-march-2022-sigvatr-s-st',5,'locations/london/episodes.json','$[1].attested[0]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:london/london-bridge-1014:attested:1','episode','london/london-bridge-1014','Battle of London Bridge','london','episode_attested',1014,1014,'The Anglo-Saxon Chronicle shows the bridge mattered militarily: in 1013 part of Swein''s army drowned in the Thames because they did not use a bridge, and London held out for Aethelred and Thorkell; in 1016 Cnut''s ships could not pass it.',NULL,NULL,NULL,NULL,NULL,'ev-fact-or-folklore-the-viking-attack-on-london-bri,ev-heimskringla-saga-of-olaf-haraldson-chapter-on-t,ev-olaf-haraldsson-encyclopaedia-romana,ev-the-anglo-saxon-chronicle-eleventh-century-entri,ev-tooley-street-delight-19-march-2022-sigvatr-s-st',5,'locations/london/episodes.json','$[1].attested[1]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:london/london-bridge-1014:attested:2','episode','london/london-bridge-1014','Battle of London Bridge','london','episode_attested',1014,1014,'Aethelred returned in Lent 1014 and then drove Cnut out of Lindsey (Anglo-Saxon Chronicle).',NULL,NULL,NULL,NULL,NULL,'ev-fact-or-folklore-the-viking-attack-on-london-bri,ev-heimskringla-saga-of-olaf-haraldson-chapter-on-t,ev-olaf-haraldsson-encyclopaedia-romana,ev-the-anglo-saxon-chronicle-eleventh-century-entri,ev-tooley-street-delight-19-march-2022-sigvatr-s-st',5,'locations/london/episodes.json','$[1].attested[2]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:london/london-bridge-1014:attested:3','episode','london/london-bridge-1014','Battle of London Bridge','london','episode_attested',1014,1014,'Near-contemporary skaldic verse exists: Ottarr svarti''s Hofudlausn, stanza 7, addresses Olaf with ''you broke the bryggjur of London''; Sigvatr Thordarson''s Vikingarvisur lists a battle of Olaf''s at London and Sudvirki (Southwark). These are praise poems by Olaf''s own poets.',NULL,NULL,NULL,NULL,NULL,'ev-fact-or-folklore-the-viking-attack-on-london-bri,ev-heimskringla-saga-of-olaf-haraldson-chapter-on-t,ev-olaf-haraldsson-encyclopaedia-romana,ev-the-anglo-saxon-chronicle-eleventh-century-entri,ev-tooley-street-delight-19-march-2022-sigvatr-s-st',5,'locations/london/episodes.json','$[1].attested[3]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:london/london-bridge-1014:attested:4','episode','london/london-bridge-1014','Battle of London Bridge','london','episode_attested',1014,1014,'Olaf was venerated in London soon afterwards: six medieval churches in London and Southwark were dedicated to him, one at the south end of the bridge (Tooley Street is a corruption of St Olave''s).',NULL,NULL,NULL,NULL,NULL,'ev-fact-or-folklore-the-viking-attack-on-london-bri,ev-heimskringla-saga-of-olaf-haraldson-chapter-on-t,ev-olaf-haraldsson-encyclopaedia-romana,ev-the-anglo-saxon-chronicle-eleventh-century-entri,ev-tooley-street-delight-19-march-2022-sigvatr-s-st',5,'locations/london/episodes.json','$[1].attested[4]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:london/london-bridge-1014:tradition:0','episode','london/london-bridge-1014','Battle of London Bridge','london','episode_tradition',1014,1014,'The whole narrative of the attack comes from Snorri''s Heimskringla (Saga of St Olaf, written c. 1230): Danes holding London and a fortification at Southwark with large ditches and a rampart of timber, stone and turf; a bridge wide enough for two wagons to pass, with towers and breast-high wooden parapets on the downstream side, standing on piles.',NULL,NULL,NULL,NULL,NULL,'ev-fact-or-folklore-the-viking-attack-on-london-bri,ev-heimskringla-saga-of-olaf-haraldson-chapter-on-t,ev-olaf-haraldsson-encyclopaedia-romana,ev-the-anglo-saxon-chronicle-eleventh-century-entri,ev-tooley-street-delight-19-march-2022-sigvatr-s-st',5,'locations/london/episodes.json','$[1].tradition[0]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:london/london-bridge-1014:tradition:1','episode','london/london-bridge-1014','Battle of London Bridge','london','episode_tradition',1014,1014,'The tactics are Snorri''s alone: Olaf roofed his ships with platforms made from pulled-down houses (wood bound with hazel or withies, often rendered ''wattle'' or ''wickerwork'' in modern retellings) on stout posts, rowed up under the bridge under a hail of stones and missiles, fastened cables round the piles, and rowed hard downstream until the piles loosened and the loaded bridge gave way; Southwark was then stormed and London submitted to Aethelred.',NULL,NULL,NULL,NULL,NULL,'ev-fact-or-folklore-the-viking-attack-on-london-bri,ev-heimskringla-saga-of-olaf-haraldson-chapter-on-t,ev-olaf-haraldsson-encyclopaedia-romana,ev-the-anglo-saxon-chronicle-eleventh-century-entri,ev-tooley-street-delight-19-march-2022-sigvatr-s-st',5,'locations/london/episodes.json','$[1].tradition[1]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:london/london-bridge-1014:tradition:2','episode','london/london-bridge-1014','Battle of London Bridge','london','episode_tradition',1014,1014,'That ''bryggjur'' means the bridge: the word is plural and can mean wharves or jetties. The editor of Sigvatr''s poem argues that his stanza refers to London''s wharves, not its bridge.',NULL,NULL,NULL,NULL,NULL,'ev-fact-or-folklore-the-viking-attack-on-london-bri,ev-heimskringla-saga-of-olaf-haraldson-chapter-on-t,ev-olaf-haraldsson-encyclopaedia-romana,ev-the-anglo-saxon-chronicle-eleventh-century-entri,ev-tooley-street-delight-19-march-2022-sigvatr-s-st',5,'locations/london/episodes.json','$[1].tradition[2]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:london/london-bridge-1014:tradition:3','episode','london/london-bridge-1014','Battle of London Bridge','london','episode_tradition',1014,1014,'That Olaf fought for Aethelred: this is Snorri''s framing; the Encyclopaedia Romana page notes other sources put Olaf on the Danish side.',NULL,NULL,NULL,NULL,NULL,'ev-fact-or-folklore-the-viking-attack-on-london-bri,ev-heimskringla-saga-of-olaf-haraldson-chapter-on-t,ev-olaf-haraldsson-encyclopaedia-romana,ev-the-anglo-saxon-chronicle-eleventh-century-entri,ev-tooley-street-delight-19-march-2022-sigvatr-s-st',5,'locations/london/episodes.json','$[1].tradition[3]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:london/london-bridge-1014:tradition:4','episode','london/london-bridge-1014','Battle of London Bridge','london','episode_tradition',1014,1014,'The link to the nursery rhyme ''London Bridge is falling down'': Samuel Laing''s 1844 translation was phrased to echo the rhyme; John Clark''s study rejects the folk-memory idea.',NULL,NULL,NULL,NULL,NULL,'ev-fact-or-folklore-the-viking-attack-on-london-bri,ev-heimskringla-saga-of-olaf-haraldson-chapter-on-t,ev-olaf-haraldsson-encyclopaedia-romana,ev-the-anglo-saxon-chronicle-eleventh-century-entri,ev-tooley-street-delight-19-march-2022-sigvatr-s-st',5,'locations/london/episodes.json','$[1].tradition[4]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:london/london-bridge-1014:unknown:0','episode','london/london-bridge-1014','Battle of London Bridge','london','episode_unknown',1014,1014,'Whether any attack on the bridge happened at all, and if so in which year and on which side Olaf fought.',NULL,NULL,NULL,NULL,NULL,'ev-fact-or-folklore-the-viking-attack-on-london-bri,ev-heimskringla-saga-of-olaf-haraldson-chapter-on-t,ev-olaf-haraldsson-encyclopaedia-romana,ev-the-anglo-saxon-chronicle-eleventh-century-entri,ev-tooley-street-delight-19-march-2022-sigvatr-s-st',5,'locations/london/episodes.json','$[1].unknown[0]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:london/london-bridge-1014:unknown:1','episode','london/london-bridge-1014','Battle of London Bridge','london','episode_unknown',1014,1014,'Whether the bridge was pulled down, damaged, or simply fought over. Hagland and Watson, who think the attack plausible, say the damage may well be exaggerated.',NULL,NULL,NULL,NULL,NULL,'ev-fact-or-folklore-the-viking-attack-on-london-bri,ev-heimskringla-saga-of-olaf-haraldson-chapter-on-t,ev-olaf-haraldsson-encyclopaedia-romana,ev-the-anglo-saxon-chronicle-eleventh-century-entri,ev-tooley-street-delight-19-march-2022-sigvatr-s-st',5,'locations/london/episodes.json','$[1].unknown[1]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:london/london-bridge-1014:unknown:2','episode','london/london-bridge-1014','Battle of London Bridge','london','episode_unknown',1014,1014,'The actual form of the bridge superstructure and of any Southwark defences in 1014; no excavated evidence fixes them for this date.',NULL,NULL,NULL,NULL,NULL,'ev-fact-or-folklore-the-viking-attack-on-london-bri,ev-heimskringla-saga-of-olaf-haraldson-chapter-on-t,ev-olaf-haraldsson-encyclopaedia-romana,ev-the-anglo-saxon-chronicle-eleventh-century-entri,ev-tooley-street-delight-19-march-2022-sigvatr-s-st',5,'locations/london/episodes.json','$[1].unknown[2]');
