INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:london/barnet-1471:attested:0','episode','london/barnet-1471','Battle of Barnet','london','episode_attested',1471,1471,'Date, commanders and outcome: Edward IV defeated Warwick; Warwick and Montagu were killed; the Duke of Exeter was badly wounded and left for dead; the Earl of Oxford escaped. Henry VI was brought to the field with Edward''s army and returned to the Tower.',NULL,NULL,NULL,NULL,NULL,'ev-the-barnet-battlefield-project-2015-2018-g-foard,ev-looking-for-the-site-of-the-battle-of-barnet-b-w,ev-mystery-remains-over-lost-battlefield-site-of-14,ev-warkworth-s-chronicle-the-battle-of-barnet-text-,ev-how-much-ancient-divisions-survive-unnatural-all,ev-the-battle-of-barnet-and-the-great-north-road-se',6,'locations/london/episodes.json','$[3].attested[0]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:london/barnet-1471:attested:1','episode','london/barnet-1471','Battle of Barnet','london','episode_attested',1471,1471,'Mist or fog: reported independently by the Arrivall, Warkworth and Gerhard von Wesel''s newsletter of 17 April 1471 (which says the fog was also in London).',NULL,NULL,NULL,NULL,NULL,'ev-the-barnet-battlefield-project-2015-2018-g-foard,ev-looking-for-the-site-of-the-battle-of-barnet-b-w,ev-mystery-remains-over-lost-battlefield-site-of-14,ev-warkworth-s-chronicle-the-battle-of-barnet-text-,ev-how-much-ancient-divisions-survive-unnatural-all,ev-the-battle-of-barnet-and-the-great-north-road-se',6,'locations/london/episodes.json','$[3].attested[1]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:london/barnet-1471:attested:2','episode','london/barnet-1471','Battle of Barnet','london','episode_attested',1471,1471,'Misaligned lines: the Arrivall says the two battles did not meet ''directly frount to frount'' because of the mist. At the west end the Lancastrians overreached the king''s line and drove it back, with fugitives fleeing through Barnet towards London; at the east end the king''s line overreached theirs.',NULL,NULL,NULL,NULL,NULL,'ev-the-barnet-battlefield-project-2015-2018-g-foard,ev-looking-for-the-site-of-the-battle-of-barnet-b-w,ev-mystery-remains-over-lost-battlefield-site-of-14,ev-warkworth-s-chronicle-the-battle-of-barnet-text-,ev-how-much-ancient-divisions-survive-unnatural-all,ev-the-battle-of-barnet-and-the-great-north-road-se',6,'locations/london/episodes.json','$[3].attested[2]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:london/barnet-1471:attested:3','episode','london/barnet-1471','Battle of Barnet','london','episode_attested',1471,1471,'Night before: Edward would not let his men stay in the town, lodged them very close to the enemy and kept silence; Warwick''s guns fired through the night and overshot.',NULL,NULL,NULL,NULL,NULL,'ev-the-barnet-battlefield-project-2015-2018-g-foard,ev-looking-for-the-site-of-the-battle-of-barnet-b-w,ev-mystery-remains-over-lost-battlefield-site-of-14,ev-warkworth-s-chronicle-the-battle-of-barnet-text-,ev-how-much-ancient-divisions-survive-unnatural-all,ev-the-battle-of-barnet-and-the-great-north-road-se',6,'locations/london/episodes.json','$[3].attested[3]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:london/barnet-1471:attested:4','episode','london/barnet-1471','Battle of Barnet','london','episode_attested',1471,1471,'Warwick had arrived first and chose the ground; the Arrivall has him ''undre an hedge-syde'' somewhat more than half a mile from Barnet; von Wesel and the Great Chronicle of London imply nearer a mile. The battle was fought on foot.',NULL,NULL,NULL,NULL,NULL,'ev-the-barnet-battlefield-project-2015-2018-g-foard,ev-looking-for-the-site-of-the-battle-of-barnet-b-w,ev-mystery-remains-over-lost-battlefield-site-of-14,ev-warkworth-s-chronicle-the-battle-of-barnet-text-,ev-how-much-ancient-divisions-survive-unnatural-all,ev-the-battle-of-barnet-and-the-great-north-road-se',6,'locations/london/episodes.json','$[3].attested[4]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:london/barnet-1471:attested:5','episode','london/barnet-1471','Battle of Barnet','london','episode_attested',1471,1471,'Yorkist order of march and battle (Great Chronicle of London, Hall): Gloucester the vanguard, Edward with Clarence the main battle, Hastings the rearward. Oxford led the Lancastrian vanguard and routed the wing opposite him, which was Hastings''s.',NULL,NULL,NULL,NULL,NULL,'ev-the-barnet-battlefield-project-2015-2018-g-foard,ev-looking-for-the-site-of-the-battle-of-barnet-b-w,ev-mystery-remains-over-lost-battlefield-site-of-14,ev-warkworth-s-chronicle-the-battle-of-barnet-text-,ev-how-much-ancient-divisions-survive-unnatural-all,ev-the-battle-of-barnet-and-the-great-north-road-se',6,'locations/london/episodes.json','$[3].attested[5]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:london/barnet-1471:attested:6','episode','london/barnet-1471','Battle of Barnet','london','episode_attested',1471,1471,'A chapel for the dead was established near the field soon after; the hermitage chapel at Kitts End is the usual candidate, but geophysics there found a moat and no graves.',NULL,NULL,NULL,NULL,NULL,'ev-the-barnet-battlefield-project-2015-2018-g-foard,ev-looking-for-the-site-of-the-battle-of-barnet-b-w,ev-mystery-remains-over-lost-battlefield-site-of-14,ev-warkworth-s-chronicle-the-battle-of-barnet-text-,ev-how-much-ancient-divisions-survive-unnatural-all,ev-the-battle-of-barnet-and-the-great-north-road-se',6,'locations/london/episodes.json','$[3].attested[6]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:london/barnet-1471:attested:7','episode','london/barnet-1471','Battle of Barnet','london','episode_attested',1471,1471,'Survey finds 2015-18: of 1,007 recorded objects only 16-17 were certainly medieval; a few lead round shot are known from the Wrotham Park / Kitts End / Old Fold area. No mass grave has been found.',NULL,NULL,NULL,NULL,NULL,'ev-the-barnet-battlefield-project-2015-2018-g-foard,ev-looking-for-the-site-of-the-battle-of-barnet-b-w,ev-mystery-remains-over-lost-battlefield-site-of-14,ev-warkworth-s-chronicle-the-battle-of-barnet-text-,ev-how-much-ancient-divisions-survive-unnatural-all,ev-the-battle-of-barnet-and-the-great-north-road-se',6,'locations/london/episodes.json','$[3].attested[7]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:london/barnet-1471:tradition:0','episode','london/barnet-1471','Battle of Barnet','london','episode_tradition',1471,1471,'Army sizes: the sources contradict each other along party lines. Arrivall (Yorkist): 9,000 against 30,000. Warkworth: Edward about 7,000-8,000 against Warwick 20,000. Von Wesel: Edward 15,000-20,000. Polydore Vergil (decades later): Edward ''far superior'' in numbers. Modern compromise figures (Hammond: about 12,000 Yorkists, 15,000 Lancastrians; others 10,000 and 15,000) are estimates, and the project report notes historians now tend to reduce such numbers further.',NULL,NULL,NULL,NULL,NULL,'ev-the-barnet-battlefield-project-2015-2018-g-foard,ev-looking-for-the-site-of-the-battle-of-barnet-b-w,ev-mystery-remains-over-lost-battlefield-site-of-14,ev-warkworth-s-chronicle-the-battle-of-barnet-text-,ev-how-much-ancient-divisions-survive-unnatural-all,ev-the-battle-of-barnet-and-the-great-north-road-se',6,'locations/london/episodes.json','$[3].tradition[0]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:london/barnet-1471:tradition:1','episode','london/barnet-1471','Battle of Barnet','london','episode_tradition',1471,1471,'The tidy textbook deployment (Lancastrians: Oxford right, Montagu centre, Exeter left, Warwick in reserve; Yorkists: Hastings left, Edward centre, Gloucester right) is a modern reconstruction. The wing positions are inferred from military convention (vanguard on the right) plus the Arrivall; Hall, the only chronicler to give a Lancastrian order, puts Oxford and Montagu on the left, Warwick and Exeter on the right, and Somerset (who was not there) in the centre.',NULL,NULL,NULL,NULL,NULL,'ev-the-barnet-battlefield-project-2015-2018-g-foard,ev-looking-for-the-site-of-the-battle-of-barnet-b-w,ev-mystery-remains-over-lost-battlefield-site-of-14,ev-warkworth-s-chronicle-the-battle-of-barnet-text-,ev-how-much-ancient-divisions-survive-unnatural-all,ev-the-battle-of-barnet-and-the-great-north-road-se',6,'locations/london/episodes.json','$[3].tradition[1]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:london/barnet-1471:tradition:2','episode','london/barnet-1471','Battle of Barnet','london','episode_tradition',1471,1471,'Oxford''s star badge mistaken for Edward''s sun and the cry of ''Treason'': from Warkworth alone. The History of Parliament notes it ''is perhaps not to be taken too seriously'' and that there is no evidence a star with streams was a de Vere badge.',NULL,NULL,NULL,NULL,NULL,'ev-the-barnet-battlefield-project-2015-2018-g-foard,ev-looking-for-the-site-of-the-battle-of-barnet-b-w,ev-mystery-remains-over-lost-battlefield-site-of-14,ev-warkworth-s-chronicle-the-battle-of-barnet-text-,ev-how-much-ancient-divisions-survive-unnatural-all,ev-the-battle-of-barnet-and-the-great-north-road-se',6,'locations/london/episodes.json','$[3].tradition[2]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:london/barnet-1471:tradition:3','episode','london/barnet-1471','Battle of Barnet','london','episode_tradition',1471,1471,'Montagu wearing Edward''s livery and being killed by Warwick''s own men (Warkworth): regarded as improbable.',NULL,NULL,NULL,NULL,NULL,'ev-the-barnet-battlefield-project-2015-2018-g-foard,ev-looking-for-the-site-of-the-battle-of-barnet-b-w,ev-mystery-remains-over-lost-battlefield-site-of-14,ev-warkworth-s-chronicle-the-battle-of-barnet-text-,ev-how-much-ancient-divisions-survive-unnatural-all,ev-the-battle-of-barnet-and-the-great-north-road-se',6,'locations/london/episodes.json','$[3].tradition[3]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:london/barnet-1471:tradition:4','episode','london/barnet-1471','Battle of Barnet','london','episode_tradition',1471,1471,'Warwick killed fleeing to a wood, or while reaching his horse: details vary by source. The Hadley Highstone obelisk (1740) marks a traditional spot only.',NULL,NULL,NULL,NULL,NULL,'ev-the-barnet-battlefield-project-2015-2018-g-foard,ev-looking-for-the-site-of-the-battle-of-barnet-b-w,ev-mystery-remains-over-lost-battlefield-site-of-14,ev-warkworth-s-chronicle-the-battle-of-barnet-text-,ev-how-much-ancient-divisions-survive-unnatural-all,ev-the-battle-of-barnet-and-the-great-north-road-se',6,'locations/london/episodes.json','$[3].tradition[4]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:london/barnet-1471:tradition:5','episode','london/barnet-1471','Battle of Barnet','london','episode_tradition',1471,1471,'Casualties: Sir John Paston''s letter says over 1,000 besides the notables; Warkworth about 4,000; a foreign report 10,000; von Wesel says more than 10,000 broken arrows lay on the field. None is reliable.',NULL,NULL,NULL,NULL,NULL,'ev-the-barnet-battlefield-project-2015-2018-g-foard,ev-looking-for-the-site-of-the-battle-of-barnet-b-w,ev-mystery-remains-over-lost-battlefield-site-of-14,ev-warkworth-s-chronicle-the-battle-of-barnet-text-,ev-how-much-ancient-divisions-survive-unnatural-all,ev-the-battle-of-barnet-and-the-great-north-road-se',6,'locations/london/episodes.json','$[3].tradition[5]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('episode:london/barnet-1471:tradition:6','episode','london/barnet-1471','Battle of Barnet','london','episode_tradition',1471,1471,'Place-names ''Gladmore Heath'' and ''Dead Man''s Bottom'': the project report shows ''Gladmore Heath'' grew out of a map label (''Gladmore heath field'') on Norden''s 1598 map, and treats Dead Man''s Bottom as a late, possibly spurious association.',NULL,NULL,NULL,NULL,NULL,'ev-the-barnet-battlefield-project-2015-2018-g-foard,ev-looking-for-the-site-of-the-battle-of-barnet-b-w,ev-mystery-remains-over-lost-battlefield-site-of-14,ev-warkworth-s-chronicle-the-battle-of-barnet-text-,ev-how-much-ancient-divisions-survive-unnatural-all,ev-the-battle-of-barnet-and-the-great-north-road-se',6,'locations/london/episodes.json','$[3].tradition[6]');
