INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('stone:stonehenge/6:state_1625','stone','stonehenge/6','6','stonehenge','state_1625',1625,1625,'leaning','Leaning in 1625 (assumed from 1901 state; direction not established): Encyclopaedia Britannica 1911 reports trilithon 6-7 had "slewed round" with its lintel turned in 1901, and English Heritage says the restoration began in 1919 with stones 6 and 7, one leaning inward and one outward. Stukeley''s 1720s count of 17 standing includes both. Which of the two leaned in/out is not given in fetched sources; the assignment here (6 inward, 7 outward) is arbitrary.',NULL,NULL,NULL,NULL,'sto-sos-stones,sto-stukeley-1740,sto-barclay-1895,sto-antiquity-keeping-time,sto-eb1911-stonehenge,sto-eh-100-years-care',6,'locations/stonehenge/stones.json','$.stones[5]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('stone:stonehenge/7:state_1625','stone','stonehenge/7','7','stonehenge','state_1625',1625,1625,'leaning','Leaning in 1625 (assumed from 1901 state; direction not established): Encyclopaedia Britannica 1911 reports trilithon 6-7 had "slewed round" with its lintel turned in 1901, and English Heritage says the restoration began in 1919 with stones 6 and 7, one leaning inward and one outward. Stukeley''s 1720s count of 17 standing includes both. Which of the two leaned in/out is not given in fetched sources; the assignment here (6 inward, 7 outward) is arbitrary.',NULL,NULL,NULL,NULL,'sto-sos-stones,sto-stukeley-1740,sto-barclay-1895,sto-antiquity-keeping-time,sto-eb1911-stonehenge,sto-eh-100-years-care',6,'locations/stonehenge/stones.json','$.stones[6]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('stone:stonehenge/8:state_1625','stone','stonehenge/8','8','stonehenge','state_1625',1625,1625,'broken','Broken portion in 1625 (assumed): lying/broken on Petrie''s and Barclay''s plan; Stukeley counted 6 uprights lying on the ground in the 1720s (24 of 30 positions with stones: 17 standing, 1 leaning, 6 lying) so the fallen set was already about this size by then; which six they were is not stated in the text and a fall date for each is unknown. Assumed down by 1625 - no evidence of a later fall.',NULL,NULL,NULL,NULL,'sto-sos-stones,sto-stukeley-1740,sto-barclay-1895,sto-antiquity-keeping-time',4,'locations/stonehenge/stones.json','$.stones[7]');
