INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('stone:stonehenge/13:state_1625','stone','stonehenge/13','13','stonehenge','state_1625',1625,1625,'missing','Missing in 1625 (assumed): no stone at this position on Stukeley''s 1720s count (24 of 30 visible, 22 lintels and 6 piers gone) or Petrie 1880; Barclay 1895 lists five piers missing (13, 17, 18, 20, 24). Antiquity (2022) places the six missing uprights in the south-west and concludes they were robbed in antiquity; parchmarks of 2013 and excavated sockets mark some positions (Banton 2014; Cleal 1995). Which of these five positions has a proved stonehole is not established from fetched sources; the stone''s existence is inferred.',NULL,NULL,NULL,NULL,'sto-sos-stones,sto-stukeley-1740,sto-barclay-1895,sto-antiquity-keeping-time,sto-sos-missing',5,'locations/stonehenge/stones.json','$.stones[12]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('stone:stonehenge/14:state_1625','stone','stonehenge/14','14','stonehenge','state_1625',1625,1625,'leaning','Leaning in 1625 (assumed from the 1720s): Stukeley describes one upright "at the back of the temple or on the south-west" that leans upon a stone of the inner circle (1720s), and Barclay 1895 says the later fall of pier 14 damaged bluestones 37-39; Burl (via Stones of Stonehenge) identifies 14 with Aubrey''s fallen "Friar''s Heel" stone, which would mean it was already down c.1666-93 - a conflict that is unresolved. Date of fall unknown (between the 1720s and 1771 by Burl''s reading).',NULL,NULL,NULL,NULL,'sto-sos-stones,sto-stukeley-1740,sto-barclay-1895,sto-antiquity-keeping-time',4,'locations/stonehenge/stones.json','$.stones[13]');
