INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('stone:stonehenge/22:state_1625','stone','stonehenge/22','22','stonehenge','state_1625',1625,1625,'standing','Standing in 1625 (assumed, high-ish confidence): Stukeley (observations 1719-24, pub. 1740) counts 17 uprights of the outer circle standing, a number equal to today, so the 1900 fall of stone 22 (31 Dec 1900, with lintel 122) was not a long-standing ruin; it was re-erected in the 1950s. No earlier fall is recorded.',NULL,NULL,NULL,NULL,'sto-sos-stones,sto-stukeley-1740,sto-barclay-1895,sto-antiquity-keeping-time',4,'locations/stonehenge/stones.json','$.stones[21]');
