INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('stone:stonehenge/51:state_1625','stone','stonehenge/51','51','stonehenge','state_1625',1625,1625,'standing','Standing in 1625: Stukeley (1720s) describes the first two trilithons on the left of the entrance (51-52 and 53-54) as entire and in situ, and they have stood ever since (Stones of Stonehenge: "remained standing for 4,500 years"). No fall recorded; assumed standing in 1625.',NULL,NULL,NULL,NULL,'sto-sos-stones,sto-stukeley-1740,sto-barclay-1895',3,'locations/stonehenge/stones.json','$.stones[58]');
