INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('stone:stonehenge/80:state_1625','stone','stonehenge/80','80','stonehenge','state_1625',1625,1625,'broken','Broken (2-3 pieces) under the fallen Great Trilithon in 1625, LOW confidence (tied to the date of the 55/156 fall): Stukeley (5 July 1723) found it a cubit thick, "broken in two or three pieces by the ponderous mass of the impost and one upright" (quoted in Long 1876); the Altar Stone is in two pieces under 55b and 156 today (Stones of Stonehenge). If the Great Trilithon was still standing in 1625 it lay whole.',NULL,NULL,NULL,NULL,'sto-sos-stones,sto-stukeley-1740,sto-long-1876,sto-barclay-1895,sto-osm-overpass',5,'locations/stonehenge/stones.json','$.stones[83]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('stone:stonehenge/91:state_1625','stone','stonehenge/91','91','stonehenge','state_1625',1625,1625,'leaning','Leaning/standing in 1625 (assumed as in 1771): Stukeley (1720s) describes the two stones within the vallum - one stands, the other leans a little; Dr John Smith (1771) says the eastern one "leans very much towards the ditch"; it has since fallen eastwards (Barclay 1895). No 1625 record.',NULL,NULL,NULL,NULL,'sto-sos-stones,sto-stukeley-1740,sto-barclay-1895,sto-osm-overpass',4,'locations/stonehenge/stones.json','$.stones[84]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('stone:stonehenge/92:state_1625','stone','stonehenge/92','92','stonehenge','state_1625',1625,1625,'missing','Missing in 1625 (assumed): only a mound with a cup-like depression remains (Barclay 1895: mounds and stones alternate); Stukeley (1720s) records just two stones within the vallum. Whether a stone stood on this mound in 1625 is unknown. The position is the modern marker (OSM location approximated).',NULL,NULL,NULL,NULL,'sto-sos-stones,sto-sos-missing,sto-stukeley-1740,sto-barclay-1895,sto-osm-overpass',5,'locations/stonehenge/stones.json','$.stones[85]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('stone:stonehenge/93:state_1625','stone','stonehenge/93','93','stonehenge','state_1625',1625,1625,'standing','Standing in 1625 (assumed): in situ in the 1720s (Stukeley: one of the two stones stands) and today (Barclay 1895: "in situ").',NULL,NULL,NULL,NULL,'sto-sos-stones,sto-stukeley-1740,sto-barclay-1895,sto-osm-overpass',4,'locations/stonehenge/stones.json','$.stones[86]');
