INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('stone:stonehenge/130:state_1625','stone','stonehenge/130','130','stonehenge','state_1625',1625,1625,'standing','Standing (in place) in 1625 (assumed): in situ today and one of the five lintels Stukeley (1720s) records on the 11 continuous uprights by the entrance; no source records it falling or being replaced.',NULL,NULL,NULL,NULL,'sto-sos-stones,sto-stukeley-1740,sto-barclay-1895,sto-antiquity-keeping-time,sto-sos-about,sto-eb1911-stonehenge',6,'locations/stonehenge/stones.json','$.stones[120]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('stone:stonehenge/150:state_1625','stone','stonehenge/150','150','stonehenge','state_1625',1625,1625,'fallen','Fallen, partly buried, in 1625 (assumed, low confidence): Barclay 1895 calls it the unique bluestone impost with two mortises, lying in the NE arc of the bluestone circle, fallen from a single standing position; no earlier record of when it fell.',NULL,NULL,NULL,NULL,'sto-sos-stones,sto-barclay-1895,sto-field-2015-blog,sto-osm-overpass',4,'locations/stonehenge/stones.json','$.stones[121]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('stone:stonehenge/152:state_1625','stone','stonehenge/152','152','stonehenge','state_1625',1625,1625,'standing','Standing (in place) in 1625: Stukeley (1720s) records trilithons 51-52 and 53-54 with their impost entire; they have stood continuously (Stones of Stonehenge).',NULL,NULL,NULL,NULL,'sto-sos-stones,sto-stukeley-1740,sto-barclay-1895',3,'locations/stonehenge/stones.json','$.stones[122]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('stone:stonehenge/154:state_1625','stone','stonehenge/154','154','stonehenge','state_1625',1625,1625,'standing','Standing (in place) in 1625: Stukeley (1720s) records trilithons 51-52 and 53-54 with their impost entire; they have stood continuously (Stones of Stonehenge).',NULL,NULL,NULL,NULL,'sto-sos-stones,sto-stukeley-1740,sto-barclay-1895',3,'locations/stonehenge/stones.json','$.stones[123]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('stone:stonehenge/156:state_1625','stone','stonehenge/156','156','stonehenge','state_1625',1625,1625,'fallen','Fallen in 1625, LOW confidence: lies on its edge across the west end of the Altar Stone (Stones of Stonehenge); Stukeley (1720s) describes it dislodged and fallen on the altar; Aubrey attributes the fall of the great stone to the 1620 digging (Long 1876; Barclay 1895). Alternative: still on top of 55-56 in 1625.',NULL,NULL,NULL,NULL,'sto-sos-stones,sto-stukeley-1740,sto-barclay-1895,sto-long-1876',4,'locations/stonehenge/stones.json','$.stones[124]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('stone:stonehenge/158:state_1625','stone','stonehenge/158','158','stonehenge','state_1625',1625,1625,'standing','Standing (in place) in 1625: fell westwards with 57 and 58 on 3 Jan 1797, re-erected 1958 (Stones of Stonehenge, Barclay 1895); Stukeley (1720s) records it in place apart from chipping of its end.',NULL,NULL,NULL,NULL,'sto-sos-stones,sto-stukeley-1740,sto-barclay-1895,sto-eb1911-stonehenge',4,'locations/stonehenge/stones.json','$.stones[125]');
INSERT INTO "fact"("fact_id","entity_type","entity_id","entity_name","location_id","kind","year_from","year_to","value_text","detail","lat","lon","evidence","confidence","source_ids","n_sources","origin_file","origin_path") VALUES('stone:stonehenge/160:state_1625','stone','stonehenge/160','160','stonehenge','state_1625',1625,1625,'broken','Fallen and broken in 1625: Stukeley (1720s) records the impost of the last trilithon fallen forwards and broken in three; Barclay 1895: before 1574 on a British Museum drawing (secondary report). Three fragments 160a-c today.',NULL,NULL,NULL,NULL,'sto-sos-stones,sto-stukeley-1740,sto-barclay-1895',3,'locations/stonehenge/stones.json','$.stones[126]');
