INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/st-pauls',4,'Old St Paul''s extended east (the New Work, 1251–1314), with renewed spire',1251,1314,1561,'handover',NULL,1,'The Gothic ''New Work'' east end was begun in 1251 (VCH) and the renewed spire dedicated in 1314, used here as the completion of the work (the 1314 date is not confirmed by the VCH pages read). Extension phase: the Romanesque church stands until then. Spire destroyed by lightning and fire, 4 June 1561. All phases from 1087 share the west front (89.5 m west of the landmark point), so the New Work extends the church eastwards, and the crossing tower stays where the Romanesque church has it (93 m from the west front).','church','{"l": 179, "w": 32, "h": 28, "wall": "caen", "roof": "lead", "aisles": true, "transept": {"l": 88, "w": 28}, "tower": {"w": 16, "h": 62, "at": "crossing"}, "spire": 82, "crossingAt": 0.52, "westEnd": -89.5}','$[19].phases[4]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/st-pauls',5,'Old St Paul''s without its spire',1561,NULL,NULL,NULL,NULL,1,'Roofs repaired 1561–66; the spire was never rebuilt. Tower stump about 62 m.','church','{"l": 179, "w": 32, "h": 28, "wall": "caen", "roof": "lead", "aisles": true, "transept": {"l": 88, "w": 28}, "tower": {"w": 16, "h": 62, "at": "crossing"}, "crossingAt": 0.52, "westEnd": -89.5}','$[19].phases[5]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/queenhithe',0,'Revetted dock',970,1021,NULL,NULL,NULL,0,'Revetments late 10th century; embankments tree-ring dated 1021 and 1045.','dock','{"l": 55, "w": 34, "inlet": true}','$[20].phases[0]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/saxon-bridge',0,'Successive timber bridges (one destroyed by the storm of 1091)',990,1000,1135,'burned',NULL,0,'A bridge existed by about 1000. London Museum records its destruction by a storm in 1091; when it was rebuilt is not recorded, so this phase stands for successive bridges, not one structure. The 1014 ''pulling down'' is saga tradition only. Burned in 1135 or 1136 depending on the source.','bridge','{"type": "timber", "width": 6, "deck": 5, "span": 11}','$[21].phases[0]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/saxon-bridge',1,'Rebuilt timber bridge',1136,1163,1209,'demolished',NULL,0,'Last timber rebuild 1163 (Peter of Colechurch); replaced by the stone bridge built alongside.','bridge','{"type": "timber", "width": 6, "deck": 5, "span": 11}','$[21].phases[1]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/old-london-bridge',0,'Stone bridge',1176,1209,NULL,NULL,NULL,0,NULL,'stone-bridge','{"width": 6.1, "deck": 8, "arches": 19}','$[22].phases[0]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/bridge-houses',0,'First houses',1209,1211,1212,'burned',NULL,0,'Destroyed in the fire of 11 July 1212.','bridge-houses','{"storeys": 2, "style": "medieval", "deck": 8}','$[23].phases[0]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/bridge-houses',1,'Medieval houses',1214,1260,1480,'handover',NULL,0,NULL,'bridge-houses','{"storeys": 3, "style": "medieval", "deck": 8}','$[23].phases[1]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/bridge-houses',2,'Tudor houses',1480,NULL,NULL,NULL,NULL,1,NULL,'bridge-houses','{"storeys": 4, "style": "tudor", "deck": 8}','$[23].phases[2]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/bridge-chapel',0,'First chapel',1205,1212,1387,'replaced',NULL,0,NULL,'bridge-chapel','{"h": 12, "style": "early"}','$[24].phases[0]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/bridge-chapel',1,'Rebuilt chapel',1387,1396,1549,'handover',NULL,0,'Rebuilt 1387–96.','bridge-chapel','{"h": 15, "style": "perpendicular"}','$[24].phases[1]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/bridge-chapel',2,'Chapel converted to a dwelling',1549,NULL,NULL,NULL,NULL,1,'Chapel closed 1548; converted to a house in 1549 (first lease 1553 in another account).','bridge-chapel','{"h": 15, "style": "house"}','$[24].phases[2]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/bridge-stone-gate',0,'Stone gate',1200,1209,1437,'ruin',1440,0,'Collapsed with two arches in January 1437.','bridge-gate','{"h": 16, "w": 11}','$[25].phases[0]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/bridge-stone-gate',1,'Rebuilt stone gate',1437,1466,1577,'handover',NULL,0,'Rebuilt after the collapse of January 1437 (completion about 1466); burned in Fauconberg''s attack of 1471 and repaired.','bridge-gate','{"h": 19, "w": 12}','$[25].phases[1]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/bridge-stone-gate',2,'Rebuilt stone gate with traitors'' heads',1577,NULL,NULL,NULL,NULL,1,'Traitors'' heads were shown on the Drawbridge Gate until it was taken down in April 1577 (Stow 1633, via MoEML) and from then on over the gate at the Southwark end.','bridge-gate','{"h": 19, "w": 12, "heads": 1577}','$[25].phases[2]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/bridge-drawbridge-gate',0,'Drawbridge tower',1250,1258,1426,'replaced',NULL,0,'Early form poorly documented.','bridge-gate','{"h": 14, "w": 10, "pier": 12}','$[26].phases[0]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/bridge-drawbridge-gate',1,'Rebuilt drawbridge gate',1426,1428,1577,'demolished',NULL,0,NULL,'bridge-gate','{"h": 17, "w": 10, "pier": 12}','$[26].phases[1]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/nonsuch-house',0,'Nonsuch House',1577,1579,NULL,NULL,NULL,0,'Tower taken down 1577; house finished September 1579 (Stow).','nonsuch','{"h": 17, "w": 15, "d": 7.6}','$[27].phases[0]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/bridge-waterworks',0,'Waterwheels',1581,1582,NULL,NULL,NULL,0,'Operational 1582 (Stow). Corn mills were added at the south end c. 1590–91 (not modelled).','waterwheel','{"d": 6}','$[28].phases[0]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/st-magnus',0,'Early church',1100,1128,1250,'handover',NULL,0,NULL,'church','{"l": 22, "w": 9, "h": 7, "wall": "ragstone", "roof": "shingle"}','$[29].phases[0]');
