INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/fishmongers-hall',0,'Company hall',1434,1444,NULL,NULL,NULL,0,NULL,'courtyard','{"l": 36, "w": 30, "h": 9, "range": 8, "wall": "ragstone", "roof": "tile"}','$[30].phases[0]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/st-olave',0,'Church',1070,NULL,NULL,NULL,NULL,0,'In existence by the late 11th century: probably the church recorded in Domesday (1086) and first named in 1096. 1070 is a display anchor, not a construction date; a pre-Conquest origin is possible but not established by the sources read.','church','{"l": 30, "w": 14, "h": 9, "wall": "ragstone", "roof": "tile", "tower": {"w": 7, "h": 22, "at": "west"}}','$[31].phases[0]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/st-mary-overie',0,'Minster recorded in Domesday (form unknown)',1086,NULL,1106,'replaced',NULL,0,'The first written reference is a ''minster'' in Domesday Book (1086); in 1106 the church was refounded as an Augustinian priory (Southwark Cathedral). Its form is unknown and the small church shown is a placeholder; 1086 is the date of the record, not of building.','church','{"l": 30, "w": 12, "h": 9, "wall": "ragstone", "roof": "shingle", "placeholder": true}','$[32].phases[0]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/st-mary-overie',1,'Norman priory church',1106,1140,1212,'burned',NULL,0,'Refounded 1106; burned 11 July 1212 in the same fire as the bridge.','church','{"l": 55, "w": 18, "h": 13, "wall": "ragstone", "roof": "shingle", "transept": {"l": 34, "w": 9}, "tower": {"w": 9, "h": 22, "at": "crossing"}}','$[32].phases[1]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/st-mary-overie',2,'Gothic priory church',1220,1300,1520,'handover',NULL,0,NULL,'church','{"l": 80, "w": 21, "h": 17, "wall": "ragstone", "roof": "lead", "aisles": true, "transept": {"l": 36, "w": 10}, "tower": {"w": 10.5, "h": 30, "at": "crossing"}}','$[32].phases[2]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/st-mary-overie',3,'Church with heightened tower',1520,1528,NULL,NULL,NULL,1,'The two upper stages of the tower were built in 1520–28 (VCH Surrey), shown as an extension rising while the earlier church stands. Priory surrendered 27 October 1539; parish church of St Saviour from 1540.','church','{"l": 80, "w": 21, "h": 17, "wall": "ragstone", "roof": "lead", "aisles": true, "transept": {"l": 36, "w": 10}, "tower": {"w": 10.5, "h": 45, "at": "crossing", "pinnacles": true}}','$[32].phases[3]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/winchester-palace',0,'Bishop''s palace',1144,1160,1300,'handover',NULL,0,'Henry of Blois, c. 1140s.','hall','{"l": 30, "w": 11, "h": 9, "wall": "ragstone", "roof": "shingle"}','$[33].phases[0]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/winchester-palace',1,'Palace with great hall',1300,NULL,NULL,NULL,NULL,1,'The standing great hall is a 14th-century rebuild.','courtyard','{"l": 70, "w": 48, "h": 10, "range": 10, "wall": "ragstone", "roof": "tile", "greatHall": true}','$[33].phases[1]');
