INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/roman-quay',0,'First timber revetment',52,52,62,'replaced',NULL,0,'Tree-ring date 52 CE.','quay','{"width": 9, "warehouses": false}','$[35].phases[0]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/roman-quay',1,'Timber quays and warehouses',63,102,255,'decay',400,0,'Tree-ring anchors: great quay 63, landing stage c. 70, extension 102, further advances to the mid 3rd century; quays dismantled by the 4th century.','quay','{"width": 12, "warehouses": true}','$[35].phases[1]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/westminster-abbey',0,'Edward the Confessor''s abbey',1045,1065,1245,'replaced',NULL,0,NULL,'church','{"l": 98, "w": 22, "h": 17, "wall": "caen", "roof": "lead", "aisles": true, "transept": {"l": 46, "w": 12}, "tower": {"w": 11, "h": 32, "at": "crossing"}}','$[36].phases[0]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/westminster-abbey',1,'Henry III''s abbey: east end, transepts and part of the nave',1245,1269,1376,'handover',NULL,0,'By 1269 only the east end, transepts and first nave bays were finished; the Romanesque nave stood for another century. The east end is pinned 60 m east of the landmark point, where Henry VII''s Chapel (its own landmark) later joins it; the nave rebuilt from 1376 shares it.','church','{"l": 110, "w": 24, "h": 31, "wall": "caen", "roof": "lead", "aisles": true, "transept": {"l": 62, "w": 24}, "crossingAt": 0.6, "eastEnd": 60}','$[36].phases[1]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/westminster-abbey',2,'Abbey with the nave rebuilt westwards (1376–1517)',1376,1517,NULL,NULL,NULL,1,'Work on the new nave resumed in 1376 and was finished in 1517 (Westminster Abbey). An extension phase: Henry III''s church with the old Romanesque nave stays standing while the new nave rises, and is replaced only when the nave is complete. No west towers before 1745. Drawn 124 m long from the east end it shares with Henry III''s church, so the new work rises at the west: the 156 m used before is the Abbey''s length including Henry VII''s Chapel, which is its own 32 m landmark east of it (the two models had double-counted it). The crossing is kept where Henry III''s church has it.','church','{"l": 124, "w": 24, "h": 31, "wall": "caen", "roof": "lead", "aisles": true, "transept": {"l": 62, "w": 24}, "crossingAt": 0.645, "eastEnd": 60}','$[36].phases[2]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/henry-vii-chapel',0,'Lady Chapel',1503,1516,NULL,NULL,NULL,0,'Consecrated 19 February 1516.','church','{"l": 32, "w": 21, "h": 20, "wall": "caen", "roof": "lead", "pinnacles": true}','$[37].phases[0]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/westminster-hall',0,'Norman hall',1097,1099,1393,'handover',NULL,0,NULL,'hall','{"l": 73, "w": 20.5, "h": 12, "wall": "ragstone", "roof": "shingle", "pitch": 0.9}','$[38].phases[0]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/westminster-hall',1,'Hall heightened and given its hammerbeam roof',1393,1399,NULL,NULL,NULL,1,'Roof commissioned 1393; the Norman walls were kept, heightened and refaced to carry it. A Commons debate of 1914 gives the work as 1393–1402; the lanterns are usually dated 1397–98 and work stopped in 1401 with decoration unfinished. 1399 is an approximate display anchor for substantial completion, not a documented date. Extension phase: the Norman hall stays standing until then.','hall','{"l": 73, "w": 20.5, "h": 13, "wall": "ragstone", "roof": "lead", "pitch": 1.1, "endTowers": true}','$[38].phases[1]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/white-tower',0,'White Tower',1078,1100,NULL,NULL,NULL,0,'Begun c. 1075–81, complete by c. 1100; 27 m to the battlements. Whitewashed from 1240.','keep','{"w": 36, "d": 32.5, "h": 27, "turrets": true, "wall": "caen"}','$[39].phases[0]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/tower-inner-ward',0,'Inner curtain',1238,1250,NULL,NULL,NULL,0,'Henry III, 1238–1240s. A first stone enclosure and ditch of c. 1190 is not shown.','wall','{"h": 10, "thick": 3, "wall": "ragstone", "crenel": true, "towers": 55, "closed": true}','$[40].phases[0]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/tower-outer-ward',0,'Outer curtain',1275,1285,NULL,NULL,NULL,0,NULL,'wall','{"h": 7, "thick": 2.5, "wall": "ragstone", "crenel": true, "towers": 0, "closed": true}','$[41].phases[0]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/baynards-castle-1',0,'Norman castle',1070,1087,1213,'demolished',NULL,0,NULL,'keep','{"w": 18, "d": 16, "h": 15, "turrets": false, "wall": "ragstone", "placeholder": true}','$[42].phases[0]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/baynards-castle-2',0,'Riverside mansion',1428,1435,1501,'handover',NULL,0,'A 14th-century riverside house preceded it; rebuilt after the fire of 1428.','courtyard','{"l": 60, "w": 45, "h": 12, "range": 10, "wall": "ragstone", "roof": "tile", "towers": 2}','$[43].phases[0]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/baynards-castle-2',1,'Henry VII''s rebuilding',1501,NULL,NULL,NULL,NULL,1,NULL,'courtyard','{"l": 70, "w": 48, "h": 15, "range": 10, "wall": "ragstone", "roof": "lead", "towers": 4}','$[43].phases[1]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/temple-church',0,'Round church',1160,1185,1240,'handover',NULL,0,NULL,'church','{"l": 14, "w": 10, "h": 9, "wall": "caen", "roof": "lead", "round": 18, "westEnd": 2}','$[44].phases[0]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/temple-church',1,'Round church with hall chancel',1240,NULL,NULL,NULL,NULL,1,'The chancel was added east of the round nave (consecrated 1240); both phases pin the junction with the round, so the extension grows eastwards only.','church','{"l": 28, "w": 18, "h": 11, "wall": "caen", "roof": "lead", "round": 18, "westEnd": 2}','$[44].phases[1]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/blackfriars',0,'Dominican friary',1276,1295,1538,'handover',NULL,0,'Site granted 1276; church begun 1279 and built into the 1290s.','friary','{"l": 67, "w": 20, "h": 14, "cloister": 34, "wall": "ragstone", "roof": "lead", "fleche": 14}','$[45].phases[0]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/blackfriars',1,'Converted precinct (church demolished)',1538,NULL,NULL,NULL,NULL,1,'Surrendered 12 November 1538 (VCH); the church was demolished afterwards, in years these sources do not fix, so 1538 is the institutional, not the physical, boundary. Theatres in the former precinct: Blackfriars I from 1576 and Blackfriars II from 1596, distinct venues (EMLoT); the King''s Men used the second from 1608–09.','courtyard','{"l": 40, "w": 40, "h": 9, "range": 8, "wall": "ragstone", "roof": "tile"}','$[45].phases[1]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/greyfriars',0,'First friary',1225,1240,1306,'handover',NULL,0,'Drawn in the place of the great church''s choir (its east end pinned to the great church''s), since parts of the first church were taken into the new choir. Its exact plan is not known.','friary','{"l": 40, "w": 14, "h": 10, "cloister": 28, "wall": "ragstone", "roof": "tile", "eastEnd": 45.7}','$[46].phases[0]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/greyfriars',1,'Great church',1306,1327,NULL,NULL,NULL,1,'Foundation stone of the great church laid 1306, finished 1327 (VCH; a chronicler says it was still not dedicated in 1357). VCH gives 300 × 89 ft; the 64 ft height is from another account. Parts of the first church were taken into the new choir, so the first friary stays standing while the great church rises (extension phase). Surrendered 12 November 1538; kept as Christ Church parish church from 1547.','friary','{"l": 91.4, "w": 27.1, "h": 19.5, "cloister": 36, "wall": "ragstone", "roof": "lead", "fleche": 16}','$[46].phases[1]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/austin-friars',0,'Friary',1253,1280,1354,'handover',NULL,0,NULL,'friary','{"l": 45, "w": 16, "h": 11, "cloister": 28, "wall": "ragstone", "roof": "tile"}','$[47].phases[0]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/austin-friars',1,'Rebuilt church with spire',1354,NULL,1600,'handover',NULL,1,NULL,'friary','{"l": 78, "w": 25, "h": 15, "cloister": 30, "wall": "ragstone", "roof": "lead", "fleche": 26}','$[47].phases[1]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/austin-friars',2,'Nave only (Dutch Church)',1600,NULL,NULL,NULL,NULL,1,'Choir and steeple taken down around 1600. The nave kept is the west part of the rebuilt church: its west end is pinned to that church''s west front.','church','{"l": 46, "w": 25, "h": 15, "wall": "ragstone", "roof": "lead", "aisles": true, "westEnd": -39}','$[47].phases[2]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/holy-trinity-aldgate',0,'Priory',1108,1150,1532,'demolished',NULL,0,'Founded 1107/08; burned 1132 and rebuilt; surrendered July 1531 (Stow) or 1532. VCH: surrendered February 1532 and granted to Lord Audley in 1534; when the church was pulled down is not established by the sources read, so the end shown is the surrender.','friary','{"l": 75, "w": 24, "h": 16, "cloister": 32, "wall": "ragstone", "roof": "lead", "tower": {"w": 9, "h": 30}}','$[48].phases[0]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/holy-trinity-aldgate',1,'Duke''s Place mansion',1534,1544,NULL,NULL,NULL,0,NULL,'courtyard','{"l": 42, "w": 36, "h": 10, "range": 8, "wall": "ragstone", "roof": "tile"}','$[48].phases[1]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/st-bartholomew',0,'Priory church (surrendered 1539)',1123,1160,1543,'handover',NULL,0,'Surrendered in October 1539 (VCH). The nave was then demolished and the choir kept as the parish church (Great St Bartholomew); the sources do not give the year of demolition, so 1543 is a display boundary, not continued monastic life.','friary','{"l": 85, "w": 22, "h": 15, "cloister": 30, "wall": "ragstone", "roof": "lead", "tower": {"w": 9, "h": 26}}','$[49].phases[0]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/st-bartholomew',1,'Choir only (parish church)',1543,NULL,NULL,NULL,NULL,1,'The choir kept as the parish church: its east end is pinned to the priory church''s east end.','church','{"l": 38, "w": 22, "h": 15, "wall": "ragstone", "roof": "lead", "aisles": true, "eastEnd": 42.5}','$[49].phases[1]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/charterhouse',0,'Carthusian monastery (community disbanded 1538)',1371,1436,1546,'handover',NULL,0,'Founded 1371 on the plague cemetery of 1349; the cells took about 60 years to complete. Surrendered 10 June 1537 and formally disbanded 15 November 1538 (VCH). The buildings then stood, divided among Crown grantees, used as a royal storehouse from 1542 and largely derelict, until they were sold to Sir Edward North on 14 April 1546; the monastic community did not continue after 1538.','courtyard','{"l": 104, "w": 91, "h": 5, "range": 7, "wall": "ragstone", "roof": "tile"}','$[50].phases[0]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/charterhouse',1,'Mansion, later Sutton''s Hospital',1546,NULL,NULL,NULL,NULL,1,'Sir Edward North bought the site on 14 April 1546 and made a mansion of it; Sutton''s Hospital from 1611.','courtyard','{"l": 60, "w": 50, "h": 10, "range": 9, "wall": "ragstone", "roof": "tile"}','$[50].phases[1]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/savoy',0,'Savoy Palace',1246,1360,1381,'ruin',1509,0,'Peter of Savoy''s house from 1245–46; Lancastrian palace of the 1350s; burned 1381 and left a ruin.','courtyard','{"l": 85, "w": 60, "h": 13, "range": 11, "wall": "ragstone", "roof": "lead", "towers": 2, "placeholder": true}','$[51].phases[0]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/savoy',1,'Savoy Hospital',1509,1517,NULL,NULL,NULL,0,'Stow gives only ''about 1509''; the completion date was not verified.','courtyard','{"l": 85, "w": 55, "h": 11, "range": 10, "wall": "ragstone", "roof": "lead", "tower": {"w": 7, "h": 22}}','$[51].phases[1]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/guildhall',0,'Great Hall',1411,1440,NULL,NULL,NULL,0,'Begun 1411. The City of London gives 1411–1440 for the building, and the Gresham lecture a wider civic campaign of about 1411–1450 including the precinct. The hall is shown complete only at the end of the City''s range; its exact completion year is not recorded in these sources.','hall','{"l": 50, "w": 17.5, "h": 15, "wall": "ragstone", "roof": "lead", "pitch": 0.9, "endTowers": true}','$[52].phases[0]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/leadenhall',0,'Garner and market',1440,1455,NULL,NULL,NULL,0,'Simon Eyre''s quadrangle of the 1440s; damaged by fire in 1484.','courtyard','{"l": 68, "w": 58, "h": 11, "range": 9, "wall": "ragstone", "roof": "lead", "towers": 4}','$[53].phases[0]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/royal-exchange',0,'Gresham''s Exchange',1566,1568,NULL,NULL,NULL,0,'First brick 7 June 1566, slated November 1567; named ''Royal'' at Elizabeth''s visit of 23 January 1571.','courtyard','{"l": 62, "w": 52, "h": 12, "range": 9, "wall": "brick", "roof": "slate", "tower": {"w": 5, "h": 30}, "arcade": true}','$[54].phases[0]');
