INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/lambeth-palace',0,'Archbishop''s house and chapel',1200,1250,1490,'handover',NULL,0,'Archbishop Baldwin acquired the site in 1189–90; the new palace was begun under Archbishop Langton (1207–29) and the chapel appears to be of the mid 13th century (RCHME). The 1200 start and the 1250 completion are approximate display anchors, not documented dates.','courtyard','{"l": 60, "w": 45, "h": 9, "range": 9, "wall": "ragstone", "roof": "tile"}','$[60].phases[0]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/lambeth-palace',1,'Palace with Morton''s Tower',1490,NULL,NULL,NULL,NULL,1,'Morton''s Tower (the gatehouse) built by Cardinal Morton in 1490 (RCHME).','courtyard','{"l": 70, "w": 50, "h": 10, "range": 9, "wall": "brick", "roof": "tile", "towers": 2}','$[60].phases[1]');
INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('london/bermondsey-abbey',0,'Priory',1082,1140,1538,'demolished',NULL,0,'Founded in 1082 (Southwark Heritage). The 1140 completion and the 1538 demolition are not supported by a source read here: 1538 is the dissolution, and when the church was actually pulled down for Bermondsey House is not established.','friary','{"l": 80, "w": 24, "h": 15, "cloister": 32, "wall": "ragstone", "roof": "lead", "tower": {"w": 9, "h": 26}}','$[61].phases[0]');
