INSERT INTO "landmark_phase"("landmark_id","seq","label","year_from","year_built","year_to","end_kind","gone_by","continues","date_note","model_kind","model_params","origin_path") VALUES('stonehenge/durrington-timber-ring',0,'Timber ring of about 300 posts',-2530,-2520,-2481,'replaced',NULL,0,'Current Archaeology: the ring stood for at most about 50 years, its posts were removed and sockets filled before the henge bank (c. 2480-2450 BCE) covered them; when it went up is not directly dated. Display years 2530-2481 BCE so that it is gone when the henge begins (corrected after fact review glm-stonehenge-005).','timber-circle','{"rings": [{"r": 222, "count": 300, "d": 1, "h": 5, "hVar": 0.1}], "material": "timber"}','$[28].phases[0]');
