INSERT INTO "location"("id","name","kind","subtitle","scope_note","origin_lat","origin_lon","origin_note","lat_min","lat_max","lon_min","lon_max","x_min","x_max","z_min","z_max","timeline_start","timeline_end","initial_year","timeline_scale","config_json","origin_file") VALUES('barnet','Barnet, 1471','site','The ridge north of Chipping Barnet where Edward IV defeated the Earl of Warwick, 1400 – 1500','A landscape reconstruction of about 3 × 4 km from Chipping Barnet north through Hadley Green to Kitts End, built to show the ground of the Battle of Barnet (14 April 1471). The battle certainly happened somewhere along this stretch of road, but its exact position is disputed: the registered battlefield centres on Hadley Green, while the 2015–18 survey could not find the battlefield and judged that the ground around Kitts End fits the written sources better. Both areas are shown as shaded zones, not as a located site. The blocks of figures are abstract stand-ins on one modern interpretation: they do not show real numbers, real positions or individual people.',51.661,-0.199,'The middle of Hadley Green, on the old road north from Chipping Barnet (modern A1000), about 850 m north of Barnet church. Chosen because it lies between the two candidate battlefield areas and is the one open space that survives. Local coordinates are metres east (x) and south (z) of this point.',NULL,NULL,NULL,NULL,-1500.0,1500.0,-2400.0,1600.0,1400,1500,1471,'[{"year": 1400, "u": 0}, {"year": 1471, "u": 0.6}, {"year": 1500, "u": 1}]','{"terrain": {"base": 32.6, "hills": [{"name": "Hadley Green plateau", "lat": 51.6619, "lon": -0.20117, "height": 38.0, "sigma": 450}, {"name": "Chipping Barnet hilltop", "lat": 51.65426, "lon": -0.20407, "height": 34.0, "sigma": 380}, {"name": "Wood Street ridge", "lat": 51.65291, "lon": -0.21783, "height": 33.1, "sigma": 420}, {"name": "Kicks End Common plateau", "lat": 51.67224, "lon": -0.19538, "height": 30.7, "sigma": 380}, {"name": "Ganwick ridge", "lat": 51.68078, "lon": -0.19031, "height": 35.2, "sigma": 450}, {"name": "Hadley Common ridge (east of the church)", "lat": 51.66325, "lon": -0.18814, "height": 33.1, "sigma": 330}, {"name": "Kitts End north-west spur", "lat": 51.67988, "lon": -0.20914, "height": 14.0, "sigma": 350}, {"name": "Hadley Wood ridge", "lat": 51.67493, "lon": -0.18959, "height": 4.0, "sigma": 280}, {"name": "Spur south of Hadley Common", "lat": 51.65785, "lon": -0.18741, "height": 35.7, "sigma": 250}, {"name": "North-east rise", "lat": 51.68257, "lon": -0.17873, "height": 15.9, "sigma": 400}, {"name": "Hadley Common east rise", "lat": 51.66639, "lon": -0.17728, "height": 4.4, "sigma": 250}, {"name": "Ridge crest at the road fork (Hadley Highstone)", "lat": 51.6666, "lon": -0.1992, "height": 8.0, "sigma": 230}], "valleys": [{"name": "Monken Mead brook", "path": [[51.6655, -0.1935], [51.667, -0.1905], [51.6676, -0.1896], [51.6686, -0.1831], [51.6689, -0.1778], [51.6695, -0.1724]], "depth": 11.8, "sigma": 200}, {"name": "Green Brook (Pymmes Brook head)", "path": [[51.6605, -0.1894], [51.6599, -0.1817], [51.6613, -0.1746]], "depth": 8.9, "sigma": 220}, {"name": "Valley south-east of Hadley (towards Pymmes Brook)", "path": [[51.6575, -0.1935], [51.6555, -0.186], [51.653, -0.1775]], "depth": 24.2, "sigma": 300}, {"name": "Margery Mead head", "path": [[51.6696, -0.2076], [51.6709, -0.2103], [51.6732, -0.2139], [51.6732, -0.2209]], "depth": 0.6, "sigma": 300}, {"name": "Fall to the Dollis Brook valley (south)", "path": [[51.644, -0.225], [51.644, -0.17]], "depth": 6.4, "sigma": 450}, {"name": "Fall to the Mimmshall Brook streams (west)", "path": [[51.65, -0.2235], [51.684, -0.2235]], "depth": 3.2, "sigma": 500}], "eyots": [], "note": "A flat-topped ridge of pebble gravel over London Clay, about 120–135 m above sea level, runs north from Chipping Barnet through Hadley Green towards Potters Bar; the ground falls west to the Mimmshall Brook streams (about 90–100 m) and east into the Monken Mead and Pymmes Brook valleys (down to about 70 m). Heights here are on a local datum: add 64 m to get an approximate height above sea level, so the lowest ground in the scene is about 5 m and the plateau about 65–72 m. The hills and valleys are smooth analytic shapes fitted to a coarse (250 m) grid of modern elevations, with an average error of about 5 m; they are not a survey, and the modern elevation model includes trees, buildings, the golf course and the 1823 cutting on Barnet Hill. The broad pattern of relief is thought to be much as it was in 1471, but no fine detail (ditches, banks, ponds, marshy patches) is modelled.", "sources": ["bar-eudem-elevation", "bar-vch-middx-monken-hadley-intro", "bar-vch-middx-south-mimms-intro", "bar-vch-herts-barnet", "bar-barnet-battlefield-project-2015-2018", "bar-osm-overpass"]}, "polygons": {"barnet-town": [[51.651, -0.1976], [51.6524, -0.1998], [51.6524, -0.203], [51.6536, -0.203], [51.654, -0.2026], [51.6562, -0.2029], [51.6574, -0.2022], [51.6572, -0.2004], [51.656, -0.2008], [51.6542, -0.2004], [51.6534, -0.1992], [51.6519, -0.1966]], "registered-area-approx": [[51.6588, -0.2035], [51.6625, -0.208], [51.6668, -0.206], [51.6672, -0.2], [51.6668, -0.1935], [51.665, -0.1895], [51.6608, -0.1905], [51.6588, -0.1975]], "kicks-end-area": [[51.6672, -0.1996], [51.67, -0.203], [51.674, -0.2052], [51.6752, -0.1975], [51.6738, -0.1912], [51.67, -0.1888], [51.6674, -0.1925]], "kicks-end-common": [[51.6668, -0.1988], [51.669, -0.199], [51.6713, -0.2004], [51.6728, -0.2028], [51.6736, -0.1975], [51.674, -0.1922], [51.67, -0.1953], [51.6672, -0.1976]], "hadley-green": [[51.6589, -0.2012], [51.6602, -0.2016], [51.663, -0.201], [51.6631, -0.1985], [51.6616, -0.1962], [51.6606, -0.1974], [51.659, -0.1996]], "chase-west-edge": [[51.664, -0.194], [51.6668, -0.1968], [51.67, -0.1942], [51.6745, -0.1908], [51.679, -0.1868], [51.679, -0.179], [51.67, -0.179], [51.6625, -0.18], [51.6622, -0.19]]}, "woodland": {"hedgerowTrees": true, "note": "Low and steady by assumption. The written record points to little woodland on this side of South Mimms and to open pasture with scattered trees along the western edge of Enfield Chase, but the earliest map evidence is from 1594–1701, not the 15th century. The figure is illustrative, tree positions are generated, and no individual wood is mapped (an ''old wood'' on the Old Fold estate is documented but unlocated)."}, "atmosphere": {"mist": {"from": 1471, "to": 1471, "density": 0.004, "height": 45, "base": 70, "color": "#ece6da"}, "sunElevation": 6, "sunAzimuth": 75, "exposure": 0.9}, "views": [{"id": "south", "name": "Both lines and the road fork from the south", "position": [-60, 1250.0, 1500], "target": [-60, 66.0, -450], "scope": "overview"}, {"id": "hadley-green", "name": "Hadley Green looking north", "position": [-40, 150.7, 430], "target": [0, 62.6, -420], "scope": "overview"}, {"id": "warwick-side", "name": "From Warwick''s presumed side, looking south", "position": [-200, 134.4, -760], "target": [-20, 66.7, -20], "scope": "overview"}, {"id": "road-fork", "name": "The road fork", "position": [150, 127.6, -330], "target": [-5, 62.4, -640], "scope": "overview"}, {"id": "low-green", "name": "Low across the green", "position": [-70, 69.0, 90], "target": [-110, 66.5, -290], "scope": "overview"}]}','locations/barnet/site.json');
INSERT INTO "location"("id","name","kind","subtitle","scope_note","origin_lat","origin_lon","origin_note","lat_min","lat_max","lon_min","lon_max","x_min","x_max","z_min","z_max","timeline_start","timeline_end","initial_year","timeline_scale","config_json","origin_file") VALUES('brentford','Brentford and the Thames ford','site','A river crossing west of London, 950 – 1100 CE, and the fight of 1016','About 3 × 2.4 km around the meeting of the River Brent and the Thames, about 15 km west of London Bridge. This is a reconstruction of a landscape, not of a battle. In 1016 the Anglo-Saxon Chronicle says only that King Edmund ''went over at Brentford'', fought the Danish army and put it to flight, and that many of the English drowned through their own carelessness, having gone ahead of the army for plunder. Where the crossing was, which bank the fighting was on, how many fought and how the day went are not recorded, and no archaeology of the battle is known. No trace of a late Saxon settlement has been excavated at Brentford either. The river, banks and road are placed from the modern map and the county history; the houses, fields, figures and shaded areas are labelled guesses.',51.4815,-0.302,'A point on the low ground called Old England, between the lower Brent and the Thames (the site of the later Brentford Dock), chosen because the county history places the probable Thames ford here. Local coordinates are metres east (x) and south (z) of this point. It is a convenient centre for the model, not a located battlefield.',NULL,NULL,NULL,NULL,-1500.0,1500.0,-1200.0,1200.0,950,1100,1016,'[{"year": 950, "u": 0}, {"year": 1016, "u": 0.5}, {"year": 1100, "u": 1}]','{"river": {"centreline": [[51.4526, -0.3033, 65, 65, 0], [51.4582, -0.3081, 65, 65, 0], [51.4603, -0.3139, 65, 65, 0], [51.4622, -0.3172, 65, 65, 0], [51.4654, -0.3208, 70, 70, 0], [51.4685, -0.3197, 90, 70, 0], [51.4706, -0.3189, 90, 70, 0], [51.4722, -0.3153, 75, 75, 0], [51.4746, -0.3087, 75, 75, 0], [51.476, -0.3064, 75, 80, 0], [51.4779, -0.3049, 80, 80, 0], [51.4794, -0.3033, 85, 85, 0], [51.4811, -0.3011, 90, 85, 0], [51.4829, -0.2991, 95, 90, 0], [51.484, -0.2973, 105, 100, 0], [51.4852, -0.2956, 110, 105, 0], [51.486, -0.2931, 110, 105, 0], [51.4868, -0.2891, 95, 90, 0], [51.487, -0.2882, 90, 85, 0], [51.4857, -0.2827, 85, 85, 0], [51.483, -0.278, 80, 80, 0], [51.4796, -0.2755, 80, 80, 0], [51.4749, -0.2723, 80, 80, 0], [51.4715, -0.2662, 80, 80, 0]], "northBankSetback": [{"year": 950, "value": 0}, {"year": 1100, "value": 0}], "southEmbankment": [{"year": 950, "value": 0.45}, {"year": 1100, "value": 0.45}], "note": "The centreline follows the modern Thames (OpenStreetMap) from Richmond to Mortlake; ''left'' is the Middlesex bank (Isleworth, Syon, Brentford) and ''right'' the Surrey bank (Kew). The course of the river about 1000 is not known in detail and is assumed to be close to the modern one. Half-widths are a modelling assumption: the modern channel is roughly 110 to 150 m wide in the Syon reach and about 240 m from bank to bank across the aits (estimated from the modern map, not surveyed), and it is drawn somewhat wider here to stand for an unembanked river with shelving gravel foreshores. No measured width or depth for the 11th century was found. A writer of 1695 is quoted as saying the Thames at Brentford was ''not above 3ft deep at low water''; that is 700 years later and is the only depth figure found. Whether and how strongly the reach was tidal about 1000 could not be established from the sources read (it is tidal today; Iron Age and Romano-British hut floors on the Brentford foreshore now lie below high-tide level, so the river has risen since). The model shows one water level. No bank is embanked in this period: the two keyframe sets are constant, and the right-bank value of 0.45 is a rendering choice that gives low, damp but mostly firm ground on the Kew side instead of open creeks; it does not represent a flood bank.", "sources": ["bre-osm-nominatim", "bre-vch-mdx7-comms", "bre-bclhs-brentford-bridge", "bre-vch-mdx1-iron-age", "bre-vch-mdx3-heston-isleworth", "bre-tdp-foreshore-pioneers", "bre-tdp-brentford-aits"]}, "terrain": {"hills": [], "valleys": [{"name": "River Brent", "path": [[51.4925, -0.325], [51.4913, -0.3206], [51.4882, -0.3215], [51.487, -0.3179], [51.4853, -0.3136], [51.4838, -0.3099], [51.4823, -0.3124], [51.4809, -0.3111], [51.4819, -0.3071], [51.4825, -0.303], [51.4829, -0.3004]], "depth": 5, "sigma": 110}], "eyots": [{"name": "Gravel shoal at the later Lot''s Ait", "lat": 51.4847, "lon": -0.2983, "height": 0.6, "sigma": 14, "stretch": 5, "bearing": 53, "shoal": true}, {"name": "Gravel shoal at the later Brentford Ait (upper)", "lat": 51.4853, "lon": -0.2962, "height": 0.6, "sigma": 16, "stretch": 6, "bearing": 53, "shoal": true}, {"name": "Gravel shoal at the later Brentford Ait (lower)", "lat": 51.4866, "lon": -0.2925, "height": 0.6, "sigma": 16, "stretch": 6, "bearing": 53, "shoal": true}], "note": "Relief is the engine''s analytic approximation: ground rising gently from the Middlesex bank (the county history describes land ''rising gently from the Thames'' to about 23 m some 2 km north), a low flat Surrey bank, and a shallow valley for the Brent with alluvium at its mouth. It is not a survey or borehole model, and the Syon bank west of the Brent is in reality lower and flatter than drawn. The Brent valley follows the modern river and canal line, which was straightened below Brentford Bridge between 1699 and 1760; its medieval meanders and its second mouth (the later dock stood on an island between the Thames and two mouths of the Brent) are not modelled. The three eyots stand at the positions of today''s Lot''s Ait and Brentford Ait. Those islands are later forms (osiers were grown on aits here by 1397; nothing earlier was found), so low gravel shoals standing just above the water, drawn long and narrow along the stream, are a guess at what was there about 1000; their size and height are not recorded. Brentford Ait lay in Surrey and Lot''s Ait in Ealing parish, which hints at which bank each grew from.", "sources": ["bre-vch-mdx7-intro", "bre-vch-mdx3-heston-isleworth", "bre-vch-mdx7-econ", "bre-wikipedia-brentford-dock", "bre-wikipedia-brentford-ait", "bre-wikipedia-lots-ait", "bre-osm-nominatim"]}, "polygons": {}, "woodland": {"note": "Illustrative only. Domesday Book (1086) records woodland for 500 pigs at Isleworth and for 50 at Hanwell, so the manors still held woodland, but it does not say where; it is more likely to have been on the clay to the north than on the gravel by the river (an inference, not a source statement). The slight fall across the window is an assumption, and the percentages are not measurements."}, "views": [{"id": "overview", "name": "Whole site", "position": [100, 1250, 1900], "target": [0, 0, -50], "scope": "overview"}, {"id": "ford-middlesex", "name": "The ford from the Middlesex bank", "position": [-330, 60, -110], "target": [60, 2, 190], "scope": "overview"}, {"id": "ford-surrey", "name": "The ford from the Surrey bank", "position": [330, 55, 400], "target": [-80, 2, 80], "scope": "overview"}, {"id": "brent-mouth", "name": "The mouth of the Brent", "position": [450, 140, 60], "target": [-100, 0, -170], "scope": "overview"}, {"id": "water-low", "name": "Low over the water", "position": [215, 6, -170], "target": [-14, 3, 133], "scope": "overview"}]}','locations/brentford/site.json');
INSERT INTO "location"("id","name","kind","subtitle","scope_note","origin_lat","origin_lon","origin_note","lat_min","lat_max","lon_min","lon_max","x_min","x_max","z_min","z_max","timeline_start","timeline_end","initial_year","timeline_scale","config_json","origin_file") VALUES('london','London and the Thames','site','One place within the land that became England, 4000 BCE – 1625 CE','This is a single anchor location: about 4.8 × 3 km around the City of London, Southwark and Westminster. It is not a visualisation of England as a whole. Most of the country changed on different timetables.',51.509,-0.0865,'North end of medieval London Bridge (near St Magnus the Martyr). Local coordinates are metres east (x) and south (z) of this point.',NULL,NULL,NULL,NULL,-3300.0,1500.0,-1500.0,1500.0,-4000,1625,NULL,'[{"year": -4000, "u": 0}, {"year": -800, "u": 0.06}, {"year": 43, "u": 0.14}, {"year": 410, "u": 0.36}, {"year": 1066, "u": 0.56}, {"year": 1485, "u": 0.8}, {"year": 1625, "u": 1}]','{"river": {"centreline": [[51.4805, -0.127, 150, 130, 0.2], [51.4875, -0.1265, 150, 130, 0.2], [51.4945, -0.1235, 160, 130, 0.2], [51.5008, -0.121, 230, 130, 0.3], [51.5062, -0.1195, 260, 130, 0.3], [51.5086, -0.1165, 190, 130, 0.4], [51.5098, -0.11, 165, 135, 0.6], [51.5097, -0.104, 160, 140, 0.8], [51.5088, -0.0943, 120, 140, 1], [51.5079, -0.0877, 125, 140, 1], [51.5062, -0.076, 130, 140, 0.8], [51.5045, -0.064, 140, 140, 0.5], [51.504, -0.052, 140, 140, 0.5]], "northBankSetback": [{"year": -4000, "value": 110}, {"year": 50, "value": 110}, {"year": 63, "value": 104}, {"year": 102, "value": 95}, {"year": 250, "value": 75}, {"year": 1000, "value": 72}, {"year": 1050, "value": 64}, {"year": 1200, "value": 42}, {"year": 1350, "value": 18}, {"year": 1450, "value": 6}, {"year": 1500, "value": 0}], "southEmbankment": [{"year": -4000, "value": 0}, {"year": 50, "value": 0.08}, {"year": 200, "value": 0.25}, {"year": 450, "value": 0.12}, {"year": 1000, "value": 0.2}, {"year": 1200, "value": 0.5}, {"year": 1400, "value": 0.85}, {"year": 1600, "value": 1}], "inlets": [{"id": "queenhithe-inlet", "name": "Queenhithe dock", "landmark": "queenhithe", "lat": 51.5106, "lon": -0.095, "bearing": 191, "width": 34, "from": 970, "to": null, "evidence": "attested-documentary", "confidence": "medium", "uncertainty": "That Queenhithe stayed an open inlet while the frontage either side was embanked (1021, 1045 and later) is documented; its plan here is not surveyed. The head is put at the model''s waterline of about 1000 (where the landmark stands), the 34 m width is the dock model''s, the axis is set square to the modelled bank, and the inlet''s length is simply wherever the modelled bank stands in each year.", "sources": ["lamas-saxon-origins-queenhithe-r", "bho-stow-queene-hith-warde"]}, {"id": "billingsgate-inlet", "name": "Billingsgate dock", "landmark": "billingsgate", "lat": 51.50922, "lon": -0.0843, "bearing": 185, "width": 30, "from": 990, "to": null, "evidence": "attested-documentary", "confidence": "low", "uncertainty": "Billingsgate is documented as a dock (a water gate with a market) from about 1000 to beyond 1625; its dimensions and the line of its sides are not. The head is put at the model''s waterline of about 990 at the foot of the lane to the dock, the 30 m width is the dock model''s, the axis is set square to the modelled bank, and the inlet''s length is wherever the modelled bank stands in each year.", "sources": ["bho-stow-billinsgate-warde", "mola-medieval-c1066c1500-research-framework"]}], "note": "The 1625 bank lines are approximated from the modern river with the Victorian embankments removed. Excavated Roman quays (tree-ring dates 52, 63, c. 70, 102 CE and on to the mid 3rd century) advanced the north bank by roughly 35 m; the Roman riverside wall on the Thames Street line then stayed the landward limit, and the remaining ground was won piecemeal between about 1000 and 1500. No verified figure was found for the medieval advance, so the roughly 110 m total and its timing are modelling assumptions. The prehistoric and Roman south bank is modelled as tidal marsh with channels and gravel eyots (the reach was tidal by the Middle to Late Bronze Age); channel positions are illustrative, not mapped.", "sources": ["london-archaeologist-brigham-watson-regis-house", "gresham-discovering-port-roman-london", "britannia-brigham-late-roman-waterfront", "rfla-roman-ad-43-410", "history-london-port-roman-london-secondary", "rfla-prehistory-research-framework-london", "gresham-early-river-thames-iron", "southwark-council-archaeology-southwark-prehistoric", "london-museum-timeline-roman-london", "lamas-saxon-origins-queenhithe-r", "mola-medieval-c1066c1500-research-framework", "hrp-tower-london-historic-environment", "bho-stow-queene-hith-warde"]}, "terrain": {"hills": [{"name": "Cornhill", "lat": 51.5132, "lon": -0.085, "height": 5, "sigma": 360}, {"name": "Ludgate Hill", "lat": 51.5138, "lon": -0.099, "height": 5, "sigma": 330}, {"name": "Tower Hill", "lat": 51.5095, "lon": -0.0765, "height": 1, "sigma": 200}, {"name": "Thorney Island", "lat": 51.4995, "lon": -0.1275, "height": 1.2, "sigma": 170}], "valleys": [{"name": "Walbrook", "path": [[51.519, -0.0865], [51.516, -0.0885], [51.5135, -0.09], [51.5115, -0.091], [51.5098, -0.0915]], "depth": 6, "sigma": 70, "fill": [{"year": 50, "value": 0}, {"year": 400, "value": 0.2}, {"year": 1300, "value": 0.35}, {"year": 1500, "value": 0.45}, {"year": 1600, "value": 0.5}]}, {"name": "Fleet", "path": [[51.523, -0.1055], [51.518, -0.1052], [51.514, -0.1047], [51.5112, -0.1043]], "depth": 8, "sigma": 85}], "eyots": [{"name": "Southwark north island", "lat": 51.5055, "lon": -0.09, "height": 2.4, "sigma": 170}, {"name": "Southwark south island", "lat": 51.5028, "lon": -0.0925, "height": 2.2, "sigma": 150}, {"name": "Horsleydown eyot", "lat": 51.5035, "lon": -0.0765, "height": 2, "sigma": 160}, {"name": "Bermondsey eyot", "lat": 51.4985, "lon": -0.076, "height": 2.4, "sigma": 220}], "note": "Relief is an analytic approximation (two low gravel hills divided by the Walbrook, the Fleet valley to the west, a low marshy south bank) at true vertical scale. It is not derived from a survey or borehole model. Corrected against the 2026 LIDAR comparison (research/lidar.md): Tower Hill reduced to 1 m (no separate crest; it is the end of the Cornhill spur) and the Walbrook valley filled to no more than half its depth by 1600 (it is still about 3.5 m deep today). The City''s absolute height has not been lowered: that finding is unverified (docs/CORRECTIONS.md).", "sources": ["rfla-prehistory-research-framework-london", "gresham-early-river-thames-iron", "southwark-council-archaeology-southwark-prehistoric", "london-museum-timeline-roman-london", "gresham-discovering-port-roman-london", "london-archaeologist-brigham-watson-regis-house", "southwark-council-archaeology-southwark-roman", "rfla-roman-ad-43-410"]}, "polygons": {"walled-city": [[51.5084, -0.0768], [51.51, -0.0762], [51.5135, -0.0764], [51.515, -0.079], [51.5158, -0.0812], [51.5172, -0.085], [51.5177, -0.0886], [51.518, -0.0932], [51.5182, -0.0963], [51.5166, -0.0968], [51.516, -0.099], [51.5154, -0.1012], [51.5139, -0.1023], [51.5105, -0.1028], [51.5099, -0.096], [51.5091, -0.09], [51.5087, -0.083]]}, "woodland": {"note": "Illustrative trend only: closed woodland in the early Neolithic, progressive clearance from the Bronze Age, a largely open farmed landscape by the late Iron Age, some regeneration after the Roman period. The percentages are not measurements."}, "district": {"name": "London Bridge bridgehead", "bounds": {"xMin": -330, "xMax": 240, "zMin": -260, "zMax": 420}, "note": "The realism benchmark: the river crossing and both bridgeheads, modelled in more detail than the rest of the scene. Everything outside this rectangle is a schematic overview."}, "views": [{"id": "overview", "name": "Whole area", "position": [-500, 1900, 2900], "target": [-700, 0, -150], "scope": "overview"}, {"id": "city", "name": "City from the south", "position": [-250, 520, 1350], "target": [-250, 0, -350], "scope": "overview"}, {"id": "westminster", "name": "Westminster & Strand", "position": [-1900, 520, 1900], "target": [-2500, 0, 500], "scope": "overview"}, {"id": "bridge", "name": "Bridge from Bankside", "position": [-520, 95, 330], "target": [-20, 12, 110], "scope": "district"}, {"id": "bridge-low", "name": "Bridge from the water", "position": [240, 14, 210], "target": [-60, 14, 120], "scope": "district"}, {"id": "bridgehead", "name": "North bridgehead", "position": [150, 70, 130], "target": [-10, 8, -40], "scope": "district"}]}','locations/london/site.json');
INSERT INTO "location"("id","name","kind","subtitle","scope_note","origin_lat","origin_lon","origin_note","lat_min","lat_max","lon_min","lon_max","x_min","x_max","z_min","z_max","timeline_start","timeline_end","initial_year","timeline_scale","config_json","origin_file") VALUES('stonehenge','Stonehenge and its landscape','site','From the first earthworks to the Jacobean antiquaries, 4000 BCE to 1625 CE','A 6.4 by 5 km piece of the Stonehenge World Heritage landscape, from 4000 BCE to 1625 CE, with the sarsen circle at the origin. Two levels of detail: the whole landscape is a schematic overview (barrows, cursus, henges, hillfort and town are placed from mapped outlines and published dates, but their form is generic), while the ''district'' round the stones (about 800 by 650 m) has stone-by-stone megaliths from a catalogue, the ditch and bank, the Aubrey Holes, the first stretch of the Avenue and the Heel Stone. No feature is shown before its date, and where a date is a range or a model the landmark says so. The state of the stones before the first drawings (de Heere, 1570s) is mostly undated: which stones stood, leant or lay in 1625 is inferred, not recorded. Height comes from a modern LIDAR surface with modern works removed, with the ditch and Avenue ditches cut back in on their dates. Ground cover, trees and house positions are reconstruction. The solstice episodes mark the sunrise and sunset directions with overlay lines and discs; the scene''s one fixed sun is not moved to the solstice. Amesbury''s outline and the Durrington settlement area are schematic envelopes, not surveyed boundaries.',51.17888,-1.82619,'FINAL. Centre of the sarsen circle to within ~3 m (geography research: circle fitted to OSM-mapped uprights 51.178859, -1.826208; EH 2010 survey NGR SU 12244219; the stone catalogue''s fitted centre 51.178868, -1.8261962). Megalith landmarks are anchored at the catalogue''s fitted centre. Local x = metres east, z = metres south.',NULL,NULL,NULL,NULL,-2700.0,3700.0,-2800.0,2200.0,-4000,1625,-2400,'[{"year": -4000, "u": 0}, {"year": -3700, "u": 0.05}, {"year": -3000, "u": 0.24}, {"year": -2500, "u": 0.5}, {"year": -2000, "u": 0.7}, {"year": -1500, "u": 0.84}, {"year": 1, "u": 0.91}, {"year": 1000, "u": 0.955}, {"year": 1625, "u": 1}]','{"terrain": {"base": 39.71, "slope": {"bearing": 167.7, "gradient": 0.00174}, "hills": [{"name": "King Barrow Ridge (central: New King Barrows; the Avenue climbs it)", "lat": 51.18021, "lon": -1.80712, "height": 13.9, "sigma": 346}, {"name": "King Barrow Ridge (south: Coneybury Hill)", "lat": 51.1732, "lon": -1.81079, "height": 26.2, "sigma": 454}, {"name": "Normanton Down ridge (Bush Barrow and the Normanton Down barrows)", "lat": 51.17028, "lon": -1.83839, "height": 11.3, "sigma": 215}, {"name": "North-west upland (beyond the west end of the Greater Cursus / Lesser Cursus)", "lat": 51.19414, "lon": -1.85129, "height": 15.8, "sigma": 696}, {"name": "Larkhill rise (high ground north of Larkhill)", "lat": 51.20535, "lon": -1.816, "height": 38.6, "sigma": 800}, {"name": "High ground north-west of Durrington Walls", "lat": 51.19238, "lon": -1.79331, "height": 43.7, "sigma": 648}, {"name": "West upland (Winterbourne Stoke Down)", "lat": 51.17649, "lon": -1.84735, "height": 21.2, "sigma": 436}, {"name": "South-west upland (Wilsford Down side)", "lat": 51.16776, "lon": -1.86606, "height": 17.9, "sigma": 311}, {"name": "South ridge (Normanton / Lake Down side)", "lat": 51.1633, "lon": -1.81414, "height": 34.8, "sigma": 318}, {"name": "Upland south-east of Amesbury", "lat": 51.16237, "lon": -1.78109, "height": 28.5, "sigma": 277}, {"name": "Vespasian''s Camp spur (hill-fort promontory above the Avon)", "lat": 51.17482, "lon": -1.79104, "height": 24.7, "sigma": 247}, {"name": "Stonehenge Down knoll (flattens the ground under the stones)", "lat": 51.1787, "lon": -1.82535, "height": 5.5, "sigma": 124}], "valleys": [{"name": "River Avon valley (broad flood-plain and valley flanks)", "path": [[51.19096