INSERT INTO "place"("id","location_id","local_id","name","lat","lon","country","kind","evidence","confidence","summary","uncertainty","site_id","origin_file","origin_path") VALUES('england-wales/berwick','england-wales','berwick','Berwick-upon-Tweed',55.77,-2.005,'england','port','attested-documentary','medium','A Scottish town for most of the Middle Ages, finally taken by England in 1482. It is listed under England only for that last phase.','1296, 1318, 1482 and the ramparts (begun 1558, stopped 1569) are English Heritage''s dates. The 1120 start as a royal burgh is from memory.',NULL,'national/places.json','$[123]');
