INSERT INTO "place"("id","location_id","local_id","name","lat","lon","country","kind","evidence","confidence","summary","uncertainty","site_id","origin_file","origin_path") VALUES('england-wales/battle-dyrham','england-wales','battle-dyrham','Battle of Dyrham',51.489,-2.372,'england','battle','attested-documentary','low','The Anglo-Saxon Chronicle says the West Saxons killed three British kings here and took Gloucester, Cirencester and Bath.','Written down three centuries later; many historians doubt the details. Location follows the place-name. Dates are supported here only by Wikipedia, which is a lead rather than verification.',NULL,'national/places.json','$[150]');
