INSERT INTO "stone"("id","location_id","local_id","set_name","type","role","az","r","w","t","h","built","hypothetical","state1625","evidence1625","state_today","notes","extra_json","origin_file","origin_path") VALUES('stonehenge/152','stonehenge','152','trilithons','sarsen','lintel',124.5,6.43,4.9,1.4,0.7,'standing',0,'standing','Standing (in place) in 1625: Stukeley (1720s) records trilithons 51-52 and 53-54 with their impost entire; they have stood continuously (Stones of Stonehenge).','standing','Weight above ground 11.73 t (Stones of Stonehenge); length/width from lintel 156 mortise spacing (3.25 m) and Long 1876 (16-17 ft lintels); thickness/depth estimated from weight, depth not measured. Centre of the lintel placed at the middle of the pair.','{"face": 319.9, "on": ["51", "52"], "curved": false, "dressed": true, "tenons": true}','locations/stonehenge/stones.json','$.stones[122]');
